#!/usr/bin/env python3
"""
rtl_hygiene_lint.py — General-purpose RTL hygiene checker.

Deterministic Python-based lint that catches 7 general bug classes found
across IC designs (learned from <half-duplex-tester> debug 2026-04-16; rule 5
added from the VerilogEval-v2 v0.1.10 tuning loop 2026-05-27; rules 6-7 from the
v0.1.24/v0.1.25 fail-case loops 2026-05-27/28):

  1. Declared-but-undriven wire
     (e.g., `wire ch_wake_event;` but never on LHS of `assign` or instance output)
  2. Declared-but-unread reg
     (e.g., `reg [7:0] resp_crc;` but never appears on RHS)
  3. Case/if enumeration coverage
     (e.g., `case (x) 8'h70: ... 8'h72: ... endcase` with no `default`, missing
      values that are actually generated by producer)
  4. Pulse-to-state without latch
     (e.g., `start <= 1'b1;` in one always block, consumed by another FSM that
      only looks at `start` during a specific state → pulse may be swallowed)
  5. Reset-less registered output with no power-up initializer
     (e.g., `output reg q;` clocked by `<= d` with no reset and no `= 0` →
      powers up as X; deterministic references expect 0 at t=0)
     v0.1.24: `--fix` REPAIRS this deterministically in-place (inserts
     `initial <reg>=0;`), and now also covers an internal reg that drives an
     output via a continuous assign (Prob053-class). The lesson is enforced by
     the tool, not by a caller/prompt that can forget or be told to ignore it.
  6. Incomplete sensitivity list
     (e.g., `always @(a) if (clock) p<=a;` misses clock-edge updates → use `@(*)`)
  7. Vector self-shift fold
     (e.g., `in | {in[98:0],1'b0}` — the unshifted operand re-folds the boundary
      bit so the padded edge bit is NOT 0; shift BOTH operands inside the concat)
  8. SV reserved-word identifier (v0.1.38, from the close-loop sweep)
     iverilog 12 treats `packed`, `unique`, `priority`, `final`, `chandle`,
     `null`, `unique0` as reserved even outside their reserved contexts. Using
     any of these as a user identifier (variable, port, label) raises a
     useless `syntax error near …` with no line. Detect at lint time and
     suggest a `_val` / `_result` suffix. Chip-AGNOSTIC.
  9. Wire-driven-by-input read inside a clocked block (v0.1.38)
     `wire X = f(input_port);` followed by `always @(posedge clk) ... X ...`
     reads X at the same simulation instant as the clock edge — TB sees X
     evaluated with PRE-edge input values (one-cycle skew). The fix is to
     inline the expression inside the always block (NBA RHS pre-fetch
     semantics) OR pre-register the input. Chip-AGNOSTIC sequential hazard.
  10. Power-up determinism for INTERNAL regs in reset-less modules (v0.1.38)
     The existing rule 5 covers registered OUTPUT ports and an internal reg
     that directly drives an output via `assign out = q`. v0.1.38 extends
     `--fix` to ALSO cover ALL internal `reg` declarations in reset-less
     modules — the X-propagation through internal pipeline regs at t=0
     corrupts the output even when the output itself is initialized. Same
     conservative gate (no reset port). Chip-AGNOSTIC.
     v0.1.39 honesty correction (audit Finding 3): the v0.1.38 release
     note claimed "3 samples picked up additional initial blocks". The
     actual broader corpus sweep (362 reference samples) shows the case-c
     extension fires on ~42 samples (~11.6%). The behavior is unchanged:
     `initial X = 0;` insertion only, which preserves all functional
     behavior (steady-state semantics are independent of t=0 power-up
     value); idempotent re-runs add nothing. Zero functional regressions
     across the 42 — the safety claim holds; only the count was wrong.
  11. Unguarded simulation-only immediate assertion (v0.1.61, from the CVDP
     v0.1.59 Shape-D run). An immediate `assert (cond) else $error(...);` is
     simulation-only; yosys/DC reject it (yosys: `syntax error near else`).
     CVDP's assertion-injection task (`priority_encoder_8x3`) — and the
     benchmark's OWN provided module — shipped it unguarded, FAILing the
     synth gate. `--fix` fences it with `// synthesis translate_off …
     translate_on` (yosys/DC skip it; iverilog/cocotb keep it live). Safe,
     whole-line-only, idempotent, chip-AGNOSTIC.
  12. Reset-boundary residual level-enable write (v1.0.76, ORGANIC #723)
     A clocked register that a reset CLEARS to 0 and then updates under a
     purely LEVEL-sensitive enable that traces to a TOP-LEVEL INPUT, with NO
     registered armed/settle/valid-after-reset qualifier, has the
     stale-enable-post-reset-write hole: a held-high enable can perform a
     transfer on the FIRST post-reset clock edge, breaking the post-reset
     invariant. Motivating real case: a `ping_pong_buffer` async-reset test
     failed because a held-high `write_enable` transferred immediately after
     reset release; the fix was a registered 2-cycle "armed" guard. Advisory
     WARN. Conservative: the ubiquitous `if(!rst_n) x<=0; else x<=d;`
     (unconditional else) does NOT fire; an INTERNAL-enable counter does NOT
     fire; a design that already carries an armed/settle qualifier does NOT
     fire. chip-AGNOSTIC: pure SV structure.
  13. Multidriven register (v1.0.80, ORGANIC #740 G4)
     A reg written from >1 always block in a racing clocking domain — the
     `verilator -Wall` MULTIDRIVEN class made plugin-native. FIRE (WARN) on
     DIFFERENT clock/edge domains, or on a SAME-clock pair where one block
     reset-clears the reg and another writes it UNCONDITIONALLY (both fire on a
     reset edge → last-write-wins race). Does NOT fire on a single always block,
     on a reset-COMPLEMENTARY same-clock split (`if(rst)`/`if(!rst)`), or on
     disjoint bit-slice writers. Advisory WARN; chip-AGNOSTIC structural parse.

Usage:
    python3 rtl_hygiene_lint.py <files.v|.sv ...>
    python3 rtl_hygiene_lint.py --json <out.json> <files.v|.sv ...>

Exit codes:
    0 = no findings
    1 = findings issued (see stdout / JSON)
    2 = parse error

Works with plain regex + optional pyslang (more accurate) if installed.
No external tool dependencies required for the regex path.

Generality: applies to ANY Verilog/SystemVerilog design. Finds bugs #1, #2,
#7, #10 from the <half-duplex-tester> debug session using only syntax patterns.
"""
from __future__ import annotations
import argparse
import json
import os
import re
import sys
from dataclasses import dataclass, asdict
from pathlib import Path
from typing import List, Dict, Set, Tuple, Optional

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import _provenance as _prov  # noqa: E402  (ORGANIC #770)
from _atomic_artefact import write_text as atomic_write_text  # vibe-ic#1082 (helper from PR #1094)


@dataclass
class Finding:
    file: str
    line: int
    severity: str  # ERROR / WARN / INFO
    rule: str
    symbol: str
    message: str
    # ORGANIC #770 round-2 — provenance/confidence gate. A finding may HARD-BLOCK
    # (contribute to rc=1) only when block_eligible. A finding derived from an
    # UNCORROBORATED structural heuristic (a level-enable guess the RTL does not
    # back, a dead-reg inference the RTL CONTRADICTS by being a cross-domain sync
    # flop) is ADVISORY (reported, never a hard veto). Default True (fail-closed:
    # every existing rule keeps its historical blocking power unless a rule
    # explicitly downgrades a specific finding via _advisory()).
    block_eligible: bool = True
    advisory_note: str = ""


def _advisory(f: Finding, provenance: str, corroboration: str) -> Finding:
    """ORGANIC #770 — route ONE finding through the shared provenance layer.

    Returns the SAME Finding with block_eligible / advisory_note set per the
    single block-decision rule in _provenance.is_block_eligible. A finding that
    is downgraded is also demoted to INFO severity so it never trips the
    `warn > 0` exit condition — it stays in the report as an advisory line.
    chip-AGNOSTIC: no design/vendor literal, pure decision plumbing."""
    f.block_eligible = _prov.is_block_eligible(provenance, corroboration)
    if not f.block_eligible:
        f.advisory_note = _prov.advisory_reason(provenance, corroboration)
        f.severity = 'INFO'
    return f


# ---------------------------------------------------------------------------
# Tokenization (comment stripper + simple lexer good enough for our patterns)
# ---------------------------------------------------------------------------
def strip_comments(src: str) -> str:
    """Remove // line comments and /* block */ comments, preserving newlines and
    byte offsets (comments → spaces). STRING-AWARE (ORGANIC #843 round-3,
    Step-2.7): a `//` or `/*` INSIDE a double-quoted string literal is NOT a
    comment, so the string's bytes are copied verbatim and never trigger a
    comment scan — previously a `/*` inside a string truncated the whole
    remaining source (the string-unaware `break`), silently dropping real code
    after it (a §4.05 leak for every consumer rule). An UNTERMINATED comment now
    blanks to end-of-source (offset-preserving) rather than dropping the tail."""
    out = []
    i, n = 0, len(src)
    while i < n:
        c = src[i]
        if c == '"':
            # copy the string literal verbatim (escapes included); no comment
            # processing inside it.
            out.append('"')
            i += 1
            while i < n and src[i] != '"':
                if src[i] == '\\' and i + 1 < n:
                    out.append(src[i:i + 2])
                    i += 2
                    continue
                out.append(src[i])
                i += 1
            if i < n:
                out.append('"')
                i += 1
        elif src[i:i + 2] == '/*':
            end = src.find('*/', i + 2)
            stop = (end + 2) if end != -1 else n
            out.append(''.join('\n' if ch == '\n' else ' '
                               for ch in src[i:stop]))
            i = stop
        elif src[i:i + 2] == '//':
            end = src.find('\n', i)
            if end == -1:
                end = n
            out.append(' ' * (end - i))
            i = end
        else:
            out.append(c)
            i += 1
    return ''.join(out)


# Reserved words that look like identifiers but aren't signals
VERILOG_KEYWORDS = {
    'module', 'endmodule', 'input', 'output', 'inout', 'wire', 'reg', 'logic',
    'assign', 'always', 'always_ff', 'always_comb', 'always_latch',
    'begin', 'end', 'if', 'else', 'case', 'endcase', 'default', 'for',
    'while', 'repeat', 'posedge', 'negedge', 'or', 'and', 'not',
    'function', 'endfunction', 'task', 'endtask', 'parameter', 'localparam',
    'generate', 'endgenerate', 'genvar', 'integer', 'real', 'time',
    'return', 'break', 'continue', 'typedef', 'struct', 'union', 'enum',
    'packed', 'unpacked', 'signed', 'unsigned', 'initial', 'forever',
    'wait', 'fork', 'join', 'disable', '1b0', '1b1', 'x', 'z',
}


# ---------------------------------------------------------------------------
# Rule 1 + Rule 2: Undriven-wire / Unread-reg (general)
# ---------------------------------------------------------------------------
def find_declarations(src: str) -> List[Tuple[str, str, int]]:
    """
    Return list of (kind, name, lineno) for all wire/reg/logic declarations
    except module ports (which are driven/read externally).
    """
    decls = []
    lines = src.split('\n')
    # Track whether we are inside a module port list to skip port decls
    in_port_list = False
    paren_depth = 0
    for lineno, line in enumerate(lines, start=1):
        # Track entry/exit of port list
        if re.search(r'\bmodule\b\s+\w+', line):
            in_port_list = True
        if in_port_list:
            paren_depth += line.count('(') - line.count(')')
            if paren_depth <= 0 and ';' in line:
                in_port_list = False
            continue
        # Match: wire [MSB:LSB] name1, name2;  or reg [..] name;
        m = re.match(
            r'\s*(wire|reg|logic)\s+(?:(?:signed|unsigned)\s+)?'
            r'(?:\[[^\]]+\]\s*)?'     # optional packed range
            r'(?:\[[^\]]+\]\s*)?'     # optional 2nd range (arrays)
            r'([^;=]+?)\s*;',
            line)
        if not m:
            continue
        kind, name_list = m.group(1), m.group(2)
        # Skip if this is inside a port/function/task
        for n in name_list.split(','):
            n = n.strip()
            # Strip array subscript from declaration list
            n = re.sub(r'\[.*', '', n).strip()
            if n and n not in VERILOG_KEYWORDS and re.match(r'^\w+$', n):
                decls.append((kind, n, lineno))
    return decls


def collect_lhs_set(src: str) -> Set[str]:
    """Collect every identifier that appears on the LHS of assign or always <=/=."""
    lhs = set()
    # assign X = ...  (ORGANIC #544 — allow MULTIPLE bracket subscripts so a
    # 2-D / unpacked-array slice assign `assign arr[i][j] = ...` registers
    # `arr` as driven; the old single-`[...]?` form failed on a second
    # subscript and false-flagged the array as undriven-wire.)
    for m in re.finditer(r'\bassign\s+(\w+)(?:\[[^\]]+\])*\s*=', src):
        lhs.add(m.group(1))
    # LHS concatenation / bit-grouping targets, e.g.
    #   assign {carry, sum} = a + b;
    #   {hi, lo} <= a * b;
    # Every identifier inside the `{...}` group on the LHS of `=`/`<=` is driven.
    # Without this, multi-driver concat targets (very common in CPU/arithmetic
    # IP — SERV's serv_alu `assign {add_cy,result_add} = ...`) were reported as
    # false-positive `undriven-wire` ERRORs. Chip-AGNOSTIC: pure structural.
    for m in re.finditer(r'(?:\bassign\s+)?\{([^{}]*)\}\s*(?:<=|=)(?!=)', src):
        for tok in re.findall(r'[a-zA-Z_]\w*', m.group(1)):
            if tok not in VERILOG_KEYWORDS and not tok.startswith("'"):
                lhs.add(tok)
    # X <= ... or X = ... inside procedural blocks (#544 — multiple subscripts)
    for m in re.finditer(r'(?<![<>!=])\b(\w+)(?:\[[^\]]+\])*\s*(<=|=)(?!=)', src):
        # Skip the tokens around 'begin', 'end', keywords
        name = m.group(1)
        if name not in VERILOG_KEYWORDS and not name.startswith("'"):
            lhs.add(name)
    return lhs


def collect_rhs_set(src: str) -> Set[str]:
    """
    Collect identifiers that appear on the RHS of expressions / conditions / ports.
    This is conservative — it counts ANY identifier token not matched as LHS.
    """
    used = set()
    # Strip out LHS tokens first pass
    #   assign LHS = RHS;  →  keep RHS
    #   X <= RHS;         →  keep RHS
    #   port connections  →  keep all
    # Simpler: tokenize all identifiers, then we'll intersect with known decls.
    for m in re.finditer(r'\b([a-zA-Z_]\w*)\b', src):
        tok = m.group(1)
        if tok not in VERILOG_KEYWORDS:
            used.add(tok)
    return used


def collect_instance_connections(src: str) -> Dict[str, str]:
    """
    For each `.port(signal)` connection in a module instance, return mapping
    port_name -> signal_name. We use this conservatively: any signal that
    appears in .port(signal) is considered both 'driven' and 'read' because
    we don't know the port direction without cross-module analysis.
    """
    connected = {}
    for m in re.finditer(r'\.(\w+)\s*\(\s*([^)]+)\s*\)', src):
        port, sig = m.group(1), m.group(2).strip()
        # ORGANIC #544 — a concat connection `.o({w_hi, w_lo})` drives EVERY
        # identifier inside the braces (the instance output fans out to all
        # of them). The old `^(\w+)` match failed on the leading `{` and
        # left w_hi/w_lo looking undriven. Register each concat member.
        if sig.startswith("{"):
            for tok in re.findall(r'[a-zA-Z_]\w*', sig):
                if tok not in VERILOG_KEYWORDS and not tok.startswith("'"):
                    connected[tok] = port
            continue
        # Take simple identifier from the signal side
        sm = re.match(r'^(\w+)', sig)
        if sm:
            connected[sm.group(1)] = port
    return connected


def rule_undriven_and_unread(src: str, path: str) -> List[Finding]:
    findings: List[Finding] = []
    decls = find_declarations(src)
    lhs = collect_lhs_set(src)
    rhs = collect_rhs_set(src)
    inst_sigs = collect_instance_connections(src)

    for kind, name, lineno in decls:
        driven = name in lhs or name in inst_sigs
        read = name in (rhs - {name})  # exclude itself
        # Conservative: an identifier appears in RHS if used anywhere;
        # but we already include LHS in rhs (tokenizer is blind).
        # Better: count only tokens NOT in decl line.
        # For now, focus on the clear-cut cases.

        if kind == 'wire' and not driven:
            findings.append(Finding(path, lineno, 'ERROR', 'undriven-wire', name,
                f"wire '{name}' declared but never driven (no assign, no instance output)."))
        # ORGANIC R8C3 (#782) — TOTALLY-DEAD reg/logic: declared but NEITHER
        # driven NOR read. The existing reg/logic arm below guards on
        # `name in lhs` (written-but-unread), so a `reg`/`logic` that is never
        # written AND never read fell through entirely and was silently
        # tolerated — only a dead `wire` was flagged (asymmetry). verilator
        # -Wall reports UNUSEDSIGNAL ("not driven, nor used") on such a dead
        # reg/logic. Flag it symmetrically. Carve-outs: skip a memory ARRAY
        # declaration (a storage element whose read port may live in a
        # sibling/future module — same INFO carve-out the unread-reg arm uses)
        # so no-leak holds for staged designs.
        #
        # The read-test MUST count occurrences (the `read = name in (rhs -
        # {name})` short-cut above wrongly removes the name itself from rhs, so
        # it always says "not read" — that mislabels a READ-BUT-UNDRIVEN signal
        # `q` in `w_ptr <= q;` as totally dead). A genuinely dead reg appears
        # ONLY at its own declaration: total token occurrences == 1 (the decl).
        # One extra occurrence means it is read somewhere (a different,
        # undriven-read concern that this TOTALLY-dead arm deliberately leaves
        # alone). chip-AGNOSTIC: pure structural token count.
        _tot_occ = len(re.findall(r'\b' + re.escape(name) + r'\b', src))
        if (kind in ('reg', 'logic') and not driven and _tot_occ <= 1):
            is_mem_array = re.search(
                r'\b(?:reg|logic)\b[^;\n]*\b' + re.escape(name)
                + r'\s*\[[^\]]+\]\s*[;,]', src)
            sev = 'INFO' if is_mem_array else 'WARN'
            note = (" (write-only/unused memory array — likely storage whose "
                    "ports are in a sibling/future module; advisory only)"
                    if is_mem_array else
                    " (declared but neither driven nor read — dead signal; "
                    "`verilator -Wall` UNUSEDSIGNAL).")
            findings.append(Finding(path, lineno, sev, 'unused-signal', name,
                f"{kind} '{name}' is declared but never used.{note}"))
        if kind in ('reg', 'logic') and name in lhs:
            # declared reg that is written but never read on any RHS
            # Heuristic: if the only occurrences are in always-block-LHS, it's unread.
            # Count RHS occurrences excluding LHS sites:
            lhs_pattern = re.compile(
                r'\b' + re.escape(name) + r'\b(?:\s*\[[^\]]+\])?\s*(?:<=|=)(?!=)')
            total_occ = len(re.findall(r'\b' + re.escape(name) + r'\b', src))
            lhs_occ = len(lhs_pattern.findall(src))
            decl_occ = 1  # the declaration itself
            # Reads = total - (LHS assignments) - (declaration)
            reads = total_occ - lhs_occ - decl_occ
            if reads <= 0 and name not in inst_sigs:
                # #754 / ORGANIC-20260616 (C4) — a write-only UNPACKED MEMORY
                # ARRAY (`reg [W-1:0] NAME [DEPTH]`) whose only use is an indexed
                # write is a legitimate single-port-RAM storage pattern whose
                # read port lives in a sibling/future module (staged/incremental
                # designs that store spec-mandated fields ahead of their
                # out-of-scope consumers, e.g. MSHR write_table_q/data_ram_q).
                # Such a write-only array MUST NOT BLOCK a correct submission, so
                # it is reported at INFO (advisory, non-blocking, excluded from
                # the rc=1 condition) rather than WARN. A genuinely dead SCALAR
                # reg still WARNs/blocks. This reuses the same structural
                # memory-array detection used by the autofix path so the two
                # agree, and is purely structural / chip-AGNOSTIC.
                is_mem_array = re.search(
                    r'\b(?:reg|logic)\b[^;\n]*\b' + re.escape(name)
                    + r'\s*\[[^\]]+\]\s*[;,]', src)
                sev = 'INFO' if is_mem_array else 'WARN'
                note = (" (write-only memory array — likely a RAM whose read "
                        "port is in a sibling/future module; advisory only)"
                        if is_mem_array else "")
                f = Finding(path, lineno, sev, 'unread-reg', name,
                    f"{kind} '{name}' declared and written but never read.{note}")
                # ORGANIC #770 round-2 — a scalar reg that is written ONLY by a
                # pure register-pass-through copy (`reg <= <single_identifier>;`)
                # inside a clocked block is the canonical CDC double-flop
                # SYNCHRONIZER stage (e.g. async-FIFO `wq2_rptr`): its reader is
                # the comparison/full-flag logic that lives in a SIBLING module /
                # the other clock domain, so it is NOT dead — it is a legitimate
                # cross-domain signal. The dead-reg structural inference is
                # PROSE_HEURISTIC and the RTL CONTRADICTS it (the flop is a
                # synchronizer feeding out of this submodule). Downgrade to
                # ADVISORY. No-leak: a reg written with COMPUTED logic
                # (`x <= a & b;`, a constant, an expression) is NOT a
                # pass-through sync flop → stays a hard WARN (block-eligible).
                if not is_mem_array and _is_sync_passthrough_reg(src, name):
                    f = _advisory(f, _prov.PROSE_HEURISTIC, _prov.CONTRADICTED)
                findings.append(f)
    return findings


# Single-identifier NBA write of a scalar reg inside a clocked always block —
# the register-to-register copy that defines a CDC synchronizer / pipeline-pass
# flop (ORGANIC #770 round-2). chip-AGNOSTIC: pure SystemVerilog structure.
def _is_sync_passthrough_reg(src: str, name: str) -> bool:
    """True iff EVERY NBA write of scalar `name` is either a SINGLE bare-
    identifier register copy (`q2 <= q1;`) or a reset-clear-to-zero
    (`q2 <= 0;`), AND at least one register-copy write exists inside a
    posedge/negedge (clocked) always block. That is the double-flop CDC
    synchronizer signature: reset to 0, then pass the prior stage straight
    through with no logic. A reg written with COMPUTED logic (operators, a
    non-zero literal/constant value, a slice/concat/index), or by blocking `=`
    only, is NOT a pass-through sync flop → returns False (keeps the hard
    WARN — no-leak biased). chip-AGNOSTIC pure structure."""
    # All NBA writes of `name` and their RHS up to `;`.
    write_re = re.compile(
        r'(?<![<>!=])\b' + re.escape(name) + r'\s*<=\s*([^;]+);')
    rhss = [m.group(1).strip() for m in write_re.finditer(src)]
    if not rhss:
        return False  # no NBA write at all → not a sync flop
    saw_passthrough = False
    for rhs in rhss:
        # A reset-clear write (`<= 0` / `<= 4'd0` / `<= '0` / `<= {N{1'b0}}`) is
        # allowed — it does not carry datapath logic.
        if _sized_literal_value(rhs) == 0 or re.fullmatch(
                r"(?:\d+'[bhdo]?0+|'0|0|\{[^{}]*1'b0[^{}]*\})", rhs):
            continue
        # Otherwise the RHS must be exactly ONE bare identifier (a register
        # pass-through). No operators, no non-zero literals, no slice/concat/
        # index — those carry logic and are NOT a synchronizer stage.
        if not re.fullmatch(r'[A-Za-z_]\w*', rhs) or rhs in VERILOG_KEYWORDS:
            return False
        saw_passthrough = True
    if not saw_passthrough:
        return False  # only reset-clears, no copy → not a synchronizer
    # At least one register-copy NBA write must sit inside a CLOCKED always
    # block (level-sensitive `@(*)` pass-throughs are not CDC synchronizers).
    name_domain = None
    src_ids: Set[str] = set()
    for sens, body, _pos in _iter_always_blocks(src):
        dom = _edge_domain(sens)
        if not dom:
            continue  # comb block — not a clocked synchronizer
        for m in write_re.finditer(body):
            rhs = m.group(1).strip()
            if re.fullmatch(r'[A-Za-z_]\w*', rhs) and rhs not in VERILOG_KEYWORDS:
                name_domain = dom
                src_ids.add(rhs)
    if name_domain is None:
        return False
    # ORGANIC #770 r2 Step-2.7 — a bare clocked `q2 <= q1` is a SYNCHRONIZER only
    # with structural corroboration that it crosses or feeds a domain; otherwise
    # a same-domain copy read NOWHERE is just a dead reg (must keep its WARN).
    # Corroborate by EITHER:
    #   (a) `name` is itself read on the RHS of ANOTHER reg's NBA (a 2-flop chain
    #       qN <= qN-1 downstream — the synchronizer continues), OR
    #   (b) a source it copies is written in a DIFFERENT clock domain (true CDC).
    downstream_re = re.compile(
        r'\b[A-Za-z_]\w*\s*(?:\[[^\]]*\])?\s*<=\s*[^;]*\b'
        + re.escape(name) + r'\b')
    feeds_downstream = False
    for m in downstream_re.finditer(src):
        # ignore name's own writes (`name <= ... name ...`); require a DIFFERENT LHS.
        lhs = re.match(r'\s*([A-Za-z_]\w*)', m.group(0))
        if lhs and lhs.group(1) != name:
            feeds_downstream = True
            break
    if feeds_downstream:
        return True
    # (b) true CDC: walk the copy chain back from `name`; if ANY stage copies a
    # source that is NBA-written in a DIFFERENT edge (clock) domain, the chain
    # crosses clock domains → genuine synchronizer (async_filo: `wq2 <= wq1 <=
    # rptr_gray`, rptr_gray registered in the rclk domain). A SINGLE-clock copy
    # chain (deadcopy: q2<=q1, both wclk, source a same-domain reg or a port) is
    # NOT a CDC → stays a dead-reg WARN (§4.05 no-leak biased). chip-AGNOSTIC.
    # Map every NBA-written name → its edge domain(s).
    dom_of: Dict[str, Set[str]] = {}
    for sens, body, _pos in _iter_always_blocks(src):
        dom = _edge_domain(sens)
        if not dom:
            continue
        for am in re.finditer(r'([A-Za-z_]\w*)(?:\s*\[[^\]]*\])?\s*<=', body):
            dom_of.setdefault(am.group(1), set()).add(dom)
    seen_chain: Set[str] = set()
    frontier = set(src_ids)
    while frontier:
        sid = frontier.pop()
        if sid in seen_chain:
            continue
        seen_chain.add(sid)
        # if this stage is written in a domain other than name's → CDC.
        if any(d != name_domain for d in dom_of.get(sid, set())):
            return True
        # follow the chain: what bare register does `sid` copy?
        for cm in re.finditer(
                r'(?<![<>!=])\b' + re.escape(sid) + r'\s*<=\s*([^;]+);', src):
            rhs = cm.group(1).strip()
            if re.fullmatch(r'[A-Za-z_]\w*', rhs) and rhs not in VERILOG_KEYWORDS:
                frontier.add(rhs)
    return False


# ---------------------------------------------------------------------------
# Rule 3: Case without default + enum coverage hint
# ---------------------------------------------------------------------------

# Sized integer literal: N'bxx / N'hxx / N'dxx / N'oxx (optional underscores,
# optional s for signed). Chip-AGNOSTIC: this is plain SystemVerilog syntax.
_SIZED_LITERAL_RE = re.compile(
    r"\b(\d+)\s*'\s*([sS]?)([bBoOdDhH])\s*([0-9a-fA-F_xXzZ]+)")


def _sized_literal_value(tok: str):
    """Return the integer value of a sized literal like 2'b10 / 8'hFF.

    Returns None when the literal is non-deterministic (contains x/z, or is not
    a clean sized literal) so the caller can stay conservative. ORGANIC #764.
    """
    m = _SIZED_LITERAL_RE.fullmatch(tok.strip())
    if not m:
        return None
    base = m.group(3).lower()
    digits = m.group(4).replace('_', '')
    if any(c in 'xXzZ' for c in digits):
        return None  # don't-care / hi-Z label — value not determinable
    try:
        if base == 'b':
            return int(digits, 2)
        if base == 'o':
            return int(digits, 8)
        if base == 'd':
            return int(digits, 10)
        if base == 'h':
            return int(digits, 16)
    except ValueError:
        return None
    return None


def _resolve_selector_width(src: str, expr: str):
    """Resolve the bit-width of a case selector from its declaration.

    Only succeeds for a SIMPLE scalar identifier selector whose declaration
    carries a CONCRETE numeric `[hi:lo]` range (hi/lo are plain integers, not
    parameter expressions). Returns the width in bits, or None when it cannot
    be deterministically resolved (parameterized width, no range, expression
    selector, …). Conservative-by-design: None -> keep the WARN. Chip-AGNOSTIC.
    ORGANIC #764.
    """
    name = expr.strip()
    # Selector must be a bare identifier (no concat/slice/expression).
    if not re.fullmatch(r'[A-Za-z_]\w*', name):
        return None
    # Find a declaration of this signal carrying a numeric [hi:lo] range.
    # Matches input/output/inout/reg/wire/logic ... [HI:LO] ... name
    decl_re = re.compile(
        r'\b(?:input|output|inout|reg|wire|logic)\b[^;\n]*?'
        r'\[\s*(\d+)\s*:\s*(\d+)\s*\][^;\n]*?\b' + re.escape(name) + r'\b')
    for m in decl_re.finditer(src):
        hi = int(m.group(1))
        lo = int(m.group(2))
        return abs(hi - lo) + 1
    return None


# ORGANIC #770 round-2 — resolve a SYMBOLIC state-localparam to its integer
# value so a fully-enumerated FSM written with localparam labels
# (`case (state) S_IDLE: ... S_DONE: ...`) is recognised as exhaustive exactly
# like a numeric-literal one. chip-AGNOSTIC: pure SystemVerilog constant parse.
def _localparam_int_values(src: str) -> Dict[str, int]:
    """Map every `localparam`/`parameter NAME = <const>;` to its integer value
    (when the RHS is a deterministically-resolvable constant). Earlier params
    feed later ones via `_eval_const_int`. Non-constant RHS are skipped."""
    vals: Dict[str, int] = {}
    for m in _LOCALPARAM_DECL_RE.finditer(src):
        name, rhs = m.group(1), m.group(2)
        # ORGANIC #770 r3 — a COMMA-SEPARATED multi-declaration
        # (`localparam IDLE=2'd0, LOAD=2'd1, RUN=2'd2, DONE=2'd3;`) captures the
        # FIRST name then the whole tail as `rhs`. Split the tail into the
        # remaining `NAME = value` continuations so every state localparam
        # resolves (a symbolic-localparam FSM declared on one line was otherwise
        # unrecognised → case-no-default false WARN, binary_search_tree FP).
        # Split only at TOP-LEVEL commas (depth-aware so a `{a,b}`/`(a,b)` value
        # stays intact).
        segs: List[str] = []
        depth = 0
        cur = ""
        for ch in rhs:
            if ch in "([{":
                depth += 1
            elif ch in ")]}":
                depth = max(0, depth - 1)
            if ch == "," and depth == 0:
                segs.append(cur)
                cur = ""
            else:
                cur += ch
        if cur:
            segs.append(cur)
        pairs = [(name, segs[0] if segs else rhs)]
        for seg in segs[1:]:
            pm = re.match(r"\s*([A-Za-z_]\w*)\s*=\s*(.+)$", seg, re.DOTALL)
            if pm:
                pairs.append((pm.group(1), pm.group(2)))
        for nm, vexpr in pairs:
            if nm in VERILOG_KEYWORDS:
                continue
            v = _eval_const_int(vexpr, vals)
            if v is not None:
                vals[nm] = v
    return vals


def _label_value(tok: str, params: Dict[str, int]):
    """Resolve ONE case-label token to its integer value: a sized numeric
    literal OR a known state-localparam name. Returns None when neither (a
    symbolic label whose value we cannot prove → caller stays conservative)."""
    v = _sized_literal_value(tok)
    if v is not None:
        return v
    if re.fullmatch(r'[A-Za-z_]\w*', tok) and tok in params:
        return params[tok]
    return None


def _case_is_exhaustive(src: str, expr: str, block: str):
    """Return True iff the case PROVABLY enumerates all 2**width selector values.

    Requirements (all must hold, else returns False = stay conservative):
      * selector width deterministically resolvable to N bits (<= a sane cap),
      * EVERY case label is a clean sized numeric literal OR a resolvable
        state-localparam (ORGANIC #770 round-2: a symbolic-localparam FSM whose
        labels are all `localparam`s of known value is just as enumerable as a
        numeric-literal one),
      * the distinct label values exactly cover {0 .. 2**N - 1}.
    Purely structural & chip-AGNOSTIC (no design/benchmark literal). ORGANIC #764.
    """
    width = _resolve_selector_width(src, expr)
    if width is None or width <= 0 or width > 12:
        return False  # unknown or too-wide to enumerate -> conservative
    # ORGANIC #770 round-2 — known localparam/parameter integer values so a
    # symbolic FSM label (`S_IDLE`/`S_DONE`/…) resolves to its numeric value.
    params = _localparam_int_values(src)

    # Isolate the case body: strip the leading `case (...)` head and the
    # trailing `endcase`.
    body = block
    body = re.sub(r'^\s*\bcase[szx]?\s*\([^)]*\)', '', body, count=1)
    body = re.sub(r'\bendcase\b.*$', '', body, flags=re.DOTALL)

    # Strip line + block comments so legend text ('// 90 deg') can't be parsed
    # as a label.
    body = re.sub(r'//[^\n]*', '', body)
    body = re.sub(r'/\*.*?\*/', '', body, flags=re.DOTALL)

    # A branch label is the token-list that appears at a statement boundary and
    # is terminated by ':'. We find each ':' that directly follows a label head
    # (run of label tokens) at a statement boundary (body start, or just after a
    # top-level ';' / 'begin' / 'end'). The ':' must NOT be a part-select
    # (+:/-:), a ternary (?:), a scope resolution (::), or non-blocking-with-
    # equals (:=). A symbolic identifier sitting at a branch boundary => not
    # resolvable => bail conservatively. Chip-AGNOSTIC structural scan.
    labels = []
    label_re = re.compile(
        r"(?:(?<=^)|(?<=[;)])|(?<=\bbegin\b)|(?<=\bend\b))"  # statement boundary
        r"\s*([0-9A-Za-z_',\s]+?)\s*"
        r":(?![:=+\-])",
        re.MULTILINE)
    saw_any = False
    for m in label_re.finditer(body):
        head = m.group(1).strip()
        if not head:
            continue
        # ORGANIC #781 (round-8 cluster R8C2) — the label-head class
        # `[0-9A-Za-z_',\s]+?` admits whitespace, and the `(?<=\bbegin\b)` /
        # `(?<=\bend\b)` statement-boundary lookbehinds do NOT consume the
        # keyword. So when a branch body uses the ubiquitous
        # `LABEL: begin … end` idiom, the trailing `end`(s) of one branch
        # bleed into the NEXT label head, e.g. head = 'end\n end\n
        # ENTRY_PROCESSING'. The old comma-only split then yielded a single
        # un-resolvable part and `_label_value` returned None, so a fully-
        # enumerated begin/end FSM was wrongly judged non-exhaustive and
        # HARD-BLOCKED (case-no-default WARN). Split each head on whitespace
        # AND commas, then drop the structural `begin`/`end`/… keyword tokens
        # (they are never case labels) before resolving. A fully-enumerated
        # `begin/end` FSM is then recognised exactly like its single-statement
        # twin, while a genuinely symbolic-unknown label survives the keyword
        # filter and still bails to False below (§4.05 no-leak preserved — a
        # partial / symbolic / out-of-range begin/end FSM still hard-blocks).
        parts = [p for p in re.split(r'[\s,]+', head)
                 if p and p not in VERILOG_KEYWORDS]
        if not parts:
            continue
        for p in parts:
            v = _label_value(p, params)
            if v is None:
                # Symbolic-but-unknown / unsized / x-z / non-literal label at a
                # branch boundary -> not deterministically resolvable ->
                # conservative. (A symbolic label that IS a known state-localparam
                # resolves to its integer value via _label_value — ORGANIC #770
                # round-2 — so a fully-enumerated localparam FSM is recognised.)
                return False
            if v >= (1 << width):
                return False  # label out of declared range -> bail
            labels.append(v)
        saw_any = True

    if not saw_any or not labels:
        return False

    return set(labels) == set(range(1 << width))


def _clocked_always_spans(src: str) -> List[tuple]:
    """ORGANIC #770 r4 — (start, end) char-offset spans of every CLOCKED
    (edge-sensitive `@(posedge/negedge …)` / always_ff) always block. A `case`
    inside such a block CANNOT infer a latch: on an unlisted selector code the
    state register simply HOLDS its value (the canonical registered-FSM idiom).
    Latch risk only exists in a COMBINATIONAL `always @(*)` / always_comb / a
    level-sensitive block. chip-AGNOSTIC: pure edge-sensitivity grammar.

    r4 Step-2.7: the span END must be the clocked block's OWN matching `end`
    (or its single statement), NOT `_block_body_after`'s result — that extends to
    the NEXT always/endmodule, so a combinational case textually FOLLOWING a
    clocked block fell inside the over-extended span and was wrongly downgraded
    (a §4.05 leak). Compute the real end by `begin/end` depth tracking from the
    statement that opens the block body."""
    spans: List[tuple] = []
    for bm in re.finditer(
            r'\balways(?:_ff)?\s*@\s*\(([^)]*)\)', src):
        sens = bm.group(1)
        if not _edge_domain(sens):
            continue
        i = bm.end()
        n = len(src)
        # skip whitespace to the first body token.
        while i < n and src[i].isspace():
            i += 1
        if i < n and re.match(r'\bbegin\b', src[i:]):
            # a begin/end block — find the MATCHING end by depth counting over
            # begin/end keyword tokens (string/comment-free enough for our RTL).
            depth = 0
            for km in re.finditer(r'\b(begin|end)\b', src[i:]):
                depth += 1 if km.group(1) == 'begin' else -1
                if depth == 0:
                    spans.append((bm.start(), i + km.end()))
                    break
            else:
                spans.append((bm.start(), n))
        else:
            # a single (non-begin) statement — ends at the next ';'.
            semi = src.find(';', i)
            spans.append((bm.start(), (semi + 1) if semi != -1 else n))
    return spans


# ORGANIC #803 Step-2.7 §4.05 — `VERILOG_KEYWORDS` over-broadly includes the
# hi-Z / don't-care LITERAL-spelling tokens `x`/`z`, which are ALSO legal Verilog
# IDENTIFIERS. A token that appears as an assignment LHS (immediately before
# `=`/`<=`) is ALWAYS a real signal (you cannot assign to a literal), so it must
# never be dropped as a keyword — else a case-body output literally named `x`/`z`
# vanishes from the coverage set and a genuine inferred latch is masked.
_LHS_LITERAL_NAMES = frozenset({"x", "z"})


def _procedural_assigned_lhs(text: str) -> Set[str]:
    """ORGANIC #794 — set of identifiers assigned by a procedural `=` / `<=` at
    STATEMENT level (paren depth 0) inside `text`.

    Paren-depth gating is the key correctness point: a `<=` (or `=`) INSIDE
    `(...)` is an `if`/`while` condition or a call argument where `<=` is a
    COMPARISON, not a non-blocking assignment (e.g. `if (current_floor_reg <=
    min_request)`), and must NOT be counted as an LHS. `==` / `>=` / `!=` /
    `<=`-as-compare are rejected by the surrounding-operator guard. A
    CONCATENATION LHS `{a, b[1:0], c} =` records EVERY identifier inside the
    braces (Step-2.7 §4.05 — a missed concat LHS would falsely shrink the
    assigned set and mask a latch); a bit/part-select LHS records the BASE name
    (the caller separately refuses to PROVE coverage when a subscript is present
    — see `_lhs_has_subscript`). Purely structural & chip-AGNOSTIC."""
    out: Set[str] = set()
    depth = 0
    n = len(text)
    i = 0
    while i < n:
        c = text[i]
        if c == '(':
            depth += 1
            i += 1
            continue
        if c == ')':
            depth = max(0, depth - 1)
            i += 1
            continue
        if depth == 0 and ((c == '<' and text[i:i + 2] == '<=') or c == '='):
            if c == '<':
                op_end = i + 2
            else:
                if text[i:i + 2] == '==':       # equality compare, not assign
                    i += 2
                    continue
                if i > 0 and text[i - 1] in '<>!=':  # part of <= >= != ==
                    i += 1
                    continue
                op_end = i + 1
            # scan back to the LHS identifier, skipping a trailing [..] subscript
            j = i - 1
            while j >= 0 and text[j].isspace():
                j -= 1
            while j >= 0 and text[j] == ']':
                d2 = 0
                while j >= 0:
                    if text[j] == ']':
                        d2 += 1
                    elif text[j] == '[':
                        d2 -= 1
                    j -= 1
                    if d2 == 0:
                        break
                while j >= 0 and text[j].isspace():
                    j -= 1
            # ORGANIC #794 Step-2.7 §4.05 — a CONCATENATION LHS `{a, b[1:0], c} =`
            # assigns EVERY identifier inside the braces. The scalar scan-back
            # below would read only the brace `}` and yield an EMPTY name, so a
            # case arm assigning `{a,b}` would vanish from the assigned set and a
            # GENUINE latch on a/b would be falsely downgraded. Extract every
            # identifier inside the matching `{...}` (over-inclusion of an index
            # var is the SAFE direction — it can only KEEP a hard WARN).
            if j >= 0 and text[j] == '}':
                d3 = 0
                m = j
                while m >= 0:
                    if text[m] == '}':
                        d3 += 1
                    elif text[m] == '{':
                        d3 -= 1
                    if d3 == 0:
                        break
                    m -= 1
                concat = text[m:j + 1] if m >= 0 else ""
                for nm in re.findall(r'[A-Za-z_]\w*', concat):
                    if nm not in VERILOG_KEYWORDS or nm in _LHS_LITERAL_NAMES:
                        out.add(nm)
                i = op_end
                continue
            k = j
            while k >= 0 and (text[k].isalnum() or text[k] == '_'):
                k -= 1
            name = text[k + 1:j + 1]
            if (name and not name[0].isdigit()
                    and (name not in VERILOG_KEYWORDS
                         or name in _LHS_LITERAL_NAMES)):
                out.add(name)
            i = op_end
            continue
        i += 1
    return out


# ORGANIC #794 Step-2.7 §4.05 — a SUBSCRIPTED (bit/part-select) assignment LHS
# means the base-name assigned set CANNOT prove full-vector coverage: a pre-case
# default on `dout[3:2]` and a case-body write on `dout[1:0]` both reduce to the
# base `dout`, so a genuine latch on the unwritten slice would be falsely
# downgraded. These detect a subscripted scalar LHS (`name[...] =`) and a concat
# LHS containing a slice (`{ ... [..] ... } =`); the caller stays conservative
# (keeps the hard WARN) whenever EITHER region has one. A false hit (a `]<=` that
# is actually a condition compare) only KEEPS a hard WARN — the safe direction.
_SUBSCRIPTED_LHS_RE = re.compile(r'\][ \t]*(?:<=|=(?!=))')
_CONCAT_SLICE_LHS_RE = re.compile(r'\{[^{}]*\[[^{}]*\}[ \t]*(?:<=|=(?!=))')


def _lhs_has_subscript(text: str) -> bool:
    """True if any assignment in `text` has a SUBSCRIPTED LHS (a bit/part-select
    scalar, or a concat containing one). #794 Step-2.7 §4.05 — such an assign
    cannot prove full-vector coverage from a base name."""
    return bool(_SUBSCRIPTED_LHS_RE.search(text)
                or _CONCAT_SLICE_LHS_RE.search(text))


def _enclosing_always_body(src: str, case_off: int) -> Optional[Tuple[int, int]]:
    """ORGANIC #794 — (body_start_off, block_end_off) of the TIGHTEST always
    block textually containing `case_off`, where body_start_off is the char
    offset just AFTER the `always [@(...)]` header. Handles `always`,
    `always_comb`, `always_latch`, `always_ff` with or without a sensitivity
    list. chip-AGNOSTIC: pure begin/end depth tracking."""
    best: Optional[Tuple[int, int]] = None
    for bm in re.finditer(
            r'\balways(?:_ff|_comb|_latch)?\s*(?:@\s*\([^)]*\))?', src):
        i = bm.end()
        n = len(src)
        while i < n and src[i].isspace():
            i += 1
        if i < n and re.match(r'\bbegin\b', src[i:]):
            depth = 0
            blk_end = n
            for km in re.finditer(r'\b(begin|end)\b', src[i:]):
                depth += 1 if km.group(1) == 'begin' else -1
                if depth == 0:
                    blk_end = i + km.end()
                    break
        else:
            semi = src.find(';', i)
            blk_end = (semi + 1) if semi != -1 else n
        if bm.end() <= case_off < blk_end:
            if best is None or bm.end() > best[0]:
                best = (bm.end(), blk_end)
    return best


def _case_lhs_all_pre_assigned(src: str, case_head_off: int) -> bool:
    """ORGANIC #794 — True iff this combinational `case` is the canonical
    latch-FREE fallthrough idiom: EVERY identifier assigned inside the case body
    is ALSO unconditionally assigned (at statement-top — not under any
    if/else/case/for/while) in the SAME always block, textually BEFORE the case
    head. Then an unlisted selector code cannot infer a latch — the pre-case
    default holds — so verilator emits NO %Warning-LATCH (only CASEINCOMPLETE).
    §4.05 no-leak: returns False (keep the hard WARN) whenever ANY case-body LHS
    lacks such an unconditional pre-case default, when the pre-case region is not
    a flat statement-top list, OR when a SUBSCRIPTED (bit/part-select) LHS
    participates (a base name cannot prove a full-vector default — Step-2.7)."""
    body = _enclosing_always_body(src, case_head_off)
    if body is None:
        return False
    body_start, blk_end = body
    pre = src[body_start:case_head_off]
    # strip the single `begin` that opens the always body, then require the
    # pre-case region to be a FLAT statement-top list (no control construct). If
    # any if/else/for/while/case appears before the case, a pre-assignment might
    # be conditional → not provably unconditional → stay conservative.
    pre_body = re.sub(r'^\s*begin\b', '', pre, count=1)
    # ORGANIC #803 (extends #794): the unconditional pre-case defaults are the
    # LEADING FLAT statement-top prefix — from the body start up to the FIRST
    # control-construct token (if/else/for/while/case/repeat/forever). The
    # original #794 bailed entirely the moment ANY control token appeared in the
    # pre-case region, which MISSED the ubiquitous "priority-if-before-case" FSM
    # idiom: statement-top defaults, then `if (highest_priority) X; else
    # case(...)` (forced by any "from ANY state / regardless of current state"
    # spec). Those leading flat defaults provably HOLD on any unlisted selector
    # code REGARDLESS of an intervening priority if/else (whose own branches only
    # re-assign vars ALREADY defaulted in the flat prefix). §4.05 boundary
    # preserved: a case-LHS FIRST assigned only inside/after a conditional is NOT
    # in the flat prefix → body_lhs ⊄ uncond → hard WARN (proven latch).
    _ctrl = re.search(r'\b(if|else|for|while|case[szx]?|repeat|forever)\b',
                      pre_body)
    flat_prefix = pre_body[:_ctrl.start()] if _ctrl else pre_body
    uncond = _procedural_assigned_lhs(flat_prefix)
    if not uncond:
        return False
    # case body: from after the `(...)` head to the matching endcase.
    head_end = src.find(')', case_head_off)
    endcase_off = src.find('endcase', case_head_off)
    if head_end == -1 or endcase_off == -1 or endcase_off > blk_end:
        return False
    case_body = src[head_end + 1:endcase_off]
    # Step-2.7 §4.05 — a bit/part-select LHS in the case body or the FLAT prefix
    # defeats base-name coverage proof (a sliced default cannot cover a different
    # sliced write); stay conservative and keep the hard WARN.
    if _lhs_has_subscript(case_body) or _lhs_has_subscript(flat_prefix):
        return False
    body_lhs = _procedural_assigned_lhs(case_body)
    if not body_lhs:
        return False
    return body_lhs <= uncond


def rule_case_coverage(src: str, path: str) -> List[Finding]:
    findings: List[Finding] = []
    # Find every `case (expr) ... endcase` block with its starting line
    # Simple scan: find `case(...)` opening, find matching endcase
    lines = src.split('\n')
    clocked_spans = _clocked_always_spans(src)
    # char offset of the start of each line (for the clocked-span test).
    line_off = [0]
    for ln in lines:
        line_off.append(line_off[-1] + len(ln) + 1)
    case_starts = [(i, m.group(1))
                   for i, ln in enumerate(lines, start=1)
                   for m in re.finditer(r'\bcase[szx]?\s*\(([^)]+)\)', ln)]
    for start_line, expr in case_starts:
        # Find endcase
        end_line = start_line
        for j in range(start_line, len(lines) + 1):
            if j - 1 < len(lines) and 'endcase' in lines[j - 1]:
                end_line = j
                break
        block = '\n'.join(lines[start_line - 1:end_line])
        if not re.search(r'\bdefault\s*:', block):
            # ORGANIC #764 — suppress when the case is PROVABLY exhaustive: a
            # fully-enumerated case (all 2**width sized-literal labels present)
            # cannot infer a latch and has no un-enumerated value, so the WARN
            # is a false positive (it even fired on the golden/reference
            # module). Stay conservative: only suppress when the selector width
            # AND every label are deterministically resolvable; otherwise keep
            # the WARN (symbolic localparams, parameterized widths, partial
            # enumerations all stay flagged).
            if _case_is_exhaustive(src, expr, block):
                continue
            f = Finding(path, start_line, 'WARN', 'case-no-default', expr.strip(),
                f"case ({expr.strip()}) has no default branch — "
                "values not enumerated may generate latch or undefined behavior.")
            # ORGANIC #770 r4 — a case inside a CLOCKED (sequential) always block
            # cannot infer a LATCH (the state register HOLDS on an unlisted code,
            # the canonical registered-FSM idiom). Latch risk is COMBINATIONAL
            # only, so downgrade the sequential-case WARN to ADVISORY (reported,
            # never a hard block). A combinational `always @(*)` case with no
            # default STILL hard-WARNs (real latch risk — §4.05 no-leak).
            # char offset of the actual `case` token on the start line (not the
            # line start) — used for both the clocked-span test and the
            # pre-assigned-default test (#794).
            line_start = line_off[start_line - 1]
            cm = re.search(r'\bcase[szx]?\s*\(', lines[start_line - 1])
            case_off = line_start + (cm.start() if cm else 0)
            in_clocked = any(s <= case_off < e for s, e in clocked_spans)
            if in_clocked:
                f = _advisory(f, _prov.PROSE_HEURISTIC, _prov.CONTRADICTED)
                f.advisory_note = ("case in a CLOCKED block — on an unlisted code "
                                   "any assigned variable (state reg / temp) HOLDS "
                                   "its previous value; no latch / uninitialised "
                                   "state. Latch risk is COMBINATIONAL-only "
                                   "(always @(*)); advisory, not a hard block "
                                   "(ORGANIC #770 r4)")
            elif _case_lhs_all_pre_assigned(src, case_off):
                # ORGANIC #794 — a COMBINATIONAL `always @(*)` case with no
                # default, but EVERY case-body LHS is unconditionally assigned
                # (statement-top) before the case head. The pre-case default
                # holds on any unlisted selector code, so NO latch can be
                # inferred (verilator confirms: only CASEINCOMPLETE, no
                # %Warning-LATCH). This is the canonical latch-free
                # combinational-FSM idiom → downgrade to advisory. §4.05 no-leak:
                # _case_lhs_all_pre_assigned returns False when ANY case-body LHS
                # lacks an unconditional pre-case default, when a subscripted LHS
                # defeats base-name coverage, or when a concat LHS is missed.
                f = _advisory(f, _prov.PROSE_HEURISTIC, _prov.CONTRADICTED)
                f.advisory_note = ("combinational case with no default but every "
                                   "case-body LHS is unconditionally pre-assigned "
                                   "(statement-top) before the case head — the "
                                   "pre-case default holds on an unlisted code, so "
                                   "no latch can be inferred (latch-free "
                                   "fallthrough); advisory, not a hard block "
                                   "(ORGANIC #794)")
            findings.append(f)
    return findings


# ---------------------------------------------------------------------------
# Rule 3b: an `if` with no `else` in a COMBINATIONAL block (vibe-ic#563)
# ---------------------------------------------------------------------------
# `rule_case_coverage` above answers "is every path assigning this signal?" for
# the `case` form, with real care: it excludes clocked blocks (#770 r4), proves
# exhaustiveness before warning (#764), and resolves symbolic localparams (#770
# r2). None of that machinery had an `if` counterpart, so the SAME defect in the
# more common spelling passed silently — measured on four one-module files at
# v1.8.61:
#
#     always @(*)        if   -> 0 errors, 0 warnings, 0 info
#     always_comb        if   -> 0 errors, 0 warnings, 0 info
#     always @(en or d)  if   -> 0 errors, 0 warnings, 0 info
#     always @(*)        case -> 1 warning            <- the positive control
#
# `q` assigned only when `en` is high inside a combinational block holds its
# value otherwise: a level-sensitive latch, combinational feedback in a design
# that will be timed as if it were not. The three silent spellings are the three
# a person writes by accident; the `case` form usually comes from a deliberate
# FSM where coverage is already on the author's mind.
#
# WHY THE ASSIGNED-SET AND NOT THE `else`
# The question is not "does this `if` have an `else`". A signal assigned in BOTH
# arms is latch-free, and a signal assigned unconditionally before the `if` has a
# default that holds — the same "latch-free fallthrough" `_case_body_defaulted`
# already models. What infers a latch is a signal assigned in SOME arm and not in
# all of them, with no prior unconditional default. So the predicate is over
# assigned SETS, reusing `_procedural_assigned_lhs`, and an `if`/`else` pair
# whose arms assign the same set produces nothing.
#
# CONSERVATIVE IN THE SAME PLACES, deliberately: a subscripted LHS (`q[3] = …`)
# cannot be proven to cover the whole vector by base name, so `_lhs_has_subscript`
# suppresses exactly as it does for `case`; a clocked block cannot infer a latch
# at all (the register HOLDS), so `_clocked_always_spans` excludes it. Both were
# the hard-won parts of the `case` rule and are reused rather than re-derived.
_IF_KW_RE = re.compile(r'(?<![\w$])if\s*\(')

# A `function`/`task` body cannot infer a latch: its locals are re-evaluated on
# every call, so a variable assigned on only one path holds nothing between
# calls. MEASURED — both hits over 331 synthesisable corpus files were inside
# functions, and both were the same idiom: an unconditional seed followed by a
# conditional update (`crc16_step = {crc[14:0],1'b0}; if (fb) crc16_step ^= …`,
# `c = CRC_INIT; for (…) if (k < n) c = crc16_byte(…)`). The unconditional-default
# suppression below missed them because it searches back to the nearest `always`,
# and inside a function there is none.
_FUNC_TASK_RE = re.compile(
    r'(?<![\w$])(function|task)(?![\w$])(.*?)(?<![\w$])end\1(?![\w$])', re.S)


# A GENERATE `if`/`else if` selects which hardware EXISTS; it is elaborated away
# and cannot infer a latch. MEASURED on the tapeout ICs (`benchmark-data/ic/**`,
# where the first corpus — generated benchmark RTL — had none): 11 of 18 hits
# were this, all in SERV, all the same line shape:
#
#     end else if (W == 4) begin : gen_lsb_w_4
#
# `_IF_KW_RE` matched it, `_statement_after` read the generate block as the "then"
# arm, and every reg declared inside was reported as latched.
#
# Two signals, both structural rather than textual (a `generate` keyword is
# optional in SystemVerilog, so keying on it alone would miss exactly this file):
#   * the arm opens a NAMED block — `begin : label` — which procedural `if`
#     statements essentially never do and generate arms conventionally always do;
#   * the condition is elaboration-time constant: only identifiers, integers and
#     operators, with no signal that a simulator could change.
# The named-block test is the load-bearing one; the constant-condition test keeps
# it from swallowing a labelled procedural block.
_GENERATE_ARM_RE = re.compile(r'\s*begin\s*:\s*\w+')

# An EXPLICIT `generate` … `endgenerate` region. The named-block signal above
# catches the SERV `end else if (W == 4) begin : gen_lsb_w_4` form, but an
# unlabelled arm inside an explicit generate slips past it — MEASURED on
# `servile_mux.v:62`:
#
#     generate
#        if (sim) begin
#           integer f = 0;
#
# so both signals are needed and neither subsumes the other. `generate` is
# optional in SystemVerilog, which is why this cannot be the only test.
_GENERATE_REGION_RE = re.compile(
    r'(?<![\w$])generate(?![\w$]).*?(?:(?<![\w$])endgenerate(?![\w$])|\Z)', re.S)


def _generate_spans(src: str) -> List[tuple]:
    return [(m.start(), m.end()) for m in _GENERATE_REGION_RE.finditer(src)]

# An `initial` block runs once at time 0 and models power-up state, not hardware
# that holds between evaluations. MEASURED on the tapeout ICs: `serv_ctrl.v:101`
# is `initial if (RESET_STRATEGY == "NONE") o_ibus_adr = RESET_PC;` — a reset-
# strategy default — and `servile_mux.v:73` is an `initial if ($value$plusargs(...))`
# testbench hook. Neither can infer a latch, and both are idioms a real core uses.
_INITIAL_RE = re.compile(r'(?<![\w$])initial(?![\w$])')


def _initial_spans(src: str) -> List[tuple]:
    """(start, end) of every `initial` construct: a begin/end block, or the
    single statement that follows when there is no `begin`."""
    spans = []
    for m in _INITIAL_RE.finditer(src):
        body, end = _statement_after(src, m.end())
        spans.append((m.start(), end if body else m.end()))
    return spans


def _is_generate_arm(src: str, cond: str, then_start: int,
                     gen_spans: Optional[List[tuple]] = None,
                     off: int = -1) -> bool:
    """True when this `if` selects hardware rather than driving a signal.

    Two independent entry signals, because neither covers the other:
      * a NAMED arm (`begin : label`) — SERV's `end else if (W == 4) begin :
        gen_lsb_w_4`, where no `generate` keyword appears at all;
      * sitting directly inside an explicit `generate` region — `servile_mux.v:62`
        `generate / if (sim) begin`, whose arm is unlabelled.

    Excluding the whole generate REGION was tried and is wrong: an `always @(*)`
    inside a generate block can infer a real latch, and a region-wide exclusion
    swallows it (verified with a fixture before this shape replaced it).
    """
    named = bool(_GENERATE_ARM_RE.match(src[then_start:then_start + 64]))
    in_gen = (gen_spans is not None and off >= 0
              and any(lo <= off < hi for lo, hi in gen_spans))
    if not (named or in_gen):
        return False
    # An elaboration-time condition mentions no signal the design can change at
    # run time. Conservative: any comparison against a plain identifier is
    # allowed only when the identifier is a declared parameter/localparam.
    params = set(re.findall(
        r'(?<![\w$])(?:parameter|localparam)\b[^;]*?(\w+)\s*=', src))
    idents = set(re.findall(r'(?<![\w$])([A-Za-z_]\w*)', cond))
    return idents <= params | {"and", "or", "not"}


def _function_spans(src: str) -> List[tuple]:
    """(start, end) char offsets of every function/task body."""
    return [(m.start(), m.end()) for m in _FUNC_TASK_RE.finditer(src)]


def _matching_paren(text: str, open_idx: int) -> int:
    """Index just past the `)` matching the `(` at `open_idx`, or -1."""
    depth = 0
    for i in range(open_idx, len(text)):
        if text[i] == '(':
            depth += 1
        elif text[i] == ')':
            depth -= 1
            if depth == 0:
                return i + 1
    return -1


def _statement_after(text: str, pos: int) -> tuple:
    """(body_text, end_index) of the statement starting at `pos`.

    A `begin`…`end` block (depth-tracked, so a nested `begin` does not end it)
    or a single statement up to its `;`. Returns ("", pos) when neither is
    found, which the caller treats as "cannot analyse" rather than as "empty".
    """
    m = re.compile(r'\S').search(text, pos)
    if not m:
        return "", pos
    start = m.start()
    if text.startswith("begin", start) and not re.match(r'\w', text[start + 5:start + 6] or " "):
        depth = 0
        for km in re.finditer(r'(?<![\w$])(begin|end)(?![\w$])', text[start:]):
            if km.group(1) == "begin":
                depth += 1
            else:
                depth -= 1
                if depth == 0:
                    return text[start:start + km.end()], start + km.end()
        return text[start:], len(text)
    semi = text.find(';', start)
    if semi == -1:
        return "", pos
    return text[start:semi + 1], semi + 1


def _strip_conditional_bodies(text: str) -> str:
    """`text` with the body of every `if`/`case` removed, leaving statement-level
    code. Used to find the unconditional assignments that make a later `if`
    latch-free."""
    out = text
    for _ in range(24):                       # bounded: nesting is not deep
        m = re.search(r'(?<![\w$])(if|case[szx]?)\s*\(', out)
        if not m:
            break
        close = _matching_paren(out, m.end() - 1)
        if close == -1:
            out = out[:m.start()]
            break
        body, end = _statement_after(out, close)
        if not body:
            out = out[:m.start()]
            break
        rest = out[end:]
        em = re.match(r'\s*else(?![\w$])', rest)
        if em:
            _eb, end = _statement_after(out, end + em.end())
        out = out[:m.start()] + " " + out[end:]
    return out

def _is_edge_triggered_block(src: str, blk_start: int, off: int) -> bool:
    """True when the `always` at `blk_start` is sequential, not combinational.

    A latch is inferred only when a COMBINATIONAL block leaves a path
    unassigned. In an edge-triggered block the same shape is an enabled
    flip-flop: the value holds until the next edge because that is what a
    register does, and no level-sensitive element appears.

    Sequential by DECLARATION (`always_ff`, and `always_latch`, which is a latch
    the designer asked for) or by EVENT CONTROL (`posedge`/`negedge` in the
    sensitivity list). `always @*`, `always @(*)`, `always_comb` and a plain
    level-sensitive list are combinational and return False.

    Only the header is examined — the region from the keyword up to the end of
    the event control — so a `posedge` appearing in the BODY (a nested block, a
    string, a comment) cannot silence the rule for the whole enclosing block.
    """
    head = src[blk_start:off]
    kw = re.match(r'always(_ff|_comb|_latch)?', head)
    if kw and kw.group(1) in ("_ff", "_latch"):
        return True
    if kw and kw.group(1) == "_comb":
        return False
    at = head.find("@")
    if at < 0:
        return False
    rest = head[at + 1:].lstrip()
    if not rest.startswith("("):
        return False        # `always @*`
    depth, end = 0, -1
    for k, ch in enumerate(rest):
        if ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
            if depth == 0:
                end = k
                break
    if end < 0:
        return False        # unbalanced — do not silence on a parse failure
    return re.search(r'(?<![\w$])(?:pos|neg)edge(?![\w$])', rest[:end]) is not None


def _is_clock_gater(src: str, cond: str, sym: str) -> bool:
    """True when this latch IS an integrated clock-gating cell.

    The behavioural model of an ICG is a latch by construction, and flagging
    every clock gater in a design gets the whole rule waived — taking the real
    findings with it. MEASURED on Ibex (`prim_clock_gating.v`, 3 copies in the
    corpus):

        always @* begin
          if (!clk_i) en_latch = en_i | test_en_i;
        end
        assign clk_o = en_latch & clk_i;

    Recognised STRUCTURALLY, never by the `_latch` in the name — matching that
    suffix would be exactly the text-proxy defect vibe-ic#561 catalogues, and a
    hand-written gater called `q` would slip through it.

    Three signals, all required:
      1. the condition is a single identifier, optionally inverted;
      2. that identifier is used as a CLOCK elsewhere (`@(posedge/negedge X)`)
         or the assignment's own output is ANDed with it;
      3. the latched signal is ANDed with that same identifier in a continuous
         assignment — the gating itself.
    (3) is the load-bearing one: an ordinary latch never feeds an AND with its
    own enable condition.
    """
    m = re.fullmatch(r'\s*(!|~)?\s*([A-Za-z_]\w*)\s*', cond)
    if not m:
        return False
    clk = m.group(2)
    gated = re.compile(
        r'assign\s+\w+\s*=\s*(?:' + re.escape(sym) + r'\s*&\s*' + re.escape(clk)
        + r'|' + re.escape(clk) + r'\s*&\s*' + re.escape(sym) + r')\b')
    return bool(gated.search(src))

def rule_if_no_else_latch(src: str, path: str) -> List[Finding]:
    """A combinational `if` whose arms do not assign the same set (vibe-ic#563)."""
    findings: List[Finding] = []
    clocked = _clocked_always_spans(src)
    funcs = _function_spans(src) + _initial_spans(src)
    gen_spans = _generate_spans(src)

    def _is_clocked(off: int) -> bool:
        return any(lo <= off < hi for lo, hi in clocked)

    def _in_function(off: int) -> bool:
        return any(lo <= off < hi for lo, hi in funcs)

    line_starts = [0]
    for ln in src.split('\n'):
        line_starts.append(line_starts[-1] + len(ln) + 1)

    def _line_of(off: int) -> int:
        lo, hi = 0, len(line_starts) - 1
        while lo < hi - 1:
            mid = (lo + hi) // 2
            if line_starts[mid] <= off:
                lo = mid
            else:
                hi = mid
        return lo + 1

    for m in _IF_KW_RE.finditer(src):
        off = m.start()
        if _in_function(off):
            # No latch is possible in a function/task body — see _FUNC_TASK_RE.
            continue
        if _is_clocked(off):
            # A register HOLDS on the untaken arm — the canonical enabled-flop
            # idiom, not a latch. This is the #770 r4 exclusion, reused.
            continue
        cond_end = _matching_paren(src, m.end() - 1)
        if cond_end == -1:
            continue
        then_body, then_end = _statement_after(src, cond_end)
        if not then_body:
            continue
        if _is_generate_arm(src, src[m.end():cond_end - 1], cond_end,
                            gen_spans, off):
            # Selects which hardware exists; elaborated away, never a latch.
            continue
        # `else if` chains: treat the whole chain as one construct by letting the
        # inner `if` be visited on its own; here only the immediate else matters.
        rest = src[then_end:]
        em = re.match(r'\s*else(?![\w$])', rest)
        else_body = ""
        if em:
            else_body, _ = _statement_after(src, then_end + em.end())

        then_lhs = _procedural_assigned_lhs(then_body)
        if not then_lhs:
            continue
        else_lhs = _procedural_assigned_lhs(else_body) if else_body else set()
        uncovered = then_lhs - else_lhs
        if not uncovered:
            continue
        # A base-name assigned set cannot prove coverage of a sliced write.
        if _lhs_has_subscript(then_body) or _lhs_has_subscript(else_body):
            continue
        # An unconditional pre-assignment before the `if`, inside the same block,
        # is a default that holds — latch-free fallthrough, the same reasoning
        # `_case_body_defaulted` applies to `case`.
        blk_start = max((lo for lo, _ in
                         [(mm.start(), 0) for mm in
                          re.finditer(r'(?<![\w$])always(?:_ff|_comb|_latch)?(?![\w$])', src)]
                        if lo < off), default=None)
        # The enclosing block must actually be COMBINATIONAL. Nothing above
        # establishes that, and the finding's own text asserts it ("assigned
        # inside a combinational `if`"), so on an edge-triggered block this
        # reported a latch for the most ordinary construct in synchronous RTL:
        #
        #     always @(posedge clk or negedge rst_n)
        #       if (!rst_n) cnt <= 0; else if (en) cnt <= cnt + 1;
        #
        # `cnt` is uncovered on the untaken path and HOLDS — which is what an
        # enabled flip-flop does. No latch is inferred, because the hold is the
        # register's, not a level-sensitive one. `always_ff` says the same thing
        # by declaration, and `always_latch` is a latch the designer asked for,
        # so neither is news either.
        if blk_start is not None and _is_edge_triggered_block(src, blk_start, off):
            continue
        if blk_start is not None:
            # Everything in this block BEFORE the `if`, with each earlier
            # conditional construct's own body removed. What survives is the
            # statement-level, unconditional assignments — the defaults that hold
            # on the untaken path.
            #
            # The earlier version bailed out whenever the prefix contained ANY
            # `if`/`case`, which discards the single most common latch-free
            # idiom: a default followed by a chain of conditional updates.
            # MEASURED on Ibex's bit-manipulation unit (chip_top_sv2v.v:566-616),
            # where `rev_result = operand_a_i;` precedes five `if
            # (zbp_shift_amt[n])` updates — 14 false findings from one block.
            prefix = _strip_conditional_bodies(src[blk_start:off])
            if uncovered <= _procedural_assigned_lhs(prefix):
                continue
        cond_txt = src[m.end():cond_end - 1]
        uncovered = {s for s in uncovered
                     if not _is_clock_gater(src, cond_txt, s)}
        for sym in sorted(uncovered):
            findings.append(Finding(
                path, _line_of(off), 'WARN', 'if-no-else-latch', sym,
                f"'{sym}' is assigned inside a combinational `if` but not on "
                f"every path — it holds its value otherwise, inferring a "
                f"level-sensitive latch. Assign it in an `else`, or give it an "
                f"unconditional default before the `if`."))
    return findings


# ---------------------------------------------------------------------------
# Rule 4: Pulse signal consumed only under a state gate (pulse-swallow risk)
# ---------------------------------------------------------------------------
def rule_pulse_swallow(src: str, path: str) -> List[Finding]:
    """
    Detect the pattern:
        Producer: X <= 1'b1;  (one-cycle pulse, reset to 0 at top of always)
        Consumer: in a case branch like S_WAIT: if (X) ...
    If the consumer FSM is in a different state when X pulses, the pulse is lost.

    Conservative heuristic: flag any signal that is
      - Assigned `<= 1'b1;` or `<= 1;` AND has a default-zero assignment at top
        of an always block (classic pulse pattern)
      - Read inside a `case` branch that is not the same state as the assignment

    Reports WARN (not ERROR) because many pulses are intentionally synchronous.
    """
    findings: List[Finding] = []
    # Find one-cycle pulse producers: `sig <= 1'b1;` or `sig <= 1;`
    pulses = set()
    for m in re.finditer(r'\b(\w+)\s*<=\s*1(?:\'b1|b1|\'d1|\s*;)', src):
        pulses.add(m.group(1))
    if not pulses:
        return findings

    # For each pulse signal, check if it's read ONLY inside case-state branches
    # (heuristic: inside `S_XXX:` or `3'd\d+:` branch)
    for sig in pulses:
        # Find read sites (RHS occurrences outside its own LHS)
        reads_in_case = 0
        reads_outside_case = 0
        depth_in_case = 0
        current_block = []
        for m in re.finditer(r'\b' + re.escape(sig) + r'\b', src):
            pos = m.start()
            # Look backward for nearest `case`/`endcase`
            # v1.6.205 (#87 P1): whole-word match so `endcase` is not
            # counted as a `case` opening. Old `startswith('case', i)`
            # counted every `case` substring — including the `case`
            # inside `endcase` — pushing `in_case` to True even for
            # declarations preceded only by a closed case block. That
            # produced false-positive pulse-swallow-risk INFOs on any
            # reg declared after a function-internal case (very common
            # in spec-compliant FSMs). chip-AGNOSTIC.
            before = src[:pos]
            case_opens = len(re.findall(r'\bcase[szx]?\b', before))
            case_closes = len(re.findall(r'\bendcase\b', before))
            in_case = case_opens > case_closes
            # Exclude LHS
            rest = src[pos:pos + 120]
            if re.match(r'^\w+\s*(<=|=)(?!=)', rest):
                continue
            if in_case:
                reads_in_case += 1
            else:
                reads_outside_case += 1
        if reads_in_case > 0 and reads_outside_case == 0:
            # pulse is only consumed inside case — risk of state mismatch
            # Find declaration line
            dm = re.search(r'\b(?:reg|logic|wire)\s+(?:\[[^\]]+\]\s*)?' + re.escape(sig) + r'\b', src)
            lineno = src[:dm.start()].count('\n') + 1 if dm else 1
            findings.append(Finding(path, lineno, 'INFO', 'pulse-swallow-risk', sig,
                f"pulse signal '{sig}' (<= 1'b1) read only inside case branches — "
                "if consumer is in a different state when pulse fires, the pulse is lost. "
                "Consider latching or explicit handshake."))
    return findings


# ---------------------------------------------------------------------------
# Rule 5: Reset-less registered output with no power-up initializer
# ---------------------------------------------------------------------------
# #530 — also accept PREFIXED reset spellings (w_rst / r_rst / io_rst /
# sys_reset …, common in cross-domain designs): the old anchor required the
# token to START with rst/reset, so a dual-clock module with w_rst+r_rst was
# falsely classified reset-less and fed to the power-up autofix.
# #754 / ORGANIC-20260616 (C4) — the alternation already carried the ASYNC
# prefix `a?` (areset/arst) and the alphabetic clear spellings sclr/aclr, but
# had NO SYNC prefix: the canonical synchronous-reset spelling `srst` (= s+rst,
# no underscore separator) and `sreset` were therefore NOT matched, so a
# spec-faithful `if (srst) out <= 0;` output was mis-classified reset-less and
# falsely tripped rule_uninit_registered_output. `(?:\w+_)?` cannot consume the
# bare `s` (it requires a trailing underscore). Fix: widen the async-only
# prefix `a?` to `[as]?` on BOTH the reset and rst alternatives so
# srst/sreset/arst/areset all match — matching the richer reset-name recognition
# used by the rest of the plugin. Pure recognition widening of canonical
# sync-reset spellings — chip-AGNOSTIC, deterministic.
_RESET_NAME_RE = re.compile(
    r'\b(?:\w+_)?([as]?reset[a-z_]*|[as]?rst[a-z_]*|resetn|nreset|por|sclr|aclr)\b',
    re.I)


def _block_body_after(src: str, body_start: int) -> str:
    """Return the body text of an always block that starts at `body_start`,
    bounded at the next top-level `always` / `endmodule`. Mirrors the bounding
    used by rule_reset_boundary_residual_enable so both rules agree on scope.

    ORGANIC #765 (R6C8) — the boundary MUST match the SAME flavors of `always`
    that the block discovery does (`_iter_always_blocks` finds
    `always(?:_ff|_comb|_latch)?`). The old `\\balways\\b` could NOT match
    `always_ff`/`always_comb`/`always_latch` (the trailing `_` is a word char,
    so there is no `\\b` between `always` and `_ff`). On any modern-SV design
    written purely with `always_ff`/`always_comb` (every CDC FIFO/FILO, every
    APB block), the FIRST block's body then overran to `endmodule`, swallowing
    EVERY later block — so each register looked written by many blocks across
    many clock domains and rule_multidriven_register false-WARNed. Widening the
    boundary to the same flavors keeps every block body scoped to its own block.
    chip-AGNOSTIC, purely structural."""
    tail = src[body_start:]
    nxt = re.search(r'\balways(?:_ff|_comb|_latch)?\b|\bendmodule\b', tail)
    return tail[:nxt.start()] if nxt else tail


def _reset_covered_signals(src: str) -> Set[str]:
    """ORGANIC #727 — structurally collect every signal that has an assignment
    DOMINATED by the reset condition of its enclosing reset-bearing `always`
    process, INCLUDING a single mixed process where the reset branch and the
    datapath share one block.

    A reset-bearing process is `always @(... posedge/negedge <rst> ...)` whose
    sensitivity list names a reset-like signal (so `negedge presetn`,
    `negedge rst_n`, async OR sync resets all qualify — the reset-name detector
    here is signal-structural, not a whole-module port-name early-return).

    Inside such a process, the reset branch is the `if (<cond>)` whose condition
    references that block's reset signal (e.g. `if (!presetn)`); every `<=`/`=`
    LHS in that branch (a single statement OR a `begin ... end` group) is
    credited as reset-covered. This is purely structural and chip-AGNOSTIC.
    """
    covered: Set[str] = set()
    # Match an always block and capture its sensitivity list so we can identify
    # the per-block reset signal(s) — only edges count (a level-sensitive list
    # is not a clocked reset process).
    for bm in re.finditer(r'\balways(?:_ff)?\s*@\s*\(([^)]*)\)', src):
        sens = bm.group(1)
        # Edge-triggered signals of THIS block, in list order.
        edge_sigs = re.findall(r'\b(?:pos|neg)edge\s+([A-Za-z_]\w*)', sens)
        # Reset signal(s) of THIS block, by TWO structural signals (chip-
        # AGNOSTIC — does not depend on the reset port being spelled in a known
        # way like rst/reset; catches `presetn`, `aresetn`, custom names):
        #   (1) NAME — an edge signal whose name matches the reset-name detector.
        #   (2) STRUCTURE — in an async-reset idiom `always @(posedge clk or
        #       <edge> rst)`, the reset is the edge signal that the block's
        #       leading `if` condition tests. We seed this from the head `if`
        #       below; here we keep all edge signals as candidates so the head
        #       `if` can pick the one it tests.
        edge_rst = {t for t in edge_sigs if _RESET_NAME_RE.search(t)}
        body = _block_body_after(src, bm.end())
        # The async-reset branch of a multi-edge block is the FIRST `if` whose
        # condition tests one of the block's edge signals — structurally this IS
        # the reset, regardless of its name (clk is never tested in an `if`).
        first_if = re.search(r'\bif\s*\(([^()]*(?:\([^()]*\)[^()]*)*)\)', body)
        if first_if and len(edge_sigs) >= 2:
            head_cond = first_if.group(1)
            for t in edge_sigs:
                if re.search(r'\b' + re.escape(t) + r'\b', head_cond):
                    edge_rst.add(t)
        # Walk every `if ( <cond> )` whose condition references a reset signal
        # (either a reset edge signal of this block — name- OR structure-derived
        # — or any reset-name token, which also covers the synchronous `if(rst)`
        # form in a clk-only block).
        for im in re.finditer(r'\bif\s*\(([^()]*(?:\([^()]*\)[^()]*)*)\)', body):
            cond = im.group(1)
            cond_refs_block_rst = any(re.search(r'\b' + re.escape(r) + r'\b', cond)
                                      for r in edge_rst)
            if not (cond_refs_block_rst or _RESET_NAME_RE.search(cond)):
                continue
            # The reset branch: the statement (single or begin..end) that the
            # `if` dominates. Capture up to the matching `end` for a begin-group,
            # else the single `<lhs> <= / = ...;` statement.
            after = body[im.end():]
            mblk = re.match(r'\s*begin\b', after)
            if mblk:
                # Balance begin/end to find the branch end.
                depth = 0
                idx = 0
                # Re-scan token by token for begin/end keywords.
                for km in re.finditer(r'\b(begin|end)\b', after):
                    if km.group(1) == 'begin':
                        depth += 1
                    else:
                        depth -= 1
                        if depth == 0:
                            idx = km.end()
                            break
                branch = after[:idx] if idx else after
            else:
                semi = after.find(';')
                branch = after[:semi + 1] if semi != -1 else after
            for am in re.finditer(r'(?<![<>!=])\b([A-Za-z_]\w*)(?:\[[^\]]+\])?\s*(?:<=|=)(?!=)',
                                  branch):
                lhs = am.group(1)
                if lhs not in VERILOG_KEYWORDS:
                    covered.add(lhs)
    return covered


def _case_spans(src: str) -> List[Tuple[str, int, int]]:
    """[(selector_text, case_start_off, endcase_start_off)] for every `case`,
    depth-matched (a nested case closes against the nearest unmatched endcase).
    chip-AGNOSTIC pure Verilog grammar. (ORGANIC #783 r2.)"""
    spans: List[Tuple[str, int, int]] = []
    stack: List[Tuple[int, str]] = []
    for m in re.finditer(r'\bcase[szx]?\s*\(([^)]*)\)|\bendcase\b', src):
        if m.group(0).startswith('endcase'):
            if stack:
                start, sel = stack.pop()
                spans.append((sel, start, m.start()))
        else:
            stack.append((m.start(), m.group(1) or ''))
    return spans


def _enclosing_begin_end(src: str, pos: int) -> Optional[Tuple[int, int]]:
    """The INNERMOST [after-`begin`, start-of-matching-`end`) char span that
    encloses `pos`, or None. Depth-matched; the innermost is the enclosing pair
    with the largest `begin` offset. (ORGANIC #783 r2 — used to require a
    done/valid companion in the SAME arm as a terminal output write.)"""
    best: Optional[Tuple[int, int]] = None
    stack: List[int] = []
    for m in re.finditer(r'\b(begin|end)\b', src):
        if m.group(1) == 'begin':
            stack.append(m.end())
        elif stack:
            bstart = stack.pop()
            if bstart <= pos < m.start() and (best is None or bstart > best[0]):
                best = (bstart, m.start())
    return best


def _is_valid_gated_fsm_terminal_output(src: str, name: str,
                                        reset_covered: Set[str]) -> bool:
    """ORGANIC #783 (R8C4) — structurally recognise the legitimate
    *valid-gated FSM-terminal output* pattern, which the prose heuristic
    "a registered output powers up X but the reference expects 0 at t=0"
    CONTRADICTS.

    The canonical insertion-sort / compute-then-emit FSM writes its WIDE
    result register ONLY in a terminal/computed FSM state (e.g. `DONE:
    out_data <= array[..]`), deliberately OUTSIDE the reset branch, and
    qualifies it with a companion 1-bit `done`/`valid` output that IS
    reset-covered. The consumer samples the result only when that valid
    flag asserts, so the pre-clock X is never observed and forcing
    `initial <name> = 0;` would DIVERGE the power-up value from a
    spec-faithful / golden reference (X vs 0) on equivalence/area-opt tasks.

    Downgrade to ADVISORY only when ALL of the following hold (no-leak biased
    — every clause must be structurally TRUE, else the finding keeps its
    historical hard-block power):

      (1) the module has a WORKING reset (it reset-covers >= 1 register).
          A genuinely reset-less module is UNTOUCHED — it still hard-blocks
          (the original reset-less DFF case the rule was built for).
      (2) a companion 1-bit reset-covered OUTPUT exists (a `done`/`valid`
          qualifier with a deterministic power-up value). Without such a
          handshake, the X power-up could be consumed — keep the block.
      (3) every `<=` write of `name` is dominated by a `case` whose selector
          is a reset-covered FSM state register (i.e. the output is a
          terminal/computed result, not a free-running register that merely
          FORGOT its reset). A free-running unreset output is NOT state-gated
          and stays a hard block.

    chip-AGNOSTIC, purely structural — no chip/vendor/SKU literal.
    """
    # (1) module has a working reset.
    if not reset_covered:
        return False
    # (2) >= 1 companion 1-bit reset-covered output exists (a done/valid
    #     qualifier with a deterministic power-up value).
    one_bit_outs = set(re.findall(
        r'\boutput\b\s+(?:reg|logic|wire)?\s*([A-Za-z_]\w*)\s*(?=[,;)=])', src))
    companions = {o for o in one_bit_outs if o in reset_covered and o != name}
    if not companions:
        return False
    # state-case spans: a `case(<sel>) … endcase` whose selector is a
    # reset-covered FSM state register. (ORGANIC #783 r2 Step-2.7 — the earlier
    # form computed these selectors but NEVER used them; it only checked that
    # SOME `case` keyword textually preceded the write, so a write inside a case
    # keyed on an INPUT, or in a different block entirely, was wrongly credited.)
    state_cases = [(s, e) for sel, s, e in _case_spans(src)
                   if set(re.findall(r'[A-Za-z_]\w*', sel)) & reset_covered]
    if not state_cases:
        return False
    writes = list(re.finditer(
        r'(?<![<>!=])\b' + re.escape(name) + r'(?:\[[^\]]+\])?\s*<=\s*([^;]*);', src))
    if not writes:
        return False
    for w in writes:
        rhs = w.group(1)
        # (A) reject a FREE-RUNNING / SELF-ACCUMULATING output (the X poisons
        #     every cycle and is sampled): `name` appears in its OWN RHS.
        if re.search(r'(?<![\w.])' + re.escape(name) + r'(?![\w])', rhs):
            return False
        # (B) the write must sit textually INSIDE a reset-covered state-case
        #     (terminal/computed result, not a free-running register that merely
        #     forgot its reset, nor a case keyed on an input/non-state signal).
        if not any(s < w.start() < e for s, e in state_cases):
            return False
        # (C) a companion 1-bit reset-covered output is assigned in the SAME
        #     innermost begin/end arm as the write — the done/valid-WITH-result
        #     idiom that proves the X is qualified out. A coincidental reset-
        #     covered 1-bit output elsewhere does NOT qualify (§4.05 no-leak).
        be = _enclosing_begin_end(src, w.start())
        if be is None:
            return False
        arm = src[be[0]:be[1]]
        if not any(re.search(r'(?<![\w])' + re.escape(c) + r'\s*<=', arm)
                   for c in companions):
            return False
    return True


# ORGANIC #843 (CVDP round-18 perceptron FP) — registered-output (NBA-LHS)
# detection. The bare `(?<![<>!=])\b(\w+)(?:\[[^\]]+\])?\s*<=` regex puts its
# negative lookbehind BEFORE the IDENTIFIER, not before the `<=` OPERATOR, so a
# RELATIONAL `<=` COMPARISON whose left operand is an identifier (`y_in <=
# threshold`, `if (a <= b)`, `x >= -t && x <= t`) is mis-read as a non-blocking
# ASSIGNMENT and the identifier is wrongly added to the "registered" set —
# flagging a purely COMBINATIONAL output (written only by blocking `=` inside an
# `always_comb`) as a reset-less registered output. A combinational output
# cannot power-up-X-then-be-clocked, so the rule's premise is inapplicable.
#
# The robust discriminator: a real non-blocking ASSIGNMENT `lhs <= rhs;` is a
# procedural STATEMENT (paren depth 0), whereas a relational `<=` COMPARISON
# lives inside an `if (...)` / `while (...)` / ternary condition or a wider
# expression — i.e. inside `(...)`, at paren depth > 0. We therefore keep the
# proven regex (so the matched-LHS scope is BYTE-IDENTICAL to the shipped one —
# critical for §4.05 no-leak: this must NOT start matching anything new) and
# ACCEPT a match only when its `<=` token sits at paren depth 0. This is
# STRICTLY NARROWER than the shipped set: it removes ONLY the relational-
# comparison false matches and adds nothing, so every genuine reset-less
# registered output (`always @(posedge clk) q <= d;`) STILL enters the set and
# STILL warns. Purely structural & chip-AGNOSTIC.
_NBA_LHS_RE = re.compile(r'(?<![<>!=])\b(\w+)(?:\[[^\]]+\])?\s*<=')


def _mask_comments_and_strings(s: str) -> str:
    """Length-preserving SINGLE-PASS lexer that blanks the CONTENTS of line
    comments, block comments, AND double-quoted string literals — tracking all
    three states simultaneously so a `//`/`/*` INSIDE a string is inert, and a
    `"` inside a comment is inert. ORGANIC #843 round-3 (Step-2.7): a two-stage
    `strip_comments` (string-unaware) then `blank_strings` mis-handled a `/*`/`//`
    embedded in a string literal — it treated the in-string token as a real
    comment and truncated the whole remaining source, silently dropping a genuine
    reset-less registered output (a §4.05 leak). Delimiters are preserved; only
    inner bytes become spaces, so byte offsets are unchanged."""
    out: List[str] = []
    i, n = 0, len(s)
    while i < n:
        c = s[i]
        if c == '/' and i + 1 < n and s[i + 1] == '/':
            out.append('  ')
            i += 2
            while i < n and s[i] != '\n':
                out.append(' ')
                i += 1
        elif c == '/' and i + 1 < n and s[i + 1] == '*':
            out.append('  ')
            i += 2
            while i < n and not (s[i] == '*' and i + 1 < n and s[i + 1] == '/'):
                out.append('\n' if s[i] == '\n' else ' ')
                i += 1
            if i + 1 < n:
                out.append('  ')
                i += 2
        elif c == '"':
            out.append('"')
            i += 1
            while i < n and s[i] != '"':
                if s[i] == '\\' and i + 1 < n:
                    out.append('  ')
                    i += 2
                    continue
                out.append('\n' if s[i] == '\n' else ' ')
                i += 1
            if i < n:
                out.append('"')
                i += 1
        else:
            out.append(c)
            i += 1
    return ''.join(out)


def _registered_nba_lhs(src: str) -> Set[str]:
    """Identifiers that are the LHS of a non-blocking procedural assignment
    (`<=` at paren depth 0). See the ORGANIC #843 note above — paren-depth
    gating rejects a relational `<=` COMPARISON inside `(...)` while keeping a
    genuine `lhs <= rhs;` STATEMENT. chip-AGNOSTIC.

    ORGANIC #843 round-3 (Step-2.7) — the paren depth is measured over a
    STRUCTURAL view of the source (`_mask_comments_and_strings`): a raw GLOBAL
    byte-count of `(`/`)` is corrupted by ANY unbalanced paren in a preceding
    COMMENT or STRING (`// see foo(`, `$display("(")`, a string literal whose
    bytes are `/* (`), which would push a genuine reset-less `q <= d;` to
    apparent depth>0 and silently DROP it (a §4.05 leak). The single-pass masker
    handles comment/string tokens nested in one another; the regex runs over the
    masked copy so a `<=` inside a string/comment is never matched (strictly
    narrower than the shipped raw scan — code bytes are identical in masked, so
    every genuine NBA still registers)."""
    masked = _mask_comments_and_strings(src)
    registered: Set[str] = set()
    for mm in _NBA_LHS_RE.finditer(masked):
        op = masked.find('<=', mm.start(), mm.end())
        if op == -1:
            continue
        if masked.count('(', 0, op) - masked.count(')', 0, op) != 0:
            continue   # `<=` inside `(...)` is a relational comparison
        # ORGANIC #843 round-3 (Step-2.7) — a depth-0 relational `<=` in a
        # CONTINUOUS-ASSIGN / blocking RHS (`assign le = sum <= b;`, `flag = a <=
        # b;`) is NOT a non-blocking assignment. A real NBA `lhs <= rhs;` begins a
        # STATEMENT, so the token immediately before the LHS identifier is a
        # statement boundary (`;` `)` `}` `begin`/`end`/`else`, or buffer start) —
        # NEVER an EXPRESSION operator (`=` `?` `:` or a binary operator). Reject
        # the expression-context case so a combinational output assigned only by a
        # continuous `assign` is not mistaken for a registered output.
        # Reject ONLY clear EXPRESSION operators. `:` `,` `.` are NOT rejected —
        # they legitimately precede a genuine NBA LHS (a `case` item `2'd0: q <=
        # d;`, a concat `{a, b} <= c`, a hierarchical `a.b <= c`), so rejecting
        # them would LEAK a real reset-less registered output.
        j = mm.start() - 1
        while j >= 0 and masked[j] in ' \t\r\n':
            j -= 1
        if j >= 0 and masked[j] in '=?+-*/&|^~<>!%':
            continue
        registered.add(mm.group(1))
    return registered


def rule_undriven_output_port(src: str, path: str) -> List[Finding]:
    """An OUTPUT port that is never driven anywhere in its own module.

    Such a port has no driver at all, so it holds X for the entire simulation
    (Z if it is a tri-state net). Anything that waits on it — a status flag, a
    completion signal, a handshake — waits forever, and the run ends by timeout
    rather than by mismatch, which is the hardest failure shape to attribute.

    This is the interface contract the spec declares: a module that names an
    output promises to drive it. `rule_undriven_and_unread` covers declared
    internal WIRES, but `find_declarations` does not read ANSI port headers, so
    no rule saw output PORTS; `rule_uninit_registered_output` covers a DRIVEN
    output that lacks a power-up value, which is a different defect.

    Scoped PER MODULE — a name driven in a sibling module must never credit a
    same-named port here.

    Zero-false-positive carve-outs, each for a shape where "no driver in this
    file" is legitimate rather than a defect:
      * a module with no body (no assign / always / instantiation) is a
        black-box or stub declaration;
      * `inout` ports, whose driver may legitimately be external;
      * a port connected to an instance, since the submodule may drive it.

    chip-AGNOSTIC: pure structural. No signal-name, design or vendor literal.
    """
    findings: List[Finding] = []

    for mm in re.finditer(r'\bmodule\s+(\w+)', src):
        end = src.find('endmodule', mm.end())
        body = src[mm.end():end if end != -1 else len(src)]
        mod_off = mm.end()

        # A module with no drivers at all is a black-box / stub declaration.
        if not re.search(r'\b(?:assign|always|always_ff|always_comb|initial)\b', body) \
           and not re.search(r'\.\s*\w+\s*\(', body):
            continue

        out_ports: Dict[str, int] = {}
        for m in re.finditer(
                r'\boutput\b\s+(?:(?:reg|logic|wire)\s+)?(?:signed\s+|unsigned\s+)?'
                r'(?:\[[^\]]+\]\s*)?([A-Za-z_]\w*)\s*(?=[,;)=])', body):
            name = m.group(1)
            if name and name not in VERILOG_KEYWORDS:
                out_ports.setdefault(name, src[:mod_off + m.start()].count('\n') + 1)
        if not out_ports:
            continue

        # A `.*` wildcard connection binds every same-named signal implicitly,
        # so nothing in this module can be shown undriven by inspection.
        if re.search(r'\.\s*\*', body):
            continue

        driven = collect_lhs_set(body)
        # Instance connections. `collect_instance_connections` returns a dict
        # keyed by PORT name, so two instances sharing a port name overwrite
        # each other and signals go missing — collect them directly instead.
        connected: Set[str] = set()
        for m in re.finditer(r'\.\s*\w+\s*\(([^()]*)\)', body):
            connected |= {t for t in re.findall(r'[A-Za-z_]\w*', m.group(1))
                          if t not in VERILOG_KEYWORDS}
        # SystemVerilog IMPLICIT port connection: `.q_o` with no parentheses is
        # shorthand for `.q_o(q_o)` and drives the same-named signal. This idiom
        # is pervasive in real SV; missing it reports correct code as undriven.
        for m in re.finditer(r'\.\s*([A-Za-z_]\w*)\s*(?=[,)])', body):
            connected.add(m.group(1))
        # An output given a declaration-time initialiser is driven.
        for m in re.finditer(r'\boutput\b[^;,)]*?([A-Za-z_]\w*)\s*=', body):
            driven.add(m.group(1))

        for name, lineno in sorted(out_ports.items(), key=lambda kv: kv[1]):
            if name in driven or name in connected:
                continue
            findings.append(Finding(
                path, lineno, 'ERROR', 'undriven-output-port', name,
                f"output port '{name}' is never driven in module "
                f"'{mm.group(1)}' (no assignment, no continuous driver, no "
                f"instance connection) — it holds X for the whole simulation, "
                f"so anything waiting on it never proceeds."))
    return findings


def rule_uninit_registered_output(src: str, path: str) -> List[Finding]:
    """
    Detect a REGISTERED output port (assigned via `<=` in a clocked block) in a
    module that has NO reset-like input AND gives the output NO power-up value
    (no declaration-time initializer, no `initial` block).

    Such an output powers up as X. Deterministic reference models (and the
    VerilogEval-v2 testbenches) sample the output at t=0 before the first clock
    edge and expect a deterministic 0 there, so the design mismatches on exactly
    that one pre-clock sample. Learned from VerilogEval-v2 Prob034/053/104, where
    each lost a single vector purely to an uninitialised `output reg`.

    Conservative — only fires when the module has NO reset port at all (so the
    output genuinely cannot be reset), which is precisely the reset-less DFF
    case. Reports WARN with the exact fix. chip-AGNOSTIC.
    """
    findings: List[Finding] = []

    # Output ports (ANSI or non-ANSI), capturing optional reg/logic/wire kind.
    out_ports: Dict[str, int] = {}
    for m in re.finditer(
            r'\boutput\b\s+(?:(?:reg|logic|wire)\s+)?(?:signed\s+)?'
            r'(?:\[[^\]]+\]\s*)?([A-Za-z_]\w*)\s*(?=[,;)=])', src):
        name = m.group(1)
        if name and name not in VERILOG_KEYWORDS:
            out_ports.setdefault(name, src[:m.start()].count('\n') + 1)
    if not out_ports:
        return findings

    # ORGANIC #727 — per-OUTPUT reset coverage (replaces the old whole-module
    # "if any reset port exists, suppress every finding" early-return). The old
    # guard had two defects: (1) it MISSED resets whose port name the detector
    # did not match (e.g. `presetn`), false-flagging a reset-covered output; and
    # (2) when a reset port WAS recognized, it suppressed findings for ALL
    # outputs, hiding a genuinely-unreset output in a reset-having module. We now
    # CREDIT an output only when it is structurally assigned under the reset
    # condition of its enclosing reset-bearing process (single mixed reset+
    # datapath block included), and STILL flag any output never so assigned.
    reset_covered = _reset_covered_signals(src)

    # Registered = appears on LHS of a non-blocking assignment.
    # ORGANIC #843 — paren-depth-gated so a RELATIONAL `<=` comparison
    # (`y_in <= threshold` inside an `if (...)` / expression) is NOT mistaken for
    # a non-blocking ASSIGNMENT. Strictly narrower than the old bare regex: same
    # matched-LHS scope minus the in-paren relational-comparison false matches
    # (§4.05 no-leak — see `_registered_nba_lhs`).
    registered = _registered_nba_lhs(src)
    has_initial = bool(re.search(r'\binitial\b', src))

    for name, lineno in out_ports.items():
        if name not in registered:
            continue
        # Reset-covered: assigned under the reset condition of its clocked
        # process → has a deterministic power-up value, do NOT flag.
        if name in reset_covered:
            continue
        # Declaration-time initializer: a decl line for `name` containing `=`.
        decl_init = re.search(
            r'\b(?:output|reg|logic)\b[^;\n]*\b' + re.escape(name) + r'\s*=', src)
        if decl_init or (has_initial and re.search(
                r'\binitial\b[\s\S]{0,200}?\b' + re.escape(name) + r'\s*(<=|=)', src)):
            continue
        f = Finding(
            path, lineno, 'WARN', 'uninit-registered-output', name,
            f"registered output '{name}' has no reset and no power-up initializer "
            f"-> powers up as X. A deterministic reference (and VerilogEval-style "
            f"testbenches that sample at t=0) expects 0 there. Fix (preferred, "
            f"Verilator-clean): add a separate `initial {name} = 0;` block. A "
            f"declaration initializer `output reg ... {name} = 0;` also clears the "
            f"power-up X but trips Verilator PROCASSINIT when '{name}' is ALSO "
            f"procedurally assigned (`{name} <= ...`), so prefer the `initial` block.")
        # ORGANIC #783 — the *valid-gated FSM-terminal output* pattern (a wide
        # result register written only in a terminal/computed FSM state of a
        # reset-bearing module, qualified by a reset-covered `done`/`valid`
        # companion output) CONTRADICTS the prose heuristic "the reference
        # expects 0 at t=0": the consumer reads the result only when the valid
        # flag asserts, so the pre-clock X is never observed, and forcing
        # `initial 0` here would DIVERGE the power-up value from a spec-faithful /
        # golden reference (X vs 0) on equivalence/area-opt tasks. Downgrade to
        # ADVISORY (reported, never a hard block). A truly reset-less module, a
        # free-running output that merely forgot its reset, or a state-gated
        # output with NO done/valid companion stays STRUCTURAL → hard block
        # (§4.05 no-leak — see _is_valid_gated_fsm_terminal_output).
        if _is_valid_gated_fsm_terminal_output(src, name, reset_covered):
            f = _advisory(f, _prov.PROSE_HEURISTIC, _prov.CONTRADICTED)
            f.advisory_note = (
                "valid-gated FSM-terminal output — written only in a terminal/"
                "computed FSM state of a reset-bearing module and qualified by a "
                "reset-covered done/valid companion output, so the pre-clock X is "
                "never sampled; forcing `initial 0` would diverge the power-up "
                "value from a spec-faithful / golden reference (X vs 0). "
                "Advisory, not a hard block (ORGANIC #783)")
        findings.append(f)
    return findings


# ---------------------------------------------------------------------------
# Rule 6: Incomplete sensitivity list (latch / wrong-update hazard)
# ---------------------------------------------------------------------------
def rule_incomplete_sensitivity(src: str, path: str) -> List[Finding]:
    """Flag a LEVEL-sensitive `always @(<explicit list>)` whose body reads a signal that is
    NOT in the sensitivity list — the classic incomplete-sensitivity-list bug.

    A combinational / level-sensitive block must react to every signal it reads; if it
    lists only some, it behaves like a latch that misses updates on the omitted signals.
    The fix is `always @(*)`. Edge blocks (`@(posedge/negedge ...)`) and `@(*)` / `always_comb`
    are exempt. Learned from VerilogEval-Machine Prob145: `always @(a) if (clock) p<=a;`
    misses clock-edge updates — the reference uses `always @(*) if (clock) p=a;`. chip-AGNOSTIC.
    """
    findings: List[Finding] = []
    for m in re.finditer(r'\balways\b\s*@\s*\(([^)]*)\)', src):
        sens = m.group(1)
        if '*' in sens or re.search(r'\b(pos|neg)edge\b', sens):
            continue                                   # @(*) or clocked — exempt
        listed = set(re.findall(r'[A-Za-z_]\w*', sens))
        if not listed:
            continue
        # Extract the block body: begin..end (depth-matched) or a single statement.
        rest = src[m.end():]
        bm = re.match(r'\s*begin\b', rest)
        if bm:
            depth, i, n = 0, 0, len(rest)
            tok = re.compile(r'\b(begin|end)\b')
            start = None
            for t in tok.finditer(rest):
                if t.group(1) == 'begin':
                    if depth == 0:
                        start = t.end()
                    depth += 1
                else:
                    depth -= 1
                    if depth == 0:
                        body = rest[start:t.start()]
                        break
            else:
                continue
        else:
            semi = rest.find(';')
            if semi == -1:
                continue
            body = rest[:semi + 1]
        # ORGANIC #802 — strip BASED NUMERIC LITERALS before the identifier scan.
        # A sized/unsized based literal (4'b0000, 8'hFF, 20'd0, 'h0) has a
        # base-letter-prefixed VALUE tail (b0000 / hFF / d0) that the
        # `[A-Za-z_]\w*` read scan below treats as an identifier; the sole literal
        # guard `not re.match(r"^\d", t)` only rejects DIGIT-prefixed tokens, so
        # the value tail survives and is falsely reported as a missing-sensitivity
        # read on correct combinational RTL. A based numeric literal can never be
        # a sensitivity signal, so removing it is always safe. The regex is
        # ANCHORED on the apostrophe, so a signal merely NAMED `d0` (read as
        # `q = d0;`, no apostrophe) is never over-stripped. chip-AGNOSTIC.
        body = re.sub(r"\b\d*'[sS]?[bBoOdDhH][0-9a-fA-FxXzZ_]+", " ", body)
        # LHS targets (assigned) are not "reads"; everything else read must be in the list.
        lhs = set(re.findall(r'(\w+)(?:\s*\[[^\]]*\])?\s*(?:<=|=)(?!=)', body))
        reads = {t for t in re.findall(r'[A-Za-z_]\w*', body)
                 if t not in VERILOG_KEYWORDS and t not in lhs
                 and not re.match(r"^\d", t)}
        missing = sorted(reads - listed)
        if missing:
            lineno = src[:m.start()].count('\n') + 1
            findings.append(Finding(
                path, lineno, 'WARN', 'incomplete-sensitivity-list', ','.join(missing),
                f"level-sensitive `always @({sens.strip()})` reads {missing} not in its "
                f"sensitivity list — it behaves like a latch that misses updates on those "
                f"signals. Use `always @(*)` (or add them)."))
    return findings


def _incomplete_sens_sites(src: str):
    """Yield (paren_open_idx, paren_close_idx, sens_text) for every LEVEL-sensitive
    `always @(<explicit list>)` whose body READS a signal not in the list — i.e. the
    exact firing condition of rule_incomplete_sensitivity. Shared by the WARN rule's
    autofix so detection and repair can never drift. Read-only; returns spans into src."""
    for m in re.finditer(r'\balways\b\s*@\s*(\()([^)]*)(\))', src):
        open_i, sens, close_i = m.start(1), m.group(2), m.start(3)
        if '*' in sens or re.search(r'\b(pos|neg)edge\b', sens):
            continue                                   # @(*) or clocked — exempt
        listed = set(re.findall(r'[A-Za-z_]\w*', sens))
        if not listed:
            continue
        rest = src[m.end():]
        bm = re.match(r'\s*begin\b', rest)
        if bm:
            depth, start = 0, None
            tok = re.compile(r'\b(begin|end)\b')
            body = None
            for t in tok.finditer(rest):
                if t.group(1) == 'begin':
                    if depth == 0:
                        start = t.end()
                    depth += 1
                else:
                    depth -= 1
                    if depth == 0:
                        body = rest[start:t.start()]
                        break
            if body is None:
                continue
        else:
            semi = rest.find(';')
            if semi == -1:
                continue
            body = rest[:semi + 1]
        body = re.sub(r"\b\d*'[sS]?[bBoOdDhH][0-9a-fA-FxXzZ_]+", " ", body)
        lhs = set(re.findall(r'(\w+)(?:\s*\[[^\]]*\])?\s*(?:<=|=)(?!=)', body))
        reads = {t for t in re.findall(r'[A-Za-z_]\w*', body)
                 if t not in VERILOG_KEYWORDS and t not in lhs
                 and not re.match(r"^\d", t)}
        if reads - listed:
            yield (open_i, close_i, sens)


def autofix_incomplete_sensitivity(path: Path) -> Tuple[int, List[str]]:
    """`--fix` for rule_incomplete_sensitivity: rewrite a combinational
    `always @(<explicit list>)` whose body reads an unlisted signal to `always @(*)`.

    Safe & value-preserving: for a LEVEL-sensitive (non-edge) block, `@(*)` is the
    universally-correct sensitivity list — synthesis already ignores the sim
    sensitivity list, so the netlist is unchanged, while simulation stops missing
    updates on the omitted signals (the classic incomplete-sensitivity RACE). Learned
    from a combinational multi-block divider whose second `always @(A or B)` read
    intermediate regs written by the first block → order-dependent stale reads; the
    reference uses `always @(*)`. chip-AGNOSTIC. The #533 compile-neutrality net in
    the caller reverts this (with the other fixers) if it ever breaks compilation."""
    src = path.read_text(errors="replace")
    sites = list(_incomplete_sens_sites(src))
    if not sites:
        return 0, []
    labels: List[str] = []
    # Splice from the END so earlier offsets stay valid.
    for open_i, close_i, sens in sorted(sites, key=lambda s: s[0], reverse=True):
        src = src[:open_i] + "(*)" + src[close_i + 1:]
        labels.append(f"@({sens.strip()})")
    path.write_text(src)
    return len(labels), labels


# ---------------------------------------------------------------------------
# Rule 7: vector self-shift fold (boundary bit re-introduced by an unshifted op)
# ---------------------------------------------------------------------------
# `v` is the based-zero literal regex for the boundary pad (1'b0 / 2'b00 / 'h0 …),
# deliberately NOT plain `0` so it never matches an index like `v[0]`.
_BASED_ZERO_RE = re.compile(r"\d*'[bdh]0+\b")


def rule_vector_self_shift_fold(src: str, path: str) -> List[Finding]:
    """Flag `v OP {… v[..] …, 1'b0}` (OP in | & ^): a vector OR/AND/XOR-ed with a
    SHIFTED CONCAT of ITSELF that pads a boundary `1'b0`.

    SEVERITY IS SPLIT BY THE COMPOSING OPERATOR
    (ORGANIC-20260605-boundary-fold-or-form-escalation — two consecutive
    clean-room campaigns produced the OR-form bug while the corpus sweep's
    false positives were exclusively AND-form; ORGANIC-20260723-boundary-fold-
    xor-is-edge-idiom demotes the XOR form after it false-blocked a REUSED-IP
    OpenTitan AES flow on three silicon-proven idioms):
      * `|` composition → ERROR. The unshifted operand DOMINATES the padded
        zero (x|0 = x), so the boundary bit LEAKS through and the padded edge
        bit is NOT the intended 0 (e.g. `in | {in[98:0],1'b0}` gives
        out[0]=in[0] instead of 0). This is the ONLY form with cited real-bug
        recurrences (VerilogEval-v2 Prob092 + two clean-room campaigns). The
        correct form shifts BOTH operands inside the concat:
        `{(in[98:0] | in[99:1]), 1'b0}`.
      * `^` composition → WARN (informational). `x ^ (x<<1)` / `x ^ (x>>1)` is
        the standard EDGE / TRANSITION / first-difference operator; the boundary
        bit passing through the original edge (x^0 = x) is CORRECT-BY-
        CONSTRUCTION, not a leak — leading-one detect
        (`ppc ^ {ppc[N-2:0],1'b0}`), contiguous-ones assertion
        (`$countones(mask ^ {mask[W-2:0],1'b0}) <= 2`) and delta encoding all
        rely on it. There is NO canonical "XOR boundary must be 0" idiom, so the
        XOR form is not a reliable bug signal and must NOT block; the earlier
        `^`→ERROR was an unvalidated over-generalization from the OR form (no
        real XOR-form bug was ever cited). Verify the edge bit against the
        spec's stated boundary value (informational).
      * `&` composition → WARN (informational). The padded zero DOMINATES
        (x&0 = 0), so the boundary bit is correctly MASKED — `in & {1'b0,
        in[W-1:1]}` is the legitimate, correct-by-construction neighbour-AND
        idiom (proven by the v0.2.40 corpus sweep over 305 passing samples).
    Not auto-repaired — the right slices depend on the intended neighbour
    relation. chip-AGNOSTIC. Learned from VerilogEval-v2 Prob092 (gatesv100) —
    the recurring "boundary bit by placement, not by an op" miss.
    """
    findings: List[Finding] = []
    # The composing operators are COMMUTATIVE, so the same bug can be written
    # with EITHER operand order (ORGANIC-20260605-boundary-fold-commutative-
    # match: the third consecutive clean-room recurrence wrote the zero-padded
    # shifted self-copy as the LEFT operand and escaped the vector-first-only
    # match with zero findings). Match BOTH:
    #   form A: `<ident> <|&^> { ...concat... }`   (vector first)
    #   form B: `{ ...concat... } <|&^> <ident>`   (mirrored)
    # In both forms the ident must be the UNSHIFTED whole vector (not sliced —
    # form A enforces this by `\s*` adjacency; form B adds a `(?!\s*\[)`
    # lookahead), and the concat must slice the SAME ident + carry a zero pad.
    matches = [(m.group(1), m.group(2), m.group(3), m.start())
               for m in re.finditer(
                   r'\b([A-Za-z_]\w*)\s*([|&^])\s*\{([^{}]*)\}', src)]
    matches += [(m.group(3), m.group(2), m.group(1), m.start())
                for m in re.finditer(
                    r'\{([^{}]*)\}\s*([|&^])\s*([A-Za-z_]\w*)(?!\s*\[)', src)]
    seen_keys = set()
    for lhs, op, concat, mstart in matches:
        if lhs in VERILOG_KEYWORDS:
            continue
        has_self_slice = re.search(r'\b' + re.escape(lhs) + r'\s*\[[^\]]*\]', concat)
        has_zero_pad = _BASED_ZERO_RE.search(concat)
        if has_self_slice and has_zero_pad:
            lineno = src[:mstart].count('\n') + 1
            key = (lineno, lhs, op)
            if key in seen_keys:      # same expression matched by both forms
                continue
            seen_keys.add(key)
            if op == '&':
                findings.append(Finding(
                    path, lineno, 'WARN', 'vector-self-shift-fold', lhs,
                    f"`{lhs} & {{… {lhs}[..], 1'b0}}` — AND-composition with a "
                    f"zero-padded shifted self-copy: the padded zero MASKS the "
                    f"edge bit (x&0=0), so this is the legitimate neighbour-AND "
                    f"idiom; verify the edge bit against the spec's stated "
                    f"boundary value (informational)."))
            elif op == '^':
                findings.append(Finding(
                    path, lineno, 'WARN', 'vector-self-shift-fold', lhs,
                    f"`{lhs} ^ {{… {lhs}[..], 1'b0}}` — XOR-composition with a "
                    f"zero-padded shifted self-copy is the standard EDGE / "
                    f"TRANSITION / first-difference idiom (x^(x<<1)): the boundary "
                    f"bit passing through '{lhs}'s edge is CORRECT-BY-CONSTRUCTION "
                    f"(leading-one detect, contiguous-ones $countones(..)<=2, delta "
                    f"encode), not a leak. No canonical 'XOR boundary must be 0' "
                    f"form exists, so this is informational, not a bug; verify the "
                    f"edge bit against the spec's stated boundary value."))
            else:
                findings.append(Finding(
                    path, lineno, 'ERROR', 'vector-self-shift-fold', lhs,
                    f"`{lhs} {op} {{… {lhs}[..], 1'b0}}` — {op}-composition with "
                    f"a zero-padded shifted self-copy: the UNSHIFTED operand "
                    f"DOMINATES the padded zero (x{op}0=x), so '{lhs}'s edge bit "
                    f"LEAKS through and the padded edge bit is NOT 0. Shift BOTH "
                    f"operands inside the concat "
                    f"(e.g. `{{({lhs}[hi:lo] {op} {lhs}[hi2:lo2]), 1'b0}}`) and "
                    f"verify the edge bit against the spec's stated boundary "
                    f"value."))
    return findings


# ---------------------------------------------------------------------------
# Rule 8: SV reserved-word identifier (v0.1.38, from close-loop sweep)
# ---------------------------------------------------------------------------
# iverilog 12 ALWAYS treats these as reserved, even outside their reserved
# context. Using one as a variable / port / label name produces a
# "syntax error near …" with no useful location. The list is the conservative
# intersection of (SV-2012 reserved words used in nowhere-near-anything-else
# contexts) ∩ (iverilog 12 actually rejects). Adding `parameter` / `wire` /
# `input` etc. would be redundant — Verilog-1995 already rejects those.
_RESERVED_IDENT_BLACKLIST = frozenset({
    "packed", "unique", "unique0", "priority", "final",
    "chandle", "null", "interconnect",
})


def rule_reserved_word_identifier(src: str, path: str) -> List[Finding]:
    """Flag user identifiers that match the iverilog-rejects blacklist.

    Detects in three contexts:
      (a) variable / port DECLARATION (`reg packed`, `wire [N:0] packed`,
          `input final`)
      (b) named-block / generate / instance label (`begin : final`)
      (c) module port-list position (`module m (input final, ...)`)

    Skips occurrences in the legitimate reserved context (`logic packed [3:0]`
    SystemVerilog struct, `unique case`, `priority case`, `final begin`, etc.)
    by requiring the reserved word to appear AFTER a type keyword that's
    expecting an identifier.

    chip-AGNOSTIC; iverilog-substitution-specific (per open-benchmark-methodology
    skill § 3).
    """
    findings: List[Finding] = []
    for w in _RESERVED_IDENT_BLACKLIST:
        # (a) immediately follows a type/direction keyword
        decl = re.compile(
            r'\b(reg|wire|logic|input|output|inout|integer|real|byte|shortint|int|longint)\b'
            r'(?:\s+signed)?\s*(?:\[[^\]]+\]\s*)?'
            r'\b(' + re.escape(w) + r')\b\s*(?=[,;)=]|\[)')
        for m in decl.finditer(src):
            lineno = src[:m.start()].count('\n') + 1
            findings.append(Finding(
                path, lineno, 'WARN', 'reserved-word-identifier', w,
                f"identifier '{w}' is reserved by iverilog 12 (Vibe-IC's VCS "
                f"substitute) even outside its reserved context. Using it as a "
                f"user identifier triggers 'syntax error near {w}' with no line. "
                f"Rename to '{w}_val' / '{w}_result' / similar."))
        # (b) named-block label
        label = re.compile(r'\b(?:begin|fork|module|generate)\s*:\s*(' + re.escape(w) + r')\b')
        for m in label.finditer(src):
            lineno = src[:m.start()].count('\n') + 1
            findings.append(Finding(
                path, lineno, 'WARN', 'reserved-word-identifier', w,
                f"block label '{w}' is reserved by iverilog 12. Rename."))
    return findings


# ---------------------------------------------------------------------------
# Rule 9: wire-driven-by-input read inside a clocked block (v0.1.38)
# ---------------------------------------------------------------------------
def rule_wire_input_read_in_clocked_block(src: str, path: str) -> List[Finding]:
    """Flag `wire X = f(input_port);` then `always @(posedge clk) ... X ...`.

    The wire evaluates at the same simulation instant as the clock edge —
    iverilog evaluates the continuous-assign expression in the active region;
    the NBA in the always block samples its RHS in the same active region, so
    the wire's value is computed from the PRE-edge input. Result: a one-cycle
    skew that looks like an algorithm bug.

    The fix is either (a) inline the expression inside the always block (uses
    NBA RHS pre-fetch semantics directly), or (b) pre-register the input first.

    Conservative WARN: fires only when ALL of these are true:
      • a `wire X = expr;` declaration exists where `expr` reads an input port
      • `X` appears on the RHS of `<=` inside an `always @(posedge ...)` block
      • the same `X` is NOT also assigned in any always block (else it's not a
        pure combinational helper — could be a clocked alias)
    chip-AGNOSTIC.
    """
    findings: List[Finding] = []
    # collect input port names
    input_ports: Set[str] = set()
    for m in re.finditer(
            r'\binput\b(?:\s+wire)?(?:\s+signed)?\s*(?:\[[^\]]+\]\s*)?'
            r'([A-Za-z_]\w*)\s*(?=[,;)=])', src):
        nm = m.group(1)
        if nm and nm not in VERILOG_KEYWORDS:
            input_ports.add(nm)
    if not input_ports:
        return findings
    # collect `wire X = expr;` with RHS reading at least one input port
    wire_helpers: Dict[str, Tuple[int, str]] = {}
    for m in re.finditer(
            r'\bwire\b(?:\s+signed)?\s*(?:\[[^\]]+\]\s*)?'
            r'([A-Za-z_]\w*)\s*=\s*([^;]+);', src):
        nm, rhs = m.group(1), m.group(2)
        if nm in VERILOG_KEYWORDS:
            continue
        rhs_ids = set(re.findall(r'[A-Za-z_]\w*', rhs))
        if rhs_ids & input_ports:
            wire_helpers[nm] = (src[:m.start()].count('\n') + 1, rhs.strip())
    if not wire_helpers:
        return findings
    # A wire is never the LHS of a procedural assignment (Verilog forbids
    # it), so the only thing that would disqualify a wire helper is being
    # also written via `<=` (which itself would be a syntax error, but be
    # conservative). We do NOT collect blocking `=` here — the wire's own
    # `wire X = expr;` declaration uses `=` and would self-exclude.
    proc_lhs = {mm.group(1) for mm in
                re.finditer(r'(?<![<>!=])\b(\w+)(?:\[[^\]]+\])?\s*<=', src)}
    candidates = {k: v for k, v in wire_helpers.items() if k not in proc_lhs}
    # scan posedge-clk always blocks for RHS use of a candidate
    block_re = re.compile(r'\balways\s*@\s*\(\s*(?:pos|neg)edge\b[^)]*\)\s*(begin|[^;]+;)',
                          re.M | re.S)
    for m in block_re.finditer(src):
        head_end = m.end()
        tail = src[head_end:]
        # extract body (begin..end or single statement)
        if m.group(1).strip().startswith('begin'):
            depth, body = 0, None
            for tm in re.finditer(r'\b(begin|end)\b', src[m.start():]):
                if tm.group(1) == 'begin':
                    depth += 1
                else:
                    depth -= 1
                    if depth == 0:
                        body = src[m.end():m.start() + tm.start()]
                        break
            if body is None:
                continue
        else:
            body = m.group(1)
        rhs_ids = set(re.findall(r'[A-Za-z_]\w*', body))
        # collect block-local LHS so we don't false-positive on a local var
        block_lhs = {mm.group(1) for mm in
                     re.finditer(r'(?<![<>!=])\b(\w+)(?:\[[^\]]+\])?\s*<=', body)}
        for cand, (lineno, rhs_expr) in candidates.items():
            if cand in rhs_ids and cand not in block_lhs:
                findings.append(Finding(
                    path, lineno, 'WARN',
                    'wire-input-read-in-clocked-block', cand,
                    f"`wire {cand} = {rhs_expr};` reads an input port and is "
                    f"then read inside an `always @(posedge ...)` block at the "
                    f"same simulation instant — the wire evaluates with PRE-edge "
                    f"input values (one-cycle skew). Fix: inline the expression "
                    f"inside the always block (uses NBA RHS pre-fetch semantics), "
                    f"or pre-register the input."))
                break
    return findings


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
# ---------------------------------------------------------------------------
# Rule 11: Unguarded simulation-only immediate assertion (v0.1.61)
#
# An immediate `assert (cond) [else $error(...)];` is a SIMULATION-ONLY construct.
# Synthesis front-ends reject it: yosys' `read_verilog -sv` raises
# `syntax error, unexpected TOK_ELSE` at the `else` action, and Design Compiler /
# Genus refuse it outside a pragma guard. CVDP `priority_encoder_8x3` (the
# assertion-injection task, v0.1.59 run) FAILed `yosys_synth` for exactly this —
# and the benchmark's OWN provided module shipped the same unguarded construct.
#
# The conventional, tool-agnostic remedy is to fence the construct with a
# synthesis pragma — `// synthesis translate_off … translate_on` — which yosys /
# DC / Genus honour (skip the region) while iverilog / VCS / cocotb keep it live
# in simulation. `--fix` inserts that fence deterministically so an
# assertion-injection deliverable stops false-failing the synth gate. Chip-
# AGNOSTIC, simulation-semantics-preserving (the assertion still runs in sim).
# ---------------------------------------------------------------------------
_ASSERT_IMMEDIATE_RE = re.compile(r'\bassert\b\s*(?!property\b)\(')
_GUARD_OFF_RE = re.compile(r'//\s*(?:synthesis|synopsys|pragma)?\s*translate_off', re.I)
_GUARD_ON_RE = re.compile(r'//\s*(?:synthesis|synopsys|pragma)?\s*translate_on', re.I)


def _is_testbench(raw: str, path: str) -> bool:
    """Testbenches legitimately use assertions and are never synthesized — skip them."""
    name = Path(path).name.lower()
    if re.search(r'(^|[_.])(tb|test|testbench)([_.]|$)', name):
        return True
    if re.search(r'\bmodule\s+(?:\w*_tb|tb_?\w*|testbench\w*)\b', raw, re.I):
        return True
    return False


def _guard_regions(raw: str) -> List[Tuple[int, int]]:
    """Char ranges fenced from synthesis: `translate_off`..`translate_on` and
    `` `ifdef ``/`` `ifndef `` <…SYNTH…> .. `` `endif ``. Scanned on RAW source
    because the fences are comments / preprocessor directives."""
    regions: List[Tuple[int, int]] = []
    ons = [m.end() for m in _GUARD_ON_RE.finditer(raw)]
    for m in _GUARD_OFF_RE.finditer(raw):
        off = m.start()
        nxt = [o for o in ons if o > off]
        regions.append((off, nxt[0] if nxt else len(raw)))
    for m in re.finditer(r'`(?:ifdef|ifndef)\s+(\w+)', raw):
        if 'SYNTH' in m.group(1).upper():
            end = raw.find('`endif', m.end())
            regions.append((m.start(), end + 6 if end >= 0 else len(raw)))
    return regions


def _in_region(pos: int, regions: List[Tuple[int, int]]) -> bool:
    return any(a <= pos < b for a, b in regions)


def _assert_stmt_end(s: str, start: int):
    """Return the char offset just AFTER the terminating `;` of the immediate
    assert statement beginning at `start` (covering an optional
    `else <action>` / `else begin … end`). None if it can't be bounded."""
    i = s.find('(', start)
    if i < 0:
        return None
    depth = 0
    while i < len(s):
        if s[i] == '(':
            depth += 1
        elif s[i] == ')':
            depth -= 1
            if depth == 0:
                break
        i += 1
    if i >= len(s):
        return None
    j = i + 1
    while j < len(s) and s[j] in ' \t\r\n':
        j += 1
    if s[j:j + 4] == 'else' and (j + 4 >= len(s) or not (s[j + 4].isalnum() or s[j + 4] == '_')):
        k = j + 4
        while k < len(s) and s[k] in ' \t\r\n':
            k += 1
        if s[k:k + 5] == 'begin' and (k + 5 >= len(s) or not (s[k + 5].isalnum() or s[k + 5] == '_')):
            depth = 0
            for mm in re.finditer(r'\b(begin|end)\b', s[k:]):
                depth += 1 if mm.group(1) == 'begin' else -1
                if depth == 0:
                    return k + mm.end()
            return None
        semi = s.find(';', k)
        return semi + 1 if semi >= 0 else None
    semi = s.find(';', i)
    return semi + 1 if semi >= 0 else None


def rule_unguarded_sim_only_assert(raw: str, path: str) -> List[Finding]:
    """Rule 11 — flag immediate `assert` statements not fenced from synthesis."""
    findings: List[Finding] = []
    if _is_testbench(raw, path):
        return findings
    regions = _guard_regions(raw)
    stripped = strip_comments(raw)  # offsets preserved (comments → spaces)
    for m in _ASSERT_IMMEDIATE_RE.finditer(stripped):
        pos = m.start()
        if _in_region(pos, regions):
            continue
        lineno = raw[:pos].count('\n') + 1
        findings.append(Finding(
            path, lineno, 'WARN', 'unguarded-sim-only-assert', 'assert',
            "immediate `assert` is simulation-only and breaks synthesis "
            "(yosys: syntax error near `else`); fence it with "
            "`// synthesis translate_off … translate_on` "
            "(rtl_hygiene_lint --fix inserts this)."))
    return findings


def autofix_guard_sim_only_assert(path: Path) -> Tuple[int, List[str]]:
    """Deterministically fence unguarded immediate assertions with
    `// synthesis translate_off … translate_on` so they no longer fail the
    synthesis gate while staying live in simulation.

    Safe by construction: only wraps when the assertion construct occupies whole
    lines (nothing else shares its first/last line) and only two shapes are
    handled — (A) a standalone assert statement, and (B) an `if/else-if/else`
    chain whose every controlled statement is an assert (the CVDP encoder shape).
    Anything ambiguous is left for the WARN finding + manual handling, never
    auto-edited into broken RTL. Idempotent (re-runs see the fence and skip).

    Returns (count_wrapped, [labels]). No-op (0, []) if nothing to wrap.
    """
    raw = path.read_text(errors='replace')
    if _is_testbench(raw, str(path)):
        return 0, []
    regions = _guard_regions(raw)
    stripped = strip_comments(raw)  # offsets preserved

    units: List[Tuple[int, int]] = []
    # Shape B — if/else-if/else chain of asserts (wrap the whole chain as one unit).
    chain_re = re.compile(
        r'\bif\s*\((?:[^()]|\([^()]*\))*\)\s*assert\b[^;]*;'
        r'(?:\s*else\s*(?:if\s*\((?:[^()]|\([^()]*\))*\)\s*)?assert\b[^;]*;)*')
    for m in chain_re.finditer(stripped):
        units.append((m.start(), m.end()))
    # Shape A — standalone assert statements not already inside a Shape-B unit.
    for m in _ASSERT_IMMEDIATE_RE.finditer(stripped):
        s0 = m.start()
        if any(a <= s0 < b for a, b in units):
            continue
        end = _assert_stmt_end(stripped, s0)
        if end is None:
            continue
        pj = s0 - 1
        while pj >= 0 and stripped[pj] in ' \t\r\n':
            pj -= 1
        prevtok = stripped[max(0, pj - 5):pj + 1]
        if pj < 0 or stripped[pj] == ';' or re.search(r'(?:begin|end)$', prevtok):
            units.append((s0, end))
        # else: controlled by a non-chain if/for/while — leave to the WARN finding.

    # Filter to clean, unguarded, whole-line units; wrap from bottom up.
    edits: List[Tuple[int, int, str]] = []
    labels: List[str] = []
    for (s0, e0) in units:
        if _in_region(s0, regions):
            continue
        line_start = raw.rfind('\n', 0, s0) + 1
        line_end = raw.find('\n', e0)
        if line_end < 0:
            line_end = len(raw)
        if raw[line_start:s0].strip() or raw[e0:line_end].strip():
            continue  # shares a line with other code — skip (safety)
        indent = re.match(r'[ \t]*', raw[line_start:]).group(0)
        edits.append((line_start, line_end, indent))
        labels.append(f"assert@L{raw[:s0].count(chr(10)) + 1}")

    if not edits:
        return 0, []
    for (line_start, line_end, indent) in sorted(edits, key=lambda x: x[0], reverse=True):
        raw = (raw[:line_start]
               + f"{indent}// synthesis translate_off\n"
               + raw[line_start:line_end]
               + f"\n{indent}// synthesis translate_on"
               + raw[line_end:])
    path.write_text(raw)
    return len(edits), labels


# ---------------------------------------------------------------------------
# Rule 12: Reset-boundary residual level-enable write (ORGANIC #723)
#
# A clocked register that a reset CLEARS to 0, and is then UPDATED under a
# purely LEVEL-sensitive enable that traces to a TOP-LEVEL INPUT, with NO
# registered "armed"/"settle"/"valid-after-reset" qualifier in the module, has
# the stale-enable-post-reset-write hole:
#
#     always @(posedge clk or negedge rst_n)
#         if (!rst_n)   cnt <= 0;        // (a) reset clears the register
#         else if (dw)  cnt <= cnt + 1;  // (b) level enable `dw` (== an input)
#
# If the environment leaves `dw`'s source input HIGH across reset (common when a
# reset test runs after a random-stimulus test that did not clear enables), the
# very FIRST post-reset clock edge already performs the update, so the post-reset
# "empty / zero" invariant breaks before any deliberate transaction. The
# motivating real case: a `ping_pong_buffer` async-reset test failed because a
# held-high `write_enable` performed a transfer immediately after reset release;
# the fix was a registered 2-cycle "armed" guard that blocks updates until reset
# has been de-asserted for >= 1 full cycle.
#
# CORPUS-CLEAN narrowing — fire ONLY when ALL of:
#   (a) the register is RESET-CLEARED to zero inside the block's reset branch, AND
#   (b) the SAME register is updated in an `else if(<COND>) <reg> <= ...` whose
#       <COND> gates on a PURELY-COMBINATIONAL enable that TRACES TO A TOP-LEVEL
#       INPUT (the input port directly, or via `assign`/`wire = ...` chains of
#       combinational signals) — an environment-controllable enable that can be
#       held HIGH across reset, AND
#   (c) the module contains NO registered armed/settle/valid-after-reset
#       qualifier (a reg whose name signals a post-reset settle guard).
#
# This is deliberately conservative: the ubiquitous legitimate shape
# `if(!rst_n) x<=0; else x<=d;` (unconditional else) does NOT fire (no level
# enable in the else branch); a counter gated by an INTERNAL (clocked / derived)
# enable does NOT fire (the enable is not environment-held-across-reset); and a
# design that already carries an armed/settle qualifier does NOT fire. Advisory
# WARN only. chip-AGNOSTIC: pure SV structure, no chip/vendor/SKU literal.
# ---------------------------------------------------------------------------
_ARMED_QUALIFIER_RE = re.compile(
    r'\b\w*(?:armed|settl|reset_done|rst_done|reset_rel|rst_rel|por_done|'
    r'init_done|valid_after_reset|ready_after_reset|warmup|warm_up|'
    r'startup_done|boot_done|came_out_of_reset)\w*\b', re.I)


def _collect_input_ports(src: str) -> Set[str]:
    """Top-level input port names (chip-AGNOSTIC structural scan)."""
    ports: Set[str] = set()
    for m in re.finditer(
            r'\binput\b(?:\s+wire|\s+reg|\s+logic)?(?:\s+signed)?\s*'
            r'(?:\[[^\]]+\]\s*)?([A-Za-z_]\w*)\s*(?=[,;)=])', src):
        nm = m.group(1)
        if nm and nm not in VERILOG_KEYWORDS:
            ports.add(nm)
    # ANSI port lists pack several names per `input` keyword:
    #   `module m(input clk, rst_n, we, output ...)` — `rst_n` and `we` follow a
    #   comma, not their own `input`. Walk the port-list header and attribute
    #   every bare name after an `input` (until the next direction keyword) as an
    #   input. Pure structural, no literals.
    # Walk EVERY module header (multi-module files: a non-first module's inputs
    # are otherwise missed because comma-separated names lack their own `input`).
    for hm in re.finditer(r'\bmodule\b\s+\w+\s*(#\s*\([^)]*\)\s*)?\(', src):
        depth = 0
        end = hm.end() - 1
        while end < len(src):
            if src[end] == '(':
                depth += 1
            elif src[end] == ')':
                depth -= 1
                if depth == 0:
                    break
            end += 1
        header = src[hm.end():end]
        cur_dir = None
        for tok in re.finditer(r'\b(input|output|inout)\b|([A-Za-z_]\w*)', header):
            if tok.group(1):
                cur_dir = tok.group(1)
            elif tok.group(2):
                nm = tok.group(2)
                if nm in VERILOG_KEYWORDS or nm in ('wire', 'reg', 'logic',
                                                    'signed', 'unsigned'):
                    continue
                if cur_dir == 'input':
                    ports.add(nm)
    return ports


def _traces_to_input(sig: str, input_ports: Set[str], combinational: Dict[str, str],
                     clocked: Set[str], _seen: Set[str] | None = None) -> bool:
    """True if `sig` is a top-level input, or a purely-combinational signal
    (`assign`/`wire = ...`) whose RHS chain reaches a top-level input WITHOUT
    passing through a clocked/registered signal. Conservative: a signal driven
    by a clocked reg short-circuits to False (it is not environment-held).
    """
    if _seen is None:
        _seen = set()
    if sig in input_ports:
        return True
    if sig in clocked:
        return False
    if sig in _seen:
        return False
    _seen.add(sig)
    rhs = combinational.get(sig)
    if rhs is None:
        return False
    for tok in re.findall(r'[A-Za-z_]\w*', rhs):
        if tok in VERILOG_KEYWORDS:
            continue
        if _traces_to_input(tok, input_ports, combinational, clocked, _seen):
            return True
    return False


def _enable_fanin_text(expr: str, combinational: Dict[str, str],
                       _seen: Set[str] | None = None) -> str:
    """Concatenate `expr` with the RHS text of every combinational signal it
    transitively reads. Used to detect reset-self-gating ANYWHERE in the enable's
    fan-in (e.g. `wire dw = we & rst_n; ... else if(dw) ...` — `dw` is already
    held low while reset is asserted, so it is NOT a residual-enable hole)."""
    if _seen is None:
        _seen = set()
    parts = [expr]
    for tok in re.findall(r'[A-Za-z_]\w*', expr):
        if tok in VERILOG_KEYWORDS or tok in _seen:
            continue
        _seen.add(tok)
        rhs = combinational.get(tok)
        if rhs is not None:
            parts.append(_enable_fanin_text(rhs, combinational, _seen))
    return ' '.join(parts)


def rule_reset_boundary_residual_enable(src: str, path: str) -> List[Finding]:
    """Rule 12 (ORGANIC #723) — flag a reset-cleared register updated under a
    level-sensitive, top-level-input-traced enable with no armed/settle guard."""
    findings: List[Finding] = []
    input_ports = _collect_input_ports(src)
    if not input_ports:
        return findings

    # (c) module-wide: if any registered armed/settle qualifier exists, the
    # design already guards the reset boundary — never fire.
    # `clocked_lhs`: every `<=` (NBA) target in the file. Used both as the
    # armed/settle disqualifier set and as the "not environment-held" short
    # circuit in `_traces_to_input` (a registered signal is never an external
    # held-high enable). Over-approximating membership is the safe direction.
    clocked_lhs: Set[str] = set()
    for mm in re.finditer(r'(?<![<>!=])\b(\w+)(?:\[[^\]]+\])?\s*<=(?!=)', src):
        clocked_lhs.add(mm.group(1))
    if any(_ARMED_QUALIFIER_RE.search(nm) for nm in clocked_lhs):
        return findings

    # Combinational fan-in map: `assign X = expr;` and `wire X = expr;`.
    combinational: Dict[str, str] = {}
    for m in re.finditer(r'\bassign\s+([A-Za-z_]\w*)\s*=\s*([^;]+);', src):
        combinational.setdefault(m.group(1), m.group(2))
    for m in re.finditer(
            r'\bwire\b(?:\s+signed)?\s*(?:\[[^\]]+\]\s*)?'
            r'([A-Za-z_]\w*)\s*=\s*([^;]+);', src):
        if m.group(1) not in VERILOG_KEYWORDS:
            combinational.setdefault(m.group(1), m.group(2))

    # Scan each posedge/negedge always block for the reset-clear + level-enable
    # update on the SAME register.
    block_re = re.compile(r'\balways\s*@\s*\(\s*(?:pos|neg)edge\b[^)]*\)',
                          re.M | re.S)
    for bm in block_re.finditer(src):
        body_start = bm.end()
        # Extract the block body (begin..end or up to the next top-level always /
        # end-of-module). We only need the if/else-if chain text.
        tail = src[body_start:]
        # Bound the body: stop at the next `always`/`endmodule` at any depth — the
        # if-chain we care about is always at the head of the block.
        nxt = re.search(r'\balways\b|\bendmodule\b', tail)
        body = tail[:nxt.start()] if nxt else tail

        # (a) reset-clear: `if (<reset-cond>) <reg> <= 0;` (or '0 / {N{1'b0}}).
        # The reset condition references a reset-name signal.
        for rm in re.finditer(
                r'\bif\s*\(\s*([^()]*)\)\s*'
                r'([A-Za-z_]\w*)\s*<=\s*'
                r"(?:\d+'[bhdo]?0+|'0|0|\{[^{}]*1'b0[^{}]*\})\s*;",
                body):
            cond, reg = rm.group(1), rm.group(2)
            if not _RESET_NAME_RE.search(cond):
                continue
            # (b) same register updated under an `else if(<enable>) reg <= ...`.
            after = body[rm.end():]
            em = re.match(
                r'\s*else\s+if\s*\(\s*([^()]*(?:\([^()]*\)[^()]*)*)\)\s*'
                r'(?:begin\b)?\s*' + re.escape(reg) + r'\s*<=',
                after)
            if not em:
                continue
            enable_expr = em.group(1)
            enable_ids = [t for t in re.findall(r'[A-Za-z_]\w*', enable_expr)
                          if t not in VERILOG_KEYWORDS]
            if not enable_ids:
                continue
            # the enable must NOT reference reset anywhere in its combinational
            # fan-in (an enable like `(en & rst_n)`, directly or via a `wire dw =
            # we & rst_n;` chain, already self-gates on reset release and is not
            # a residual-enable hole).
            if _RESET_NAME_RE.search(_enable_fanin_text(enable_expr, combinational)):
                continue
            # at least one enable identifier must trace to a top-level input via
            # a purely-combinational chain (not through a clocked reg).
            traced = next(
                (t for t in enable_ids
                 if _traces_to_input(t, input_ports, combinational, clocked_lhs)),
                None)
            if traced is None:
                continue
            lineno = src[:body_start + rm.start()].count('\n') + 1
            f = Finding(
                path, lineno, 'WARN', 'reset-boundary-residual-enable', reg,
                f"register `{reg}` is reset-cleared to 0 then updated under the "
                f"level-sensitive enable `{enable_expr.strip()}` (traces to "
                f"top-level input `{traced}`) with no registered armed/settle "
                f"qualifier. A held-high enable can perform a transfer on the "
                f"FIRST post-reset clock edge, breaking the post-reset invariant. "
                f"Fix: add a registered armed/settle guard that blocks the update "
                f"until reset has been de-asserted for >= 1 full cycle (e.g. "
                f"`else if (armed && {enable_expr.strip()}) {reg} <= ...`).")
            # ORGANIC #770 round-2 — this rule is a LEVEL-ENABLE HEURISTIC: it
            # GUESSES, from a held-high enable tracing to a top-level input, that
            # a post-reset transfer is a bug. But a held-high enable on the first
            # post-reset edge is the CORRECT behaviour for the overwhelming
            # majority of valid/ready / capture registers (e.g. AXI `awvalid_q`,
            # `wvalid_q`, `timeout_flag_q`) — there is NO structural corroboration
            # that the post-reset transfer violates this design's intent. The
            # finding is PROSE_HEURISTIC with NO structural corroboration → it is
            # advisory ONLY, never a hard veto. (Non-strict callers already only
            # WARNed; this routes it out of the rc=1 / sole-emit BLOCK set.)
            f = _advisory(f, _prov.PROSE_HEURISTIC, _prov.NO_CORROBORATION)
            findings.append(f)
            break  # one finding per block is enough
    return findings


# ---------------------------------------------------------------------------
# Rule 13: Multidriven register — same reg written from >1 always block in
# genuinely different / racing clocking domains (ORGANIC #740, G4)
#
# A register written from MORE THAN ONE always block is the classic
# `verilator -Wall MULTIDRIVEN` warning: the two procedural drivers can both
# execute and the last-scheduled write wins non-deterministically. Today this
# is caught ONLY by an external `verilator -Wall`; this rule makes it a
# plugin-native, structural, advisory WARN that needs no external tool.
#
# FIRE (WARN) when the SAME reg LHS is assigned (`<=`/`=`) in >=2 distinct
# `always` blocks AND those writers can RACE:
#   * DIFFERENT clock/edge domains — block A is `@(posedge clk_a)` and block B
#     is `@(posedge clk_b)` (or `posedge`/`negedge` of the same clock): the
#     writes are unsynchronised → always a real multidriven hazard (this is
#     exactly what Verilator flags); OR
#   * SAME clock but the per-block writes to the reg are NOT mutually-exclusively
#     guarded — e.g. one block clears the reg under `if(<rst>)` while the other
#     writes it UNCONDITIONALLY (the acceptance shape: `if(rst) mem0<=0;` in one
#     block and `mem0<=mem0+1;` in another). Both fire on a reset edge → race.
#
# DO NOT FIRE (chip-AGNOSTIC, fail-SAFE — never false-WARN a legal shape):
#   * the reg is written in only ONE always block (incl. the in-block
#     `if(rst) x<=0; else x<=d;` reset+datapath idiom — one block, never racing);
#   * SAME clock AND the writer blocks are reset-COMPLEMENTARY-guarded — one
#     writes the reg only inside `if(<rst>)` and the other only inside
#     `if(!<rst>)` / `else` (they never both fire on one edge → legal split);
#   * the writers target DISJOINT bit-slices of the reg (`q[1:0]<=..` in one
#     block, `q[3:2]<=..` in another) — distinct drivers of distinct bits. This
#     exemption is PAIRWISE over ANY writer count: a reg legally split across
#     3+ always blocks (each driving its own slice) is silent too.
# Advisory WARN only; structural SV parse; no chip/vendor/SKU literal.
# ---------------------------------------------------------------------------
def _blank_string_literals(src: str) -> str:
    """Replace the INTERIOR of every Verilog double-quoted string literal with
    spaces (preserving the surrounding quotes, the TOTAL length, and every
    newline) so a keyword-shaped token inside a `$display`/`$error`/parameter
    string — e.g. the word `endmodule` or `module` — is never parsed as a
    structural boundary. Because length + newline positions are preserved, a
    caller can scan the blanked copy and index back into the ORIGINAL `src` at
    the same offsets. chip-AGNOSTIC: pure Verilog string grammar.

    ORGANIC #782 r2 (Step-2.7 §4.05): an `endmodule` token inside a string
    literal truncated `_module_regions` BEFORE a genuine same-module multidriven
    / continuous-procedural defect, so the region-scoped scan missed it (the
    masked register/illegal-l-value race verilator/iverilog flag as a real
    error). Blanking the string interior closes that leak without shifting any
    offset."""
    def _blank(m: "re.Match") -> str:
        body = m.group(0)[1:-1]
        inner = ''.join('\n' if c == '\n' else ' ' for c in body)
        return '"' + inner + '"'
    return re.sub(r'"(?:\\.|[^"\\])*"', _blank, src)


def _module_regions(src: str) -> List[Tuple[str, int, int]]:
    """ORGANIC R8C3 (#782) — partition a (comment-stripped) source file into its
    top-level module regions: a list of (module_name, start_off, end_off) where
    [start_off, end_off) spans from the `module NAME` keyword through its
    matching `endmodule`. A register name is only a multi-driven candidate when
    its driving always blocks live in the SAME module region; without this, two
    DISTINCT registers that merely SHARE A NAME across sibling modules (e.g. a
    `bit_count`/`data_reg` in both a `tx_block` and an `rx_block`) collide in the
    whole-file flat scan and false-fire as a bogus cross-domain multidriven race
    even though verilator -Wall reports ZERO MULTIDRIVEN. Verilog forbids nested
    module definitions, so a simple keyword walk (no brace nesting) is exact and
    chip-AGNOSTIC. A region before the first `module` (none, in legal SV) or an
    unterminated final module both degrade safely to the file tail.

    ORGANIC #782 r2 (Step-2.7 §4.05) — the `module`/`endmodule` walk runs over a
    STRING-BLANKED copy so a keyword token buried in a `$display`/`$error`
    string never mis-truncates a region (length-preserving, so the offsets still
    index the real `src`)."""
    regions: List[Tuple[str, int, int]] = []
    scan = _blank_string_literals(src)
    # `module NAME` … `endmodule`, scanned left-to-right. Verilog disallows a
    # module declaration inside another, so the next `endmodule` after a
    # `module NAME` always closes THAT module.
    for mm in re.finditer(r'\bmodule\b\s+([A-Za-z_]\w*)', scan):
        name = mm.group(1)
        start = mm.start()
        em = re.search(r'\bendmodule\b', scan[mm.end():])
        end = (mm.end() + em.end()) if em else len(src)
        regions.append((name, start, end))
    if not regions:
        regions.append(('', 0, len(src)))
    return regions


def _iter_always_blocks(src: str, region: Optional[Tuple[int, int]] = None):
    """Yield (sens_list_text, body_text, abs_start_offset) for every
    `always`/`always_ff`/`always_comb`/`always_latch` block. The body is bounded
    at the next top-level `always`/`endmodule` (the same head-of-block bounding
    the other rules use).

    ORGANIC R8C3 (#782) — when `region`=(lo,hi) is given, only blocks whose
    header starts inside [lo,hi) are yielded (used by rule_multidriven_register
    to confine multi-driven candidacy to a SINGLE module scope). The returned
    `abs_start_offset` is always relative to the FULL `src` so line numbers stay
    correct, and the bounded body still stops at the next always/endmodule —
    which, for the last block of a region, is that region's own `endmodule`."""
    for bm in re.finditer(r'\balways(?:_ff|_comb|_latch)?\s*@\s*\(([^)]*)\)', src):
        if region is not None and not (region[0] <= bm.start() < region[1]):
            continue
        sens = bm.group(1)
        body = _block_body_after(src, bm.end())
        yield sens, body, bm.start()


def _reg_write_guard_in_block(body: str, reg: str):
    """Classify how `reg` is written inside one always-block `body`.

    Returns a tuple (writes, slices, reset_pos, reset_neg, unconditional):
      * writes        — True if `reg` is a `<=`/`=` LHS anywhere in the block.
      * slices        — set of bit-slice strings written (`'[1:0]'`); the empty
                        string '' means a WHOLE-reg (un-sliced) write.
      * reset_pos     — True if EVERY write of `reg` is dominated by an
                        `if (<reset>)` (asserted-reset) condition.
      * reset_neg     — True if EVERY write of `reg` is dominated by an
                        `if (!<reset>)` / `else`-of-reset (deasserted) condition.
      * unconditional — True if at least one write of `reg` is NOT under any
                        reset-referencing `if`.
    Conservative & structural: a write is "reset-dominated" only when the
    nearest enclosing `if` condition (on the same source line region) references
    a reset-name signal. Deliberately simple — it just needs to separate the
    racing acceptance shape from the complementary legal split.
    """
    writes = False
    slices: Set[str] = set()
    reset_branch_only = True
    notreset_branch_only = True
    any_unconditional = False
    for am in re.finditer(
            r'(?<![<>!=])\b' + re.escape(reg) + r'\s*(\[[^\]]+\])?\s*(?:<=|=)(?!=)',
            body):
        writes = True
        slices.add((am.group(1) or '').replace(' ', ''))
        # The text from the block start up to this write tells us the nearest
        # governing condition. Find the LAST `if (...)` / `else` before it.
        prefix = body[:am.start()]
        ifs = list(re.finditer(r'\b(if)\s*\(([^()]*(?:\([^()]*\)[^()]*)*)\)|\b(else)\b',
                               prefix))
        gov = ifs[-1] if ifs else None
        if gov is None:
            any_unconditional = True
            reset_branch_only = False
            notreset_branch_only = False
            continue
        if gov.group(1) == 'if':
            cond = gov.group(2) or ''
            if _RESET_NAME_RE.search(cond):
                # determine polarity: a `!`/`~` / `==0` → deassert (complement)
                if '!' in cond or '~' in cond or re.search(r'==\s*0', cond):
                    notreset_branch_only = notreset_branch_only and True
                    reset_branch_only = False
                else:
                    reset_branch_only = reset_branch_only and True
                    notreset_branch_only = False
            else:
                any_unconditional = True
                reset_branch_only = False
                notreset_branch_only = False
        else:  # else-branch — the complement of the preceding reset `if`
            notreset_branch_only = notreset_branch_only and True
            reset_branch_only = False
    return (writes, slices,
            reset_branch_only and writes,
            notreset_branch_only and writes,
            any_unconditional)


def _slices_disjoint(slices_a: Set[str], slices_b: Set[str]) -> bool:
    """True if every write in A targets a bit-slice and every write in B
    targets a bit-slice and the two slice SETS share no slice and neither writes
    the WHOLE reg (the '' marker). Conservative: any whole-reg write ('') in
    either set means they are NOT disjoint."""
    if '' in slices_a or '' in slices_b:
        return False
    if not slices_a or not slices_b:
        return False
    return slices_a.isdisjoint(slices_b)


def _all_slices_pairwise_disjoint(slice_sets: List[Set[str]]) -> bool:
    """True when N (>=2) writer blocks each drive a DISTINCT bit-slice of a reg
    and NO two writers touch overlapping bits — i.e. every PAIR of writer
    slice-sets is `_slices_disjoint`. This generalises the disjoint-slice
    exemption from exactly-two writers to any writer count (2, 3, …): a register
    legally split across 3+ always blocks, each driving its own slice, is NOT a
    multidriven hazard (matches `verilator -Wall` reporting 0 MULTIDRIVEN).

    Conservative / fail-SAFE: reuses `_slices_disjoint`, so a whole-reg ('')
    write in ANY block, an empty slice-set, or ANY shared slice string between
    two blocks makes the group NOT-disjoint (so the genuine multidriven WARN can
    still fire). Requires >=2 sets; fewer is not a multidriven situation."""
    if len(slice_sets) < 2:
        return False
    for i in range(len(slice_sets)):
        for j in range(i + 1, len(slice_sets)):
            if not _slices_disjoint(slice_sets[i], slice_sets[j]):
                return False
    return True


def _edge_domain(sens: str) -> frozenset:
    """The (edge, signal) clocking domain of an always sensitivity list, e.g.
    {('posedge','clk')}. A level-sensitive / `*` list yields the empty set."""
    return frozenset(
        (m.group(1), m.group(2))
        for m in re.finditer(r'\b(pos|neg)edge\s+([A-Za-z_]\w*)', sens))


def _names_written_nba_in_edge_block(src: str) -> Set[str]:
    """ORGANIC #770 r2 Step-2.7 — names that receive a NON-BLOCKING (`<=`) write
    inside an EDGE-sensitive (`@(posedge/negedge …)`) always block: i.e. real
    sequential STATE / accumulators. Such a name is NEVER a mere loop index even
    if declared `integer`. chip-AGNOSTIC: pure edge-block + NBA grammar."""
    names: Set[str] = set()
    for bm in re.finditer(
            r'always(?:_ff)?\s*@\s*\(\s*(?:posedge|negedge)\b[^)]*\)',
            src, re.I):
        tail = src[bm.end():]
        nxt = re.search(r'\balways(?:_ff|_comb|_latch)?\b|\bendmodule\b', tail)
        body = tail[:nxt.start()] if nxt else tail
        for am in re.finditer(r'([A-Za-z_]\w*)(?:\s*\[[^\]]*\])?\s*<=', body):
            names.add(am.group(1))
    return names


def _loop_index_and_genvar_names(src: str) -> Set[str]:
    """Names that are LOOP-CONTROL / elaboration variables, NOT state/data
    registers: a `genvar NAME;`, or a `for (NAME = ...)` control variable /
    `integer NAME;` THAT HAS NO clocked (NBA-in-edge-block) write. ORGANIC #770
    round-2 (+ Step-2.7 tightening).

    A loop-index `i` reused across several `for` loops in different always
    blocks is NOT a multi-driven STATE register. BUT `integer` is also the
    canonical idiom for a wide counter/accumulator: a true cross-domain
    accumulator (`integer acc; always @(posedge clkX) acc <= ...`) IS legitimate
    multi-driven state and must KEEP its WARN — so a name written by a
    non-blocking assignment inside an edge-sensitive block is EXCLUDED from this
    loop-index set even if declared `integer`. chip-AGNOSTIC."""
    clocked = _names_written_nba_in_edge_block(src)
    names: Set[str] = set()
    # `genvar NAME;` is ALWAYS elaboration-only (never a data reg).
    for m in re.finditer(r'\bgenvar\b\s+([^;]+);', src):
        for nm in m.group(1).split(','):
            nm = re.sub(r'=.*', '', nm).strip()
            nm = re.sub(r'\[.*', '', nm).strip()
            if re.fullmatch(r'[A-Za-z_]\w*', nm or '') and nm not in VERILOG_KEYWORDS:
                names.add(nm)
    # `integer NAME;` — a loop/elaboration counter ONLY if it has no clocked write.
    for m in re.finditer(r'\binteger\b\s+([^;]+);', src):
        for nm in m.group(1).split(','):
            nm = re.sub(r'=.*', '', nm).strip()
            nm = re.sub(r'\[.*', '', nm).strip()
            if (re.fullmatch(r'[A-Za-z_]\w*', nm or '')
                    and nm not in VERILOG_KEYWORDS and nm not in clocked):
                names.add(nm)
    # `for (NAME = ...)` control variable — excludable only when not clocked-written.
    for m in re.finditer(r'\bfor\s*\(\s*([A-Za-z_]\w*)\s*=', src):
        nm = m.group(1)
        if nm not in VERILOG_KEYWORDS and nm not in clocked:
            names.add(nm)
    return names


def rule_multidriven_register(src: str, path: str) -> List[Finding]:
    """Rule 13 (ORGANIC #740 G4) — WARN when a reg is driven from >1 always
    block in a racing/different clocking domain."""
    findings: List[Finding] = []
    # ORGANIC #770 round-2 — loop-index integers / genvars are NOT state
    # registers; exclude them so a `for`-loop control var `i` reused across two
    # always blocks does not false-fire as a multi-driven STATE race. No-leak: a
    # genuine DATA/STATE reg (declared `reg`/`logic`, written as an FSM/datapath
    # value) is never in this set, so a real multi-driven register still WARNs.
    loop_ctrl = _loop_index_and_genvar_names(src)
    # ORGANIC R8C3 (#782) — PARTITION always-block discovery by MODULE scope
    # before building reg_block_idx. A register name is only a multi-driven
    # candidate when its >1 driving always blocks live in the SAME module. Two
    # DISTINCT registers that merely share a name across sibling modules (a
    # `bit_count` / `data_reg` in both a `tx_block` and an `rx_block`) were
    # colliding in the whole-file flat scan and false-firing a bogus
    # DIFFERENT-clocking multidriven race even though verilator -Wall reports
    # ZERO MULTIDRIVEN. No-leak: a genuine SAME-module two-block race still
    # collides within one region and still WARNs (verified). chip-AGNOSTIC: pure
    # module-scope parse.
    for _mname, _mlo, _mhi in _module_regions(src):
        findings += _multidriven_in_region(src, path, _mlo, _mhi, loop_ctrl)
    return findings


def _multidriven_in_region(src: str, path: str, mlo: int, mhi: int,
                           loop_ctrl: Set[str]) -> List[Finding]:
    """ORGANIC R8C3 (#782) — the original whole-file multidriven body, now
    confined to a SINGLE module region [mlo,mhi). Block indices/domains/guards
    are all computed only from blocks inside this region, so same-named regs in
    sibling modules never collide."""
    findings: List[Finding] = []
    blocks = [(sens, body, pos)
              for sens, body, pos in _iter_always_blocks(src, (mlo, mhi))]
    if len(blocks) < 2:
        return findings
    # collect every reg-like LHS per block (NBA or blocking) with its slice info
    # so we can see which regs are written by >1 block.
    reg_block_idx: Dict[str, List[int]] = {}
    for idx, (sens, body, pos) in enumerate(blocks):
        for am in re.finditer(
                r'(?<![<>!=])\b([A-Za-z_]\w*)\s*(?:\[[^\]]+\])?\s*(?:<=|=)(?!=)',
                body):
            nm = am.group(1)
            if nm in VERILOG_KEYWORDS:
                continue
            reg_block_idx.setdefault(nm, [])
            if idx not in reg_block_idx[nm]:
                reg_block_idx[nm].append(idx)
    for reg, idxs in sorted(reg_block_idx.items()):
        if len(idxs) < 2:
            continue
        # ORGANIC #770 round-2 — a loop-index integer / genvar is a transient
        # iteration counter, not a multi-driven STATE/data register; skip it.
        if reg in loop_ctrl:
            continue
        # gather per-block clocking domain + guard classification for THIS reg
        domains = [_edge_domain(blocks[i][0]) for i in idxs]
        guards = [_reg_write_guard_in_block(blocks[i][1], reg) for i in idxs]
        # (1) disjoint bit-slice writers → distinct drivers, not a race. This
        # holds for ANY writer count (2, 3, …): if every PAIR of writer blocks
        # drives non-overlapping bit-slices of `reg`, each block owns its own
        # bits and there is no multidriven hazard (verilator -Wall reports 0
        # MULTIDRIVEN). A single whole-reg / overlapping write breaks disjointness
        # and falls through to the genuine-race checks below.
        slice_sets = [g[1] for g in guards]   # g = (writes, slices, ...)
        if _all_slices_pairwise_disjoint(slice_sets):
            continue
        # (2) different clocking domains among the writers → ALWAYS a race
        # (this is exactly verilator's MULTIDRIVEN: "different clocking").
        distinct_domains = {d for d in domains if d}
        different_clocking = len(distinct_domains) > 1
        if different_clocking:
            lineno = src[:blocks[idxs[0]][2]].count('\n') + 1
            doms = sorted(
                "/".join(f"{e} {s}" for e, s in sorted(d)) or "comb"
                for d in distinct_domains)
            findings.append(Finding(
                path, lineno, 'WARN', 'multidriven-register', reg,
                f"register `{reg}` is driven from {len(idxs)} always blocks "
                f"with DIFFERENT clocking domains ({', '.join(doms)}) — the "
                f"writes are unsynchronised and the last-scheduled one wins "
                f"non-deterministically (`verilator -Wall` MULTIDRIVEN). Drive "
                f"`{reg}` from a SINGLE always block."))
            continue
        # (3) SAME clocking domain — fire ONLY when the writers can RACE on a
        # shared edge: i.e. they are NOT reset-complementary-guarded. The legal
        # split (`if(rst) x<=0;` in one block, `if(!rst) x<=..;` in another)
        # never both-fires on one edge → no WARN. The acceptance shape (one
        # reset-clear block + one UNCONDITIONAL datapath block) races → WARN.
        any_unconditional = any(g[4] for g in guards)
        has_reset_clear = any(g[2] for g in guards)
        all_reset_complementary = (
            all(g[2] or g[3] for g in guards)        # every block reset-guarded
            and any(g[2] for g in guards)            # at least one assert-side
            and any(g[3] for g in guards))           # at least one deassert-side
        if all_reset_complementary and not any_unconditional:
            continue                                 # legal reset/datapath split
        if any_unconditional and has_reset_clear:
            lineno = src[:blocks[idxs[0]][2]].count('\n') + 1
            findings.append(Finding(
                path, lineno, 'WARN', 'multidriven-register', reg,
                f"register `{reg}` is driven from {len(idxs)} always blocks "
                f"(multidriven): one block reset-clears it while another writes "
                f"it UNCONDITIONALLY under the same clock, so both fire on a "
                f"reset edge and the last-scheduled write wins "
                f"non-deterministically (`verilator -Wall` MULTIDRIVEN). Merge "
                f"the writes into ONE always block (gate the datapath update "
                f"with the same reset/else the clear uses)."))
    return findings


# ---------------------------------------------------------------------------
# Rule 13b (ORGANIC R8C3, #782) — CONTINUOUS-vs-PROCEDURAL driver on SAME net.
# ---------------------------------------------------------------------------
# A net driven by a continuous `assign` AND ALSO written from a procedural
# `always` block is illegal: iverilog -g2012 rejects it ("not a valid l-value
# for a procedural assignment / declared here as a wire") and verilator -Wall
# emits %Error-PROCASSWIRE. rule_multidriven_register only models always-vs-
# always races and SHORT-CIRCUITS on <2 always blocks, so a single procedural
# block fighting a continuous assign (the canonical `binary_to_gray` defect)
# was missed entirely. This is a hard, two-tool-corroborated structural defect
# — chip-AGNOSTIC, pure SV parse.
def _match_begin_end(src: str, begin_kw_off: int) -> int:
    """Given the offset of a `begin` keyword, return the offset just past its
    matching `end`. begin/end nest; the scanner also tracks the structural
    keyword pairs that introduce their OWN begin-less arms
    (case/casez/casex…endcase, function…endfunction, task…endtask,
    fork…join[_any|_none]) by counting them on the SAME depth stack so an inner
    `case` arm's `end`-less statements never desync the begin/end balance.
    chip-AGNOSTIC: pure SystemVerilog block grammar."""
    depth = 0
    for m in re.finditer(
            r'\b(begin|end|case|casez|casex|endcase|function|endfunction|'
            r'task|endtask|fork|join|join_any|join_none)\b',
            src[begin_kw_off:]):
        kw = m.group(1)
        if kw in ('begin', 'case', 'casez', 'casex', 'function', 'task', 'fork'):
            depth += 1
        else:  # end / endcase / endfunction / endtask / join*
            depth -= 1
            if depth == 0:
                return begin_kw_off + m.end()
    return len(src)


def _norm_cond(text: str) -> str:
    """Collapse a generate-if condition to a whitespace-insensitive canonical
    form (drop ALL whitespace). chip-AGNOSTIC: pure text normalisation (#799)."""
    return re.sub(r'\s+', '', text)


def _conditions_complementary(a: str, b: str) -> bool:
    """ORGANIC #799 (cross-ref #788) — True when two SEPARATE single-arm
    generate-if conditions are STRUCTURALLY complementary, i.e. exactly one of
    them can ever hold, so a driver in each can never co-elaborate:

      * logical negation        COND vs !COND   (either order)
      * equality vs inequality  X==K  vs X!=K   (same LHS, same RHS, either order)

    Both forms are decidable at elaboration time from the source text alone, so
    pairing them is sound WITHOUT a parameter solver. Anything not provably
    complementary (`if(A)` vs `if(B)`, `if(X==1)` vs `if(X==2)`) returns False so
    a genuine potential multidriver STAYS flagged.

    DELIBERATELY excludes bitwise `~COND`: `!X` is the boolean complement for ANY
    width (`!1==0`, `!0==1`), but `~X` is the bit-complement, so for a >1-bit
    operand `~EN` is still truthy when `EN` is truthy (EN=1 → ~EN=…1110 ≠ 0) and
    BOTH `if(EN)` / `if(~EN)` arms elaborate — a GENUINE multidriver
    (iverilog -g2012 rc=1). Pairing `~` would suppress that real race, so only
    `!` is a complement. chip-AGNOSTIC: pure SV expression grammar."""
    na, nb = _norm_cond(a), _norm_cond(b)
    if not na or not nb:
        return False
    # logical negation: one side is `!X` and the other is bare `X`
    for hi, lo in ((na, nb), (nb, na)):
        if hi[:1] == '!' and hi[1:2] != '=' and hi[1:] == lo:
            return True
        # tolerate a redundant outer paren on the negated side: `!(X)` vs `X`
        if hi[:2] == '!(' and hi[-1:] == ')' and hi[2:-1] == lo:
            return True
    # equality vs inequality over the SAME operands: `LHS==RHS` vs `LHS!=RHS`
    for x, y in ((na, nb), (nb, na)):
        me = re.fullmatch(r'(.+?)==(.+)', x)
        mn = re.fullmatch(r'(.+?)!=(.+)', y)
        if me and mn and me.group(1) == mn.group(1) and me.group(2) == mn.group(2):
            return True
    return False


def _generate_if_arms(src: str, mlo: int, mhi: int) -> List[List[Tuple[int, int]]]:
    """ORGANIC GAP-A — return the mutually-exclusive arm spans of every
    conditional-generate `if … begin:lbl … end else [if …] begin:lbl … end`
    chain inside module region [mlo,mhi). Each returned group is a list of
    (arm_start_off, arm_end_off) byte spans; AT MOST ONE arm of a group ever
    elaborates, so two drivers landing in DIFFERENT arms of the SAME group are
    mutually exclusive and can never co-drive a net.

    Only NAMED begin-block arms (`begin : label`) are tracked — a named begin
    immediately after `if(...)`/`else` is the canonical conditional-generate
    marker (`if (USE_FF) begin : gen_ff … end else begin : gen_comb …`). A bare
    procedural `if` inside an always block uses an UN-named begin (or no begin),
    so it is never picked up here; this keeps the suppression structurally
    confined to elaboration-time generate selection and never relaxes a genuine
    procedural same-scope race. chip-AGNOSTIC: pure SV generate-if grammar.

    ORGANIC #799 (cross-ref #788) — ALSO pairs two SEPARATE single-arm
    generate-if blocks whose conditions are structurally complementary
    (`if(COND) begin:gen_a … end` and `if(!COND) begin:gen_b … end`, NOT an
    if/else chain). #788 only walked the if/ELSE chain, so a net split across two
    complementary stand-alone ifs falsely tripped
    multidriven-continuous-procedural even though iverilog -g2012 elaborates
    exactly one arm (rc=0). Each complementary pair is emitted as its own 2-arm
    group so the two drivers read as mutually exclusive."""
    groups: List[List[Tuple[int, int]]] = []
    # #799 — stand-alone single-arm generate-ifs collected for complementary
    # pairing: (normalised-condition-text, begin_off, end_off).
    singles: List[Tuple[str, int, int]] = []
    consumed_until = mlo
    for ifm in re.finditer(r'\bif\b\s*\(', src[mlo:mhi]):
        if_abs = mlo + ifm.start()
        if if_abs < consumed_until:
            continue  # already swallowed as the `else if` of an earlier chain
        # balance the if-condition parens
        popen = mlo + ifm.end() - 1
        depth = 0
        cclose = -1
        j = popen
        while j < mhi:
            c = src[j]
            if c == '(':
                depth += 1
            elif c == ')':
                depth -= 1
                if depth == 0:
                    cclose = j
                    break
            j += 1
        if cclose < 0:
            continue
        cond_text = src[popen + 1:cclose]  # #799 — for complementary pairing
        # require a NAMED begin block immediately after the condition
        bm = re.match(r'\s*begin\b\s*:\s*[A-Za-z_]\w*', src[cclose + 1:mhi])
        if not bm:
            continue
        begin_kw = src.index('begin', cclose + 1)
        arm_end = _match_begin_end(src, begin_kw)
        arms = [(begin_kw, arm_end)]
        # walk the `else` / `else if` chain — all arms are mutually exclusive
        cur = arm_end
        while True:
            em = re.match(r'\s*else\b', src[cur:mhi])
            if not em:
                break
            after_else = cur + em.end()
            ifm2 = re.match(r'\s*if\b\s*\(', src[after_else:mhi])
            if ifm2:  # else if (...) begin : lbl
                po = after_else + ifm2.end() - 1
                d = 0
                k = po
                cc = -1
                while k < mhi:
                    if src[k] == '(':
                        d += 1
                    elif src[k] == ')':
                        d -= 1
                        if d == 0:
                            cc = k
                            break
                    k += 1
                if cc < 0:
                    break
                bm2 = re.match(r'\s*begin\b\s*:\s*[A-Za-z_]\w*', src[cc + 1:mhi])
                if not bm2:
                    break
                bkw = src.index('begin', cc + 1)
                aend = _match_begin_end(src, bkw)
                arms.append((bkw, aend))
                cur = aend
            else:  # else begin : lbl  (terminal arm)
                bm2 = re.match(r'\s*begin\b\s*:\s*[A-Za-z_]\w*', src[after_else:mhi])
                if not bm2:
                    break
                bkw = src.index('begin', after_else)
                aend = _match_begin_end(src, bkw)
                arms.append((bkw, aend))
                cur = aend
                break
        if len(arms) >= 2:
            groups.append(arms)
            consumed_until = arms[-1][1]
        else:
            # #799 — a stand-alone single-arm generate-if (no else chain).
            # Held back for complementary pairing with another stand-alone if.
            singles.append((cond_text, begin_kw, arm_end))
            consumed_until = arm_end
    # #799 — pair stand-alone single-arm ifs whose conditions are structurally
    # complementary (`if(COND)` + `if(!COND)` / `X==K` + `X!=K`). Each such pair
    # is its own mutually-exclusive 2-arm group. Greedy: each single is consumed
    # by at most one pairing so a non-complementary single is never absorbed.
    used = [False] * len(singles)
    for i in range(len(singles)):
        if used[i]:
            continue
        for k in range(i + 1, len(singles)):
            if used[k]:
                continue
            if _conditions_complementary(singles[i][0], singles[k][0]):
                groups.append([(singles[i][1], singles[i][2]),
                               (singles[k][1], singles[k][2])])
                used[i] = used[k] = True
                break
    return groups


def _drivers_mutually_exclusive(groups: List[List[Tuple[int, int]]],
                                off_a: int, off_b: int) -> bool:
    """True when off_a and off_b fall into DIFFERENT arms of the SAME
    conditional-generate group — i.e. only one of the two drivers ever
    elaborates, so they can never co-drive the net. Returns False when either
    offset is outside every tracked group, or when both land in the SAME arm (a
    genuine same-scope race that MUST stay flagged)."""
    for arms in groups:
        a_idx = next((i for i, (s, e) in enumerate(arms) if s <= off_a < e), None)
        b_idx = next((i for i, (s, e) in enumerate(arms) if s <= off_b < e), None)
        if a_idx is not None and b_idx is not None and a_idx != b_idx:
            return True
    return False


def rule_continuous_vs_procedural_driver(src: str, path: str) -> List[Finding]:
    findings: List[Finding] = []
    for _mname, mlo, mhi in _module_regions(src):
        region = src[mlo:mhi]
        # ORGANIC GAP-A — mutually-exclusive conditional-generate arms in THIS
        # module. A net whose continuous `assign` driver lives in one arm and
        # whose procedural `always` write lives in a DIFFERENT arm of the same
        # generate-if is LEGITIMATE RTL (only one arm ever elaborates), so it
        # must NOT be reported as continuous+procedural multidriven (iverilog
        # -g2012 rc=0 on such a design — confirmed). Track the absolute driver
        # offsets so the two arms can be compared structurally below.
        gen_groups = _generate_if_arms(src, mlo, mhi)
        # Continuous-assign LHS bases in THIS module (`assign NAME ... = ...`),
        # allowing an optional bit/part-select on the target.
        cont_lhs: Set[str] = set()
        cont_line: Dict[str, int] = {}
        cont_off: Dict[str, int] = {}
        for m in re.finditer(r'\bassign\b\s+(?:#\s*\S+\s+)?'
                             r'([A-Za-z_]\w*)(?:\s*\[[^\]]+\])?\s*=(?!=)', region):
            nm = m.group(1)
            if nm in VERILOG_KEYWORDS:
                continue
            cont_lhs.add(nm)
            cont_line.setdefault(nm, src[:mlo + m.start()].count('\n') + 1)
            cont_off.setdefault(nm, mlo + m.start())
        if not cont_lhs:
            continue
        # Procedural-block LHS bases in THIS module (any `<=`/`=` inside an
        # always block body), reusing the module-scoped block iterator.
        # IMPORTANT (no-leak) — `_block_body_after` bounds a body at the next
        # `always`/`endmodule`, so the LAST always block of a module OVERRUNS to
        # `endmodule` and textually swallows any CONTINUOUS `assign` statements
        # that follow it. Those swallowed `assign LHS = …;` are NOT procedural
        # writes — counting them would falsely pair a perfectly legal
        # `always @(*)`-then-`assign data_out=…` design as continuous+procedural.
        # Excise every `assign …;` statement from the body before scanning so
        # only genuine procedural `<=`/`=` writes register as proc_lhs. (iverilog
        # rc=0 / verilator no-PROCASSWIRE on those designs — confirmed.)
        proc_lhs: Set[str] = set()
        proc_line: Dict[str, int] = {}
        proc_off: Dict[str, int] = {}
        for sens, body, pos in _iter_always_blocks(src, (mlo, mhi)):
            # blank out continuous-assign statements (keep length/newlines so the
            # per-write line numbers stay correct)
            body_noassign = re.sub(
                r'\bassign\b[^;]*;',
                lambda m: ''.join('\n' if c == '\n' else ' ' for c in m.group(0)),
                body)
            for am in re.finditer(
                    r'(?<![<>!=])\b([A-Za-z_]\w*)\s*(?:\[[^\]]+\])?\s*(?:<=|=)(?!=)',
                    body_noassign):
                nm = am.group(1)
                if nm in VERILOG_KEYWORDS:
                    continue
                proc_lhs.add(nm)
                # report at the procedural-assignment site (where iverilog points)
                proc_line.setdefault(nm, src[:pos + am.start()].count('\n') + 1)
                proc_off.setdefault(nm, pos + am.start())
        for nm in sorted(cont_lhs & proc_lhs):
            # ORGANIC GAP-A — suppress when the continuous driver and the
            # procedural driver live in MUTUALLY-EXCLUSIVE conditional-generate
            # arms (only one arm elaborates → never a real multidriver). A
            # genuine SAME-scope (or SAME-arm) continuous+procedural race lands
            # both offsets outside any group / in the same arm and STILL fires.
            if _drivers_mutually_exclusive(
                    gen_groups, cont_off.get(nm, -1), proc_off.get(nm, -1)):
                continue
            ln = proc_line.get(nm, cont_line.get(nm, 1))
            findings.append(Finding(
                path, ln, 'ERROR', 'multidriven-continuous-procedural', nm,
                f"net `{nm}` is driven by BOTH a continuous `assign` (line "
                f"{cont_line.get(nm, '?')}) and a procedural `always` block — a "
                f"continuous + procedural driver on the same net is illegal "
                f"(iverilog: '`{nm}` is not a valid l-value for a procedural "
                f"assignment'; `verilator -Wall` PROCASSWIRE). Drive `{nm}` from "
                f"ONE kind of driver only."))
    return findings


# ---------------------------------------------------------------------------
# Rule 14 (ORGANIC #744 R3-1) — divide / modulo by a COMPILE-TIME-ZERO divisor
# ---------------------------------------------------------------------------
# A `localparam [W-1:0] DW = W'(2**W)` truncates to 0 (e.g. 8'(256) == 0), so
# `x % DW` / `x / DW` is modulo/divide-by-ZERO → x at runtime (a functionally
# dead pointer). This passes iverilog -g2012, verilator -Wall, AND every other
# rtl_hygiene rule — only the hidden behavioral scorer catches it. Flag a `%`/`/`
# whose divisor is a constant proven to evaluate to 0 (a width-truncated
# power-of-2-fill literal, or a bare `0` constant). chip-AGNOSTIC: pure constant
# evaluation, no chip/design literal.
_LOCALPARAM_DECL_RE = re.compile(
    r"\b(?:localparam|parameter)\b\s*"
    r"(?:integer\s+|signed\s+|unsigned\s+|logic\s+|bit\s+|reg\s+)*"
    r"(?:\[[^\]]*\]\s*)?"                            # optional packed range [W-1:0] / [7:0]
    r"(?:integer\s+|signed\s+|unsigned\s+)*"
    r"([A-Za-z_]\w*)\s*=\s*([^;]+);")


def _eval_const_int(expr: str, params: Dict[str, int]) -> Optional[int]:
    """Best-effort evaluation of a constant integer expression using only
    already-known localparam/parameter values + ** / + - * // and a SystemVerilog
    width-cast `W'(value)` (which truncates to the low W bits). Returns None when
    not a pure constant (e.g. references a signal / unknown name)."""
    e = expr.strip()
    # SV width cast: <width>'(<inner>)  → inner truncated to `width` low bits.
    m = re.fullmatch(r"\s*([A-Za-z_]\w*|\d+)\s*'\s*\(\s*(.+?)\s*\)\s*", e)
    if m:
        w = _eval_const_int(m.group(1), params)
        inner = _eval_const_int(m.group(2), params)
        if w is None or inner is None or w <= 0 or w > 4096:
            return None
        return inner & ((1 << w) - 1)        # truncate to W low bits
    # sized literal W'dN / W'hN etc. — value modulo 2**W.
    m = re.fullmatch(r"\s*(\d+)\s*'\s*[sS]?[dDhHbBoO]\s*([0-9A-Fa-f_]+)\s*", e)
    if m:
        width = int(m.group(1))
        digits = m.group(2).replace("_", "")
        try:
            val = int(digits, {"d": 10, "h": 16, "b": 2, "o": 8}[
                e[e.index("'") + 1].lower().replace("s", "d")])
        except (ValueError, KeyError):
            return None
        return val & ((1 << width) - 1) if 0 < width <= 4096 else None
    # plain decimal
    if re.fullmatch(r"\d+", e):
        return int(e)
    # known param name
    if re.fullmatch(r"[A-Za-z_]\w*", e) and e in params:
        return params[e]
    # simple binary arithmetic on two constant sub-exprs (no parens beyond cast).
    for op in ("**", "//", "*", "+", "-"):
        # split on the LAST top-level operator (avoid touching '**' as two '*').
        idx = e.rfind(op)
        if idx <= 0 or idx + len(op) >= len(e):
            continue
        if op == "*" and (e[idx - 1] == "*" or e[idx + 1] == "*"):
            continue   # part of '**'
        left = _eval_const_int(e[:idx], params)
        right = _eval_const_int(e[idx + len(op):], params)
        if left is None or right is None:
            continue
        try:
            if op == "**":
                return left ** right if right < 256 else None
            if op == "//":
                return left // right if right != 0 else None
            if op == "*":
                return left * right
            if op == "+":
                return left + right
            if op == "-":
                return left - right
        except (ValueError, ZeroDivisionError):
            return None
    return None


def _blank_string_literals(src: str) -> str:
    """Replace the CONTENTS of double-quoted string literals with spaces (keep
    the quotes + length + newlines) so a `$display("...%0d...")` format
    specifier is never mistaken for a `% 0` modulo operator. chip-AGNOSTIC."""
    out = []
    i = 0
    n = len(src)
    while i < n:
        c = src[i]
        if c == '"':
            out.append('"')
            i += 1
            while i < n and src[i] != '"':
                out.append('\n' if src[i] == '\n' else ' ')
                if src[i] == '\\' and i + 1 < n:   # skip escaped char
                    out.append(' ')
                    i += 1
                i += 1
            if i < n:
                out.append('"')
                i += 1
        else:
            out.append(c)
            i += 1
    return "".join(out)


def _harvest_header_params(src: str, consts: Dict[str, int],
                           zero_consts: Dict[str, int],
                           line_of: Dict[str, int]) -> None:
    """#750 / ORGANIC #744 R4 — seed the constant environment with module-HEADER
    parameters `module NAME #( parameter A=.., B=.. ) (...)`. The shipped Rule-14
    harvested only `;`-terminated decls (via `_LOCALPARAM_DECL_RE`), so a
    width-truncated divisor whose WIDTH source is a module-header parameter
    (`localparam [W-1:0] DW = W'(2**W)` with `#(parameter W=8)`) was missed.
    A header param with a NON-CONSTANT default resolves to None and is skipped
    (§4.05 — no false-positive risk). chip-AGNOSTIC: pure constant evaluation."""
    n = len(src)
    i = 0
    while True:
        h = src.find("#", i)
        if h < 0:
            break
        j = h + 1
        while j < n and src[j] in " \t\r\n":
            j += 1
        if j >= n or src[j] != "(":
            i = h + 1
            continue
        depth = 0
        k = j
        while k < n:
            if src[k] == "(":
                depth += 1
            elif src[k] == ")":
                depth -= 1
                if depth == 0:
                    break
            k += 1
        body = src[j + 1:k]
        base_ln = src.count("\n", 0, h) + 1
        # split on TOP-LEVEL commas
        entries, d2, last = [], 0, 0
        for idx, ch in enumerate(body):
            if ch in "([{":
                d2 += 1
            elif ch in ")]}":
                d2 -= 1
            elif ch == "," and d2 == 0:
                entries.append(body[last:idx])
                last = idx + 1
        entries.append(body[last:])
        for ent in entries:
            m = re.search(
                r"(?:parameter|localparam)?\s*"
                r"(?:integer\s+|signed\s+|unsigned\s+|logic\s+|bit\s+|reg\s+)*"
                r"(?:\[[^\]]*\]\s*)?"
                r"(?:integer\s+|signed\s+|unsigned\s+)*"
                r"([A-Za-z_]\w*)\s*=\s*(.+)$", ent.strip(), re.S)
            if not m:
                continue
            name, rhs = m.group(1), m.group(2).strip()
            if name in VERILOG_KEYWORDS or name in consts:
                continue
            val = _eval_const_int(rhs, consts)
            if val is None:
                continue
            # §4.05 — a module-header parameter whose default is a BARE INTEGER
            # LITERAL is an OVERRIDABLE PLACEHOLDER (the instantiator supplies
            # the real value, e.g. SERV's `#(parameter width=0)`): it is NOT a
            # compile-time-provable constant divisor, so it must never enter
            # `zero_consts` (a `… / width` with a default-0 placeholder is not a
            # divide-by-zero defect — the design is parameterised). A non-zero
            # bare literal is still seeded into `consts` so it can resolve a
            # derived width (`[W-1:0]`), but a bare 0 is dropped entirely so a
            # derived divisor never reads it as a hard zero. By contrast a value
            # arising from a DERIVED/TRUNCATING expression (`W'(2**W)`, the #750
            # idiom) IS provably 0 regardless of override and remains flagged.
            is_bare_literal = bool(re.fullmatch(r"\d+", rhs))
            if is_bare_literal:
                if val != 0:
                    consts[name] = val
                    line_of[name] = base_ln
                continue
            consts[name] = val
            line_of[name] = base_ln
            if val == 0:
                zero_consts[name] = base_ln
        i = k + 1


def rule_divmod_by_zero_const(src: str, path: str) -> List[Finding]:
    """Rule 14 (ORGANIC #744) — WARN on a `%` or `/` whose divisor is a
    compile-time constant that evaluates to 0 (e.g. a width-truncated
    `localparam [7:0] DW = 8'(256)` == 0). chip-AGNOSTIC."""
    findings: List[Finding] = []
    # 0. blank string-literal contents so $display("...%0d...") format specs are
    #    never read as a `% 0` divisor (printf-format blast-radius).
    src = _blank_string_literals(src)
    # 1. build the constant-localparam environment.
    consts: Dict[str, int] = {}
    zero_consts: Dict[str, int] = {}   # name -> line of a const proven == 0
    line_of: Dict[str, int] = {}
    # #750 / ORGANIC #744 R4 — seed module-HEADER parameters FIRST so a derived
    # body localparam whose WIDTH comes from a header param is provable.
    _harvest_header_params(src, consts, zero_consts, line_of)
    for m in _LOCALPARAM_DECL_RE.finditer(src):
        name, rhs = m.group(1), m.group(2)
        if name in VERILOG_KEYWORDS or name in consts:
            continue
        val = _eval_const_int(rhs, consts)
        ln = src.count("\n", 0, m.start()) + 1
        if val is not None:
            consts[name] = val
            line_of[name] = ln
            if val == 0:
                zero_consts[name] = ln
    if not zero_consts:
        # still check a bare literal-0 divisor below; otherwise nothing to do.
        pass
    # 2. scan `%`/`/` divisors. The divisor is the operand to the RIGHT of the op
    #    up to the next operator/paren/semicolon.
    for dm in re.finditer(r"(%|/)(?!/|\*)\s*([A-Za-z_]\w*|\d+\s*'\s*\w*\s*\([^)]*\)|\d+)", src):
        op = dm.group(1)
        divisor = dm.group(2).strip()
        # A real binary %/÷ has a LEFT OPERAND on the same line. A line-leading
        # `%`-coverage annotation (Verilator/covered emit `%000000  input ...`)
        # has no operand before it → skip (else `%000000` reads as `% 0`).
        line_start = src.rfind("\n", 0, dm.start()) + 1
        left = src[line_start:dm.start()].rstrip()
        if not left or left[-1] not in (
                "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_)]"):
            continue
        ln = src.count("\n", 0, dm.start()) + 1
        zero = False
        detail = ""
        if re.fullmatch(r"[A-Za-z_]\w*", divisor) and divisor in zero_consts:
            zero = True
            detail = (f"`{divisor}` is a compile-time constant that evaluates to "
                      f"0 (declared at line {zero_consts[divisor]}; a width-"
                      f"truncated literal such as W'(2**W) truncates to 0)")
        else:
            v = _eval_const_int(divisor, consts)
            if v == 0:
                zero = True
                detail = f"the divisor `{divisor}` evaluates to a constant 0"
        if zero:
            opname = "modulo" if op == "%" else "divide"
            findings.append(Finding(
                path, ln, 'WARN', 'divmod-by-zero-const', divisor,
                f"{opname}-by-zero: {detail}, so `x {op} {divisor}` is "
                f"{opname}-by-zero → x at runtime (functionally dead). Use a "
                f"non-truncated width for the divisor, or guard the divisor != 0."))
    return findings


# ---------------------------------------------------------------------------
# Rule 15: Assignment width truncation (verilator WIDTHTRUNC equivalent)
# ---------------------------------------------------------------------------
# #757 / ORGANIC-20260616 (C7) — a LINT-review prompt names "Width mismatch" as
# a category to fix, but the enabled rule set carried NO rule that flags a
# SILENT narrowing assignment (`lhs16 <= rhs32`). bitwidth_consistency_check.py
# only flags bit-select OUT-OF-RANGE (`name[hi]` beyond declared width), never
# the assignment side. verilator -Wall reports it as WIDTHTRUNC. This rule
# reproduces the single-bare-VARREF case 1:1 against verilator, and is
# deliberately CONSERVATIVE — it fires ONLY when BOTH operand widths are
# unambiguously known from `[H:L]` / `[W-1:0]` decls (so signed-arithmetic /
# extension subtleties never produce a false WARN). The author-proposed BLKSEQ /
# LATCH / UNUSEDPARAM categories are DEFERRED — they are NOT corpus-clean as a
# pure regex rule (see #757 caveat) and need a verilator-cross-validated path.
def _collect_decl_widths(src: str,
                         extra_consts: Optional[Dict[str, int]] = None
                         ) -> Dict[str, int]:
    """Map declared signal/port name -> declared bit-width, for every
    wire/reg/logic/output/input declaration whose range is a literal `[H:L]`
    or a parameterizable `[NAME-1:0]` that resolves to a constant via the
    already-known localparam/parameter map. A plain (un-ranged) scalar is
    width 1. Names whose width cannot be resolved deterministically are
    OMITTED (never guessed) so the consuming rule can only fire on widths it
    is certain about. chip-AGNOSTIC: pure structural parse, no design literal.

    `extra_consts` SEEDS the param map with constants resolved OUTSIDE this text
    (package-scope / file-scope parameters), so a per-module call can still
    resolve `[NAME-1:0]` when NAME is declared in a `package` or at file scope
    (§4.05: omitting them silently dropped a genuine within-module truncate).
    In-region params OVERRIDE the seed, so a module's own localparam still wins
    (no cross-module same-name-param collision)."""
    # Known integer params/localparams for resolving `[W-1:0]` — seeded with the
    # global (package/file-scope) consts, then overridden by in-region params.
    consts: Dict[str, int] = dict(extra_consts or {})
    for pm in re.finditer(
            r'\b(?:localparam|parameter)\b[^=;]*?\b([A-Za-z_]\w*)\s*=\s*([^,;)]+)',
            src):
        v = _eval_const_int(pm.group(2).strip(), consts)
        if v is not None:
            consts[pm.group(1)] = v

    def _range_width(hi: str, lo: str) -> Optional[int]:
        # Zero-FP discipline: only TRUST two unambiguous range forms, because
        # the shared _eval_const_int helper does not honor operator precedence
        # for mixed `*`/`-` (e.g. it reads `2*W-1` as `2*(W-1)`), and cannot
        # evaluate `$clog2(...)`. A mis-evaluated width could fabricate a
        # truncation. So:
        #   (1) PURE-LITERAL `[H:L]` (both integer literals), OR
        #   (2) the canonical `[NAME-1:0]` parameter form (width == NAME).
        # Anything else (arithmetic, $clog2, non-zero LSB) -> None (skip).
        hi_s, lo_s = hi.strip(), lo.strip()
        if re.fullmatch(r'\d+', hi_s) and re.fullmatch(r'\d+', lo_s):
            return abs(int(hi_s) - int(lo_s)) + 1
        if lo_s == '0':
            m = re.fullmatch(r'([A-Za-z_]\w*)\s*-\s*1', hi_s)
            if m and m.group(1) in consts:
                w = consts[m.group(1)]
                return w if w > 0 else None
        return None

    widths: Dict[str, int] = {}
    # Ranged decls: <kind> [signed] [H:L] name1, name2;  (kind covers ports too)
    decl_re = re.compile(
        r'\b(?:input|output|inout|wire|reg|logic)\b\s+'
        r'(?:(?:signed|unsigned)\s+)?(?:wire|reg|logic\s+)?'
        r'(?:(?:signed|unsigned)\s+)?'
        r'\[\s*([^:\]]+?)\s*:\s*([^:\]]+?)\s*\]\s*'
        r'([A-Za-z_]\w*(?:\s*,\s*[A-Za-z_]\w*)*)\s*(?=[;,)=])')
    for m in decl_re.finditer(src):
        w = _range_width(m.group(1), m.group(2))
        if w is None or w <= 0:
            continue
        for n in m.group(3).split(','):
            n = n.strip()
            if n and n not in VERILOG_KEYWORDS:
                widths.setdefault(n, w)
    # Scalar (un-ranged) decls -> width 1. Only register a scalar width when the
    # name was NOT already given a vector width above.
    scalar_re = re.compile(
        r'\b(?:input|output|inout|wire|reg|logic)\b\s+'
        r'(?:(?:signed|unsigned)\s+)?'
        r'([A-Za-z_]\w*(?:\s*,\s*[A-Za-z_]\w*)*)\s*(?=[;,)=])')
    for m in scalar_re.finditer(src):
        seg = m.group(0)
        if '[' in seg:
            continue
        for n in m.group(1).split(','):
            n = n.strip()
            if n and n not in VERILOG_KEYWORDS:
                widths.setdefault(n, 1)
    return widths


def rule_assign_width_truncate(src: str, path: str) -> List[Finding]:
    """Rule 15 (#757) — flag a blocking/non-blocking/continuous assignment whose
    RHS is a SINGLE declared signal (a bare VARREF, no slice, no operator) wider
    than the LHS declared signal — a silent width truncation (verilator
    WIDTHTRUNC).

    Conservative to the point of zero false-positives on the reference corpus:
      * RHS must be ONE bare identifier (no `[..]`, no operator, no literal) —
        expression RHS widths depend on signedness/extension rules a regex
        cannot safely infer, so they are skipped.
      * LHS must be a WHOLE-signal target (no bit-select on the LHS — a slice
        target sets its own width and is intentional).
      * BOTH widths must be known from declarations; if either is unknown the
        assignment is skipped (never guessed).
    chip-AGNOSTIC + DETERMINISTIC: no design literal, no chip name, no oracle.

    ORGANIC #757r2 (gapP) — PARTITION the width map + the assign scan by MODULE
    scope using `_module_regions` (the same helper the multidriven rule adopted
    for #782). A FLAT file-wide first-decl-wins width map collides two sibling
    modules that declare a same-named reg at DIFFERENT widths (e.g. a `mem_addr_r`
    declared `[9:0]` in one module and `[31:0]` in another): a width-CORRECT
    in-module assignment was being looked up against the OTHER module's narrower
    width → a FALSE WIDTHTRUNC WARN even though verilator -Wall reports ZERO
    truncation. Confining BOTH the decl-width map and the assign scan to a single
    region eliminates the cross-module collision while a genuine within-module
    truncation still fires (verified). chip-AGNOSTIC: pure module-scope parse.
    """
    findings: List[Finding] = []
    # §4.05: resolve package-/file-scope params GLOBALLY and seed each region, so
    # a reg whose width param lives in a `package` (outside the module) still
    # resolves [NAME-1:0] and a genuine within-module truncate is not dropped.
    gconsts = _global_param_consts(src)
    for _mname, _mlo, _mhi in _module_regions(src):
        findings += _assign_width_truncate_in_region(src, path, _mlo, _mhi,
                                                     gconsts)
    return findings


def _global_param_consts(src: str) -> Dict[str, int]:
    """Integer parameters/localparams declared OUTSIDE any module region —
    i.e. package-scope and file-scope params, which SystemVerilog scoping makes
    visible inside every module. A param declared INSIDE another module is
    deliberately excluded (it does not leak across module boundaries), so this
    cannot reintroduce the cross-module same-name collision the per-region scan
    fixes. Used to SEED per-region width resolution (`extra_consts`)."""
    regions = _module_regions(src)

    def _in_module(pos: int) -> bool:
        return any(lo <= pos < hi for _n, lo, hi in regions)

    consts: Dict[str, int] = {}
    for pm in re.finditer(
            r'\b(?:localparam|parameter)\b[^=;]*?\b([A-Za-z_]\w*)\s*=\s*([^,;)]+)',
            src):
        if _in_module(pm.start()):
            continue
        v = _eval_const_int(pm.group(2).strip(), consts)
        if v is not None:
            consts[pm.group(1)] = v
    return consts


def _assign_width_truncate_in_region(src: str, path: str,
                                     mlo: int, mhi: int,
                                     extra_consts: Optional[Dict[str, int]] = None
                                     ) -> List[Finding]:
    """ORGANIC #757r2 (gapP) — the original whole-file width-truncation body, now
    confined to a SINGLE module region [mlo,mhi). The decl-width map is built from
    THIS region's declarations only, and only assignments inside this region are
    scanned, so same-named regs at different widths in sibling modules never
    collide. Reported line numbers are computed against the FULL `src` via the
    region base offset (the `_mlo + m.start()` idiom the other module-scoped rules
    use), so line numbers stay correct. Param-width `[W-1:0]` resolution is
    preserved WITHIN the region, and `extra_consts` supplies package-/file-scope
    params declared OUTSIDE the region so they still resolve (§4.05 no-leak)."""
    findings: List[Finding] = []
    region = src[mlo:mhi]
    widths = _collect_decl_widths(region, extra_consts=extra_consts)
    if not widths:
        return findings
    seen: Set[Tuple[str, str, int]] = set()
    # <lhs> <= <rhs> ;   or   <lhs> = <rhs> ;   or   assign <lhs> = <rhs> ;
    # LHS: bare name (no subscript). RHS: bare name only, terminated by `;`.
    assign_re = re.compile(
        r'(?:\bassign\s+)?'
        r'(?<![<>!=.])\b([A-Za-z_]\w*)\s*(<=|=)(?!=)\s*'
        r'([A-Za-z_]\w*)\s*;')
    for m in assign_re.finditer(region):
        lhs, op, rhs = m.group(1), m.group(2), m.group(3)
        if lhs in VERILOG_KEYWORDS or rhs in VERILOG_KEYWORDS:
            continue
        lw = widths.get(lhs)
        rw = widths.get(rhs)
        if lw is None or rw is None:
            continue
        if rw <= lw:
            continue
        ln = src.count('\n', 0, mlo + m.start()) + 1
        key = (lhs, rhs, ln)
        if key in seen:
            continue
        seen.add(key)
        findings.append(Finding(
            path, ln, 'WARN', 'assign-width-truncate', lhs,
            f"width mismatch: `{rhs}` is {rw} bits assigned to `{lhs}` "
            f"({lw} bits) — the upper {rw - lw} bit(s) are silently dropped. "
            f"Add an explicit slice/cast (`{lhs} {op} {rhs}[{lw - 1}:0];`) or "
            f"widen `{lhs}` (verilator WIDTHTRUNC)."))
    return findings


# ---------------------------------------------------------------------------
# Rule 16: Array-reset loop INSIDE an async-reset block is an INTENDED idiom
# ---------------------------------------------------------------------------
# #749 / ORGANIC-20260616 (gshare) — a `for` loop that initialises an array
# element-by-element with BLOCKING assignments (`arr[i] = val;`) UNDER the reset
# branch of an async-reset clocked process is the CORRECT way to re-apply a
# spec-mandated reset value (PHT->weakly-not-taken, scoreboard/regfile clear) on
# EVERY async reset — the TB applies mid-stream resets, so an `initial`-only
# init never re-initialises. verilator may emit BLKLOOPINIT/BLKSEQ on that loop;
# that lint should be WAIVED, NOT "fixed" by evicting the init to `initial`.
# This rule RECOGNISES that idiom and reports it at INFO (advisory, auto-waive,
# NON-blocking) so the downstream flow records it as intended.
#
# §4.05 fail-SAFE — it does NOT fire (so it never waives) on:
#   * a combinational `for`/loop (no clock edge in the sensitivity list) — a
#     genuine combinational loop must still be caught by other rules / verilator;
#   * a blocking array write in a clocked block that is NOT under a reset branch
#     (a non-reset blocking-in-sequential is a real BLKSEQ concern, left alone).
# chip-AGNOSTIC: pure structural SV parse, no chip/vendor/SKU literal.
def _async_reset_block_bodies(src: str) -> List[Tuple[str, int]]:
    """Yield (body_text, body_start_offset) for every clocked `always` block
    whose sensitivity list is EDGE-triggered (posedge/negedge) — i.e. a
    sequential process. (Async vs sync reset is not distinguished here; the
    reset-branch dominance is established by the per-write `if(<reset>)` guard,
    which is what actually matters for re-applying the reset value.)"""
    out: List[Tuple[str, int]] = []
    for sens, body, pos in _iter_always_blocks(src):
        if re.search(r'\b(?:posedge|negedge)\b', sens):
            out.append((body, pos))
    return out


def rule_array_reset_loop_idiom(src: str, path: str) -> List[Finding]:
    findings: List[Finding] = []
    for body, _pos in _async_reset_block_bodies(src):
        # Find every `for (...) ... arr[i] = val;` blocking write to an indexed
        # target inside this sequential block, and check it is reset-dominated.
        for fm in re.finditer(r'\bfor\b\s*\(', body):
            # Bound the for body: the next `;`-terminated statement or a
            # begin/end region. Grab a conservative window after the `for(...)`.
            after = body[fm.start():fm.start() + 600]
            # Must contain a blocking indexed write `name[idx] = expr;`
            wm = re.search(r'\b([A-Za-z_]\w*)\s*\[[^\]]+\]\s*=(?!=)\s*[^;]+;', after)
            if not wm:
                continue
            arr = wm.group(1)
            if arr in VERILOG_KEYWORDS:
                continue
            # Reset-dominance: the nearest governing `if (...)` BEFORE the for
            # loop (within this block) must reference a reset-name signal.
            prefix = body[:fm.start()]
            ifs = list(re.finditer(
                r'\b(if)\s*\(([^()]*(?:\([^()]*\)[^()]*)*)\)|\b(else)\b', prefix))
            gov = ifs[-1] if ifs else None
            if gov is None or gov.group(1) != 'if':
                continue
            cond = gov.group(2) or ''
            # Must be the ASSERTED reset branch (not `!rst` / `==0` deassert).
            if not _RESET_NAME_RE.search(cond):
                continue
            if '!' in cond or '~' in cond or re.search(r'==\s*0', cond):
                continue
            ln = src.count('\n', 0, _pos) + body[:fm.start()].count('\n') + 1
            findings.append(Finding(
                path, ln, 'INFO', 'array-reset-loop-idiom', arr,
                f"intended idiom: the `for` loop blocking-initialising array "
                f"`{arr}` under the asserted-reset branch of a clocked process "
                f"re-applies the spec reset value on EVERY async reset (the TB "
                f"applies mid-stream resets). Keep it INSIDE the reset block — "
                f"do NOT evict to `initial`. If verilator emits "
                f"BLKLOOPINIT/BLKSEQ here, WAIVE the lint (advisory only)."))
    return findings


# ---------------------------------------------------------------------------
# Rule 17: Width-expand / width-truncate value-identical cast (verilator
#          WIDTHEXPAND / WIDTHTRUNC), with a value-PRESERVING `--fix`
# ---------------------------------------------------------------------------
# A blind CVDP run is scored by verilator + cocotb. When the scorer runs
# `verilator -Wall` (CVDP's default) two width diagnostics regularly FAIL an
# otherwise-correct draft that our gate did NOT pre-empt:
#
#   (a) WIDTHEXPAND — a strictly NARROWER operand summed into a strictly WIDER
#       accumulator/LHS, e.g. `logic [11:0] acc; logic [7:0] x; acc <= acc + x;`
#       The narrow operand is IMPLICITLY zero-extended; verilator -Wall flags the
#       silent extension. This is BENIGN (no value change), so the finding is an
#       advisory (non-blocking) WARN — but `--fix` makes the extension EXPLICIT
#       with a value-identical size cast `acc <= acc + 12'(x);` so the scorer's
#       width pass goes quiet without touching behaviour.
#   (b) WIDTHTRUNC — a `*`/`%` arithmetic result assigned to a strictly NARROWER
#       reg, e.g. `logic [7:0] p; p <= a * b;` (product is 16 bits). The
#       assignment ALREADY truncates to the low bits; `--fix` wraps the RHS in a
#       value-identical size cast `p <= 8'(a * b);` that drops exactly the same
#       bits, only making the (intended) truncation explicit. (The existing
#       Rule 15 only covers a BARE-VARREF truncation `lhs <= wider_sig;`; this
#       adds the arithmetic-RHS case.)
#
# CORPUS-CLEAN discipline — the auto-`--fix` only ever inserts a PROVABLY
# value-identical cast, and it fires ONLY when every guard below holds, so it can
# never change semantics on a correct design:
#   * every involved signal is UNSIGNED (a size cast of an unsigned value is a
#     pure zero-extend / low-bits-truncate — exactly the implicit behaviour; a
#     `signed` operand brings sign-extension subtleties, so it is skipped);
#   * every involved width is a PURE INTEGER LITERAL `[H:L]` (NOT a `[W-1:0]`
#     parameter form) — a numeric cast `N'(x)` baked from a parameter value would
#     TRUNCATE if the parameter were overridden larger at instantiation, so a
#     param-derived width is reported (advisory) but NEVER auto-cast;
#   * the expression is the exact two-operand accumulator (`L <= L + n;`) or
#     two-operand `*`/`%` shape — anything richer is left untouched.
# The cast is idempotent (a re-run sees `12'(x)` / `8'(a*b)`, not a bare ref, so
# it never double-wraps), and the main `--fix` path already reverts any edit that
# stops the file compiling (the #533 compile-neutrality net). chip-AGNOSTIC:
# pure structural width arithmetic, no design/vendor literal.
def _decl_width_info(region: str,
                     gconsts: Optional[Dict[str, int]] = None
                     ) -> Dict[str, Tuple[int, bool, bool]]:
    """Map a signal/port name -> (width, width_is_pure_literal, is_signed) for
    every wire/reg/logic/port declaration in `region`. Only widths that resolve
    deterministically are recorded; an unresolvable width is OMITTED (never
    guessed). `width_is_pure_literal` is True ONLY for a `[H:L]` whose bounds are
    integer literals (so a numeric cast baked from it is override-immune); a
    `[NAME-1:0]` parameter form resolves a numeric width (for the advisory
    finding) but is marked NON-literal so the auto-`--fix` skips it. A plain
    scalar is width 1 / literal True. chip-AGNOSTIC: structural parse only."""
    consts: Dict[str, int] = dict(gconsts or {})
    for pm in re.finditer(
            r'\b(?:localparam|parameter)\b[^=;]*?\b([A-Za-z_]\w*)\s*=\s*([^,;)]+)',
            region):
        v = _eval_const_int(pm.group(2).strip(), consts)
        if v is not None:
            consts[pm.group(1)] = v
    info: Dict[str, Tuple[int, bool, bool]] = {}
    # Ranged decls: <kind> [signed] [H:L] name1, name2;  (kind covers ports too).
    # The middle group cannot contain another '[' so it never spans two ranges.
    decl_re = re.compile(
        r'\b(?:input|output|inout|wire|reg|logic)\b\s+'
        r'([^;\[\]=]*?)'
        r'\[\s*([^:\]]+?)\s*:\s*([^:\]]+?)\s*\]\s*'
        r'([A-Za-z_]\w*(?:\s*,\s*[A-Za-z_]\w*)*)\s*(?=[;,)=])')
    for m in decl_re.finditer(region):
        signed = bool(re.search(r'\bsigned\b', m.group(1)))
        hi, lo = m.group(2).strip(), m.group(3).strip()
        is_lit = bool(re.fullmatch(r'\d+', hi) and re.fullmatch(r'\d+', lo))
        if is_lit:
            w: Optional[int] = abs(int(hi) - int(lo)) + 1
        else:
            w = None
            if lo == '0':
                pm2 = re.fullmatch(r'([A-Za-z_]\w*)\s*-\s*1', hi)
                if pm2 and pm2.group(1) in consts:
                    w = consts[pm2.group(1)]
            if w is None:
                continue
        if w is None or w <= 0:
            continue
        for n in m.group(4).split(','):
            n = n.strip()
            if n and n not in VERILOG_KEYWORDS and n not in info:
                info[n] = (w, is_lit, signed)
    # Scalars (un-ranged) -> width 1; only when not already a vector above.
    scalar_re = re.compile(
        r'\b(?:input|output|inout|wire|reg|logic)\b\s+'
        r'((?:signed|unsigned)\s+)?'
        r'([A-Za-z_]\w*(?:\s*,\s*[A-Za-z_]\w*)*)\s*(?=[;,)=])')
    for m in scalar_re.finditer(region):
        if '[' in m.group(0):
            continue
        signed = bool((m.group(1) or '').strip() == 'signed')
        for n in m.group(2).split(','):
            n = n.strip()
            if n and n not in VERILOG_KEYWORDS and n not in info:
                info[n] = (1, True, signed)
    return info


def _width_cast_sites(src: str) -> List[Dict]:
    """Return the list of width-cast SITES (both the auto-fixable subset and the
    advisory-only remainder) across every module region. Each site is a dict:

        {kind: 'expand'|'trunc', symbol, line, span: (start, end) in `src`,
         repl: replacement text, fixable: bool, msg}

    `span` indexes the comment-stripped `src`, whose offsets equal the raw file's
    (strip_comments is offset-preserving), so the auto-fixer can splice `repl`
    into the raw text directly. Detection precision does NOT affect safety: the
    replacement is value-identical to the original behaviour in every case the
    `fixable` guard admits, so an over-eager match can only ever add a harmless,
    behaviour-preserving cast."""
    sites: List[Dict] = []
    gconsts = _global_param_consts(src)
    for _mname, mlo, mhi in _module_regions(src):
        region = src[mlo:mhi]
        info = _decl_width_info(region, gconsts)
        if not info:
            continue
        # (a) WIDTHEXPAND accumulator:  L <= L + n ;   (or `=`, exactly 2 operands)
        for m in re.finditer(
                r'(?<![<>!=.])\b([A-Za-z_]\w*)\s*(?:<=|=)(?!=)\s*'
                r'([A-Za-z_]\w*)\s*\+\s*([A-Za-z_]\w*)\s*;', region):
            lhs, o1, o2 = m.group(1), m.group(2), m.group(3)
            if lhs in VERILOG_KEYWORDS:
                continue
            if lhs == o1:
                add, add_grp = o2, 3
            elif lhs == o2:
                add, add_grp = o1, 2
            else:
                continue                      # not a self-accumulator
            if add in VERILOG_KEYWORDS:
                continue
            li, ai = info.get(lhs), info.get(add)
            if not li or not ai:
                continue
            (wl, lit_l, sl), (wa, lit_a, sa) = li, ai
            if sl or sa or wa >= wl:           # need strictly narrower, unsigned
                continue
            a0 = mlo + m.start(add_grp)
            a1 = mlo + m.end(add_grp)
            fixable = lit_l and lit_a
            sites.append({
                'kind': 'expand', 'symbol': add,
                'line': src.count('\n', 0, a0) + 1,
                'span': (a0, a1), 'repl': f"{wl}'({add})", 'fixable': fixable,
                'msg': (f"`{add}` ({wa} bits) is implicitly "
                        f"zero-extended into `{lhs}` ({wl} bits) (verilator "
                        f"WIDTHEXPAND). " + (
                            f"--fix inserts the value-identical cast "
                            f"`{wl}'({add})`."
                            if fixable else
                            "param-derived width — reported only, not "
                            "auto-cast (override-unsafe)."))})
        # (b) WIDTHTRUNC arithmetic:  L <= a * b ;  or  L <= a % b ;  (the RHS may
        #     be parenthesised, e.g. `r <= (a % m);` — the `\(?`/`\)?` are anchored
        #     by the trailing `;` so a partial-paren expression never matches).
        for m in re.finditer(
                r'(?:\bassign\s+)?(?<![<>!=.])\b([A-Za-z_]\w*)\s*(?:<=|=)(?!=)\s*'
                r'\(?\s*([A-Za-z_]\w*)\s*([*%])\s*([A-Za-z_]\w*)\s*\)?\s*;', region):
            lhs, a, aop, b = m.group(1), m.group(2), m.group(3), m.group(4)
            if lhs in VERILOG_KEYWORDS or a in VERILOG_KEYWORDS \
                    or b in VERILOG_KEYWORDS:
                continue
            li, ai, bi = info.get(lhs), info.get(a), info.get(b)
            if not li or not ai or not bi:
                continue
            (wl, lit_l, sl), (wa, lit_a, sa), (wb, lit_b, sb) = li, ai, bi
            if sl or sa or sb:                 # unsigned only
                continue
            # verilator's generated width for BOTH `*` (MUL) and `%` (MODDIV) in
            # an assignment context is max(Wa, Wb) — empirically calibrated, NOT
            # Wa+Wb. WIDTHTRUNC fires only when that exceeds the LHS width, so the
            # common `p8 <= a8 * b8` (same-width operands) correctly does NOT fire.
            res = max(wa, wb)
            if res <= wl:                      # need a real truncation
                continue
            e0 = mlo + m.start(2)              # start of `a`
            e1 = mlo + m.end(4)                # end of `b`
            fixable = lit_l and lit_a and lit_b
            sites.append({
                'kind': 'trunc', 'symbol': lhs,
                'line': src.count('\n', 0, e0) + 1,
                'span': (e0, e1), 'repl': f"{wl}'({a} {aop} {b})",
                'fixable': fixable,
                'msg': (f"`{a} {aop} {b}` ({res} bits) assigned "
                        f"to `{lhs}` ({wl} bits) drops the upper {res - wl} "
                        f"bit(s) (verilator WIDTHTRUNC). " + (
                            f"--fix inserts the value-identical cast "
                            f"`{wl}'({a} {aop} {b})`."
                            if fixable else
                            "param-derived width — reported only, not "
                            "auto-cast (override-unsafe)."))})
    return sites


def rule_width_expand_trunc(src: str, path: str) -> List[Finding]:
    """Rule 17 — advisory (non-blocking) WARN for the WIDTHEXPAND / WIDTHTRUNC
    sites that `--fix` silences with a value-identical size cast. Advisory because
    the underlying construct is a BENIGN width-style diagnostic (an implicit
    zero-extend, or an intended low-bits truncation), not a functional bug — it
    must never hard-block an otherwise-correct draft; the real recovery is the
    value-preserving cast applied by `autofix_width_cast` under `--fix`."""
    findings: List[Finding] = []
    seen: Set[Tuple[int, int]] = set()
    for s in _width_cast_sites(src):
        if s['span'] in seen:
            continue
        seen.add(s['span'])
        f = Finding(path, s['line'], 'WARN',
                    'width-expand' if s['kind'] == 'expand'
                    else 'width-trunc-arith', s['symbol'], s['msg'])
        findings.append(_advisory(f, _prov.PROSE_HEURISTIC,
                                  _prov.NO_CORROBORATION))
    return findings


# ---------------------------------------------------------------------------
# Rule 18: Unused clock-input port (advisory WARN — likely a wiring bug)
# ---------------------------------------------------------------------------
# A declared INPUT port whose name matches a clock idiom (clk / clock / hclk /
# pclk / aclk / sclk / clk_*) that is referenced in ZERO sensitivity lists AND
# ZERO expressions anywhere in its module body can be a wiring bug — the wrong
# clock (or none) actually drives the sequential logic. This surfaces it as an
# advisory (non-blocking) WARN.
#
# CORPUS-CLEAN narrowing (the unqualified form fired on 5 CORRECT drafts in the
# run_clean_v1252 sweep — a purely-combinational module legitimately needs no
# clock, e.g. an AXIS mux or a Manchester encoder commented "unused: encode is
# combinational"; and a MULTI-clock CDC / protocol-bridge module legitimately
# leaves a secondary clock unused, e.g. a `cdc_synchronizer` clocking only on
# `clk_dst`, a `wishbone_to_ahb_bridge` with `clk_i`+`hclk`). To avoid flagging
# any of those legitimate states, the rule fires ONLY on the unambiguous
# wiring-bug shape:
#   * the module has EXACTLY ONE clock-idiom input port (multi-clock CDC/bridge
#     blocks, where an unused secondary clock is normal, are excluded), AND
#   * the module contains at least one EDGE-TRIGGERED always block (so a purely
#     combinational module — which correctly needs no clock — is excluded), AND
#   * that lone clock port is referenced NOWHERE in the body (its flip-flops are
#     therefore clocked by something that is NOT the declared clock — the bug).
# Plus the structural guards:
#   * scoped per MODULE region (a clock used in a sibling module never masks an
#     unused one here, and vice-versa);
#   * only SCALAR clock inputs (a clock is 1 bit; a ranged `input [..]` is not a
#     clock and is skipped);
#   * FAIL-SAFE toward NOT firing — the reference scan blanks ONLY the module
#     header port list and pure `input/output/inout` declarations (never a
#     `wire x = clk & en;` initializer, which is a real use), so if anything is
#     ambiguous the port reads as USED and the rule stays silent.
_CLOCK_NAME_RE = re.compile(
    r'^(?:clk|clock|hclk|pclk|aclk|sclk|bclk|mclk|gclk|clk_\w+|\w+_clk)$', re.I)


def _ranged_input_names(region: str) -> Set[str]:
    """Input port names declared WITH a `[..]` range (i.e. multi-bit) — used to
    exclude non-scalar 'clk*'-named buses from the unused-clock rule."""
    out: Set[str] = set()
    for m in re.finditer(
            r'\binput\b(?:\s+(?:wire|reg|logic))?(?:\s+signed)?\s*'
            r'\[[^\]]+\]\s*([A-Za-z_]\w*(?:\s*,\s*[A-Za-z_]\w*)*)', region):
        for n in m.group(1).split(','):
            n = n.strip()
            if n:
                out.add(n)
    return out


def rule_unused_clock_input(src: str, path: str) -> List[Finding]:
    """Rule 18 — advisory WARN on a clock-idiom INPUT port never referenced in
    its module body."""
    findings: List[Finding] = []
    for _mname, mlo, mhi in _module_regions(src):
        region = src[mlo:mhi]
        ports = _collect_input_ports(region)
        clk_ports = {p for p in ports if _CLOCK_NAME_RE.match(p)}
        # CORPUS-CLEAN narrowing: exactly ONE clock-idiom port (excludes
        # multi-clock CDC/bridge blocks) AND the module has sequential logic
        # (excludes purely-combinational modules that need no clock).
        if len(clk_ports) != 1:
            continue
        if not re.search(r'\balways(?:_ff)?\s*@\s*\(\s*(?:pos|neg)edge\b', region):
            continue
        ranged = _ranged_input_names(region)
        # Blank the module header port list + pure direction declarations, so a
        # remaining occurrence of the name is a genuine USE (sensitivity list or
        # expression). Length-preserving so line numbers stay correct.
        def _blank(m):
            return ' ' * len(m.group(0))
        nod = re.sub(
            r'\bmodule\b\s+\w+\s*(?:#\s*\([\s\S]*?\)\s*)?\([\s\S]*?\)\s*;',
            _blank, region, count=1)
        nod = re.sub(r'\b(?:input|output|inout)\b[^;]*;', _blank, nod)
        for name in sorted(clk_ports):
            if name in ranged:
                continue
            if re.search(r'\b' + re.escape(name) + r'\b', nod):
                continue                      # referenced somewhere -> used
            # Genuinely never referenced -> advisory wiring-bug WARN. Report the
            # line of the port's declaration (its first occurrence in the region).
            dm = re.search(r'\b' + re.escape(name) + r'\b', region)
            abs_off = mlo + (dm.start() if dm else 0)
            f = Finding(
                path, src.count('\n', 0, abs_off) + 1, 'WARN',
                'unused-clock-input', name,
                f"clock-idiom input port `{name}` is declared but referenced in "
                f"ZERO sensitivity lists and ZERO expressions in this module — "
                f"almost always a wiring bug (the intended clock does not drive "
                f"the logic). Connect `{name}` to the sequential process, or "
                f"remove the unused port.")
            findings.append(_advisory(f, _prov.PROSE_HEURISTIC,
                                      _prov.NO_CORROBORATION))
    return findings


def autofix_width_cast(p: Path) -> Tuple[int, List[str]]:
    """Deterministically REPAIR the auto-fixable width-cast sites (Rule 17) in
    place: insert a value-IDENTICAL size cast that silences verilator
    WIDTHEXPAND/WIDTHTRUNC without changing behaviour. Edits are spliced into the
    RAW text right-to-left (so earlier offsets stay valid) and only the `fixable`
    subset (unsigned + pure-literal widths) is touched. Returns (count, labels).
    No-op (0, []) when nothing is fixable. The caller's #533 compile-neutrality
    net reverts the whole file if any edit stops it compiling."""
    raw = p.read_text(errors='replace')
    src = strip_comments(raw)
    sites = [s for s in _width_cast_sites(src) if s['fixable']]
    if not sites:
        return 0, []
    sites.sort(key=lambda s: s['span'][0], reverse=True)
    out = raw
    labels: List[str] = []
    used_spans: Set[Tuple[int, int]] = set()
    for s in sites:
        span = s['span']
        if span in used_spans:
            continue
        used_spans.add(span)
        a, b = span
        out = out[:a] + s['repl'] + out[b:]
        labels.append(f"{s['symbol']}:{s['kind']}")
    if out != raw:
        p.write_text(out)
    return len(labels), labels


# ---------------------------------------------------------------------------
# Rule 19: Bitwise-NOT width-expand in a comparison / wider assignment
# ---------------------------------------------------------------------------
# `~v` of an N-bit operand keeps N bits, but when it sits in a WIDER context
# (compared against a wider signal, or assigned to a wider target) verilator
# context-expands the complement — `wide == ~narrow` expands `~narrow` to the
# wide width, so its upper bits become 1 and the equality can NEVER hold. This is
# the verilator WIDTHEXPAND "Operator NOT expects N bits on the LHS, but ...
# generates M bits" class. Advisory WARN (NO auto-fix): the value-correct repair
# depends on intent (mask the complement to its own width, or widen the operand),
# which a deterministic cast cannot choose without changing semantics. Fires ONLY
# when BOTH widths are known and the non-complemented side is STRICTLY wider, so
# a same-width `a == ~b` (the common, correct case) never fires. chip-AGNOSTIC.
def rule_bitwise_not_width(src: str, path: str) -> List[Finding]:
    findings: List[Finding] = []
    gconsts = _global_param_consts(src)
    seen: Set[Tuple[int, str]] = set()

    def _emit(line: int, operand: str, msg: str):
        key = (line, operand)
        if key in seen:
            return
        seen.add(key)
        f = Finding(path, line, 'WARN', 'bitwise-not-width', operand, msg)
        findings.append(_advisory(f, _prov.PROSE_HEURISTIC,
                                  _prov.NO_CORROBORATION))

    for _mn, mlo, mhi in _module_regions(src):
        region = src[mlo:mhi]
        info = _decl_width_info(region, gconsts)
        if not info:
            continue
        # Comparison forms (only the UNAMBIGUOUS comparison operators — `==`,
        # `!=`, `<`, `>` — never `<=`/`>=`, which collide with NBA / direction).
        for m in re.finditer(
                r'\b([A-Za-z_]\w*)\s*(==|!=|<|>)\s*~\s*([A-Za-z_]\w*)', region):
            other, comp = m.group(1), m.group(3)
            oi, ci = info.get(other), info.get(comp)
            if oi and ci and oi[0] > ci[0]:
                _emit(src.count('\n', 0, mlo + m.start(3)) + 1, comp,
                      f"`~{comp}` ({ci[0]} bits) is width-expanded to {oi[0]} "
                      f"bits by the comparison against `{other}` (verilator "
                      f"WIDTHEXPAND) — the complement's upper bits become 1 so "
                      f"the test can never match the intended {ci[0]}-bit value. "
                      f"Mask to the operand width or widen `{comp}`.")
        for m in re.finditer(
                r'~\s*([A-Za-z_]\w*)\s*(==|!=|<|>)\s*([A-Za-z_]\w*)', region):
            comp, other = m.group(1), m.group(3)
            ci, oi = info.get(comp), info.get(other)
            if oi and ci and oi[0] > ci[0]:
                _emit(src.count('\n', 0, mlo + m.start(1)) + 1, comp,
                      f"`~{comp}` ({ci[0]} bits) is width-expanded to {oi[0]} "
                      f"bits by the comparison against `{other}` (verilator "
                      f"WIDTHEXPAND) — the complement's upper bits become 1 so "
                      f"the test can never match the intended {ci[0]}-bit value. "
                      f"Mask to the operand width or widen `{comp}`.")
        # Assignment to a strictly-wider target: `wideLHS <= ~narrow ;`
        for m in re.finditer(
                r'(?:\bassign\s+)?(?<![<>!=.])\b([A-Za-z_]\w*)\s*(?:<=|=)(?!=)\s*'
                r'~\s*([A-Za-z_]\w*)\s*;', region):
            lhs, op = m.group(1), m.group(2)
            li, oi = info.get(lhs), info.get(op)
            if li and oi and li[0] > oi[0]:
                _emit(src.count('\n', 0, mlo + m.start(2)) + 1, op,
                      f"`~{op}` ({oi[0]} bits) is width-expanded to {li[0]} bits "
                      f"when assigned to `{lhs}` (verilator WIDTHEXPAND) — the "
                      f"upper {li[0] - oi[0]} bit(s) become 1. Confirm the intended "
                      f"width (mask `~{op}` or widen `{op}` before complementing).")
    return findings


# ---------------------------------------------------------------------------
# Rule 21: Enum-ternary base-type assigned to a narrower target
# ---------------------------------------------------------------------------
# `cond ? ENUM_A : ENUM_B` yields the enum's BASE type (e.g. `logic [3:0]`).
# Assigning it to a target narrower than that base silently truncates the enum
# encoding. Advisory WARN. Conservative & zero-FP biased: fires ONLY for enums
# declared with an EXPLICIT integral base `enum logic [H:L] {...}` (an implicit
# `int` base is never guessed), only when BOTH ternary arms are members of that
# same enum, and only when the target's width is KNOWN and strictly narrower than
# the base. A ternary assigned to the enum type itself (equal width) never fires.
def _enum_member_base_widths(src: str) -> Dict[str, int]:
    """member-name -> enum base width, for every `typedef enum logic[H:L]{..} T;`
    with an explicit integral base. Implicit-base enums are omitted (not guessed).
    """
    out: Dict[str, int] = {}
    for m in re.finditer(
            r'\btypedef\s+enum\s+(?:logic|bit|reg)\s*'
            r'\[\s*(\d+)\s*:\s*(\d+)\s*\]\s*\{([^}]*)\}', src):
        width = abs(int(m.group(1)) - int(m.group(2))) + 1
        if width <= 0:
            continue
        for seg in m.group(3).split(','):
            nm = re.match(r'\s*([A-Za-z_]\w*)', seg)
            if nm and nm.group(1) not in VERILOG_KEYWORDS:
                out.setdefault(nm.group(1), width)
    return out


def rule_enum_ternary_width(src: str, path: str) -> List[Finding]:
    findings: List[Finding] = []
    members = _enum_member_base_widths(src)
    if not members:
        return findings
    gconsts = _global_param_consts(src)
    seen: Set[int] = set()
    for _mn, mlo, mhi in _module_regions(src):
        region = src[mlo:mhi]
        info = _decl_width_info(region, gconsts)
        for m in re.finditer(
                r'(?<![<>!=.])\b([A-Za-z_]\w*)\s*(?:<=|=)(?!=)\s*'
                r'[^;?]*\?\s*([A-Za-z_]\w*)\s*:\s*([A-Za-z_]\w*)\s*;', region):
            lhs, a, b = m.group(1), m.group(2), m.group(3)
            wa, wb = members.get(a), members.get(b)
            if wa is None or wb is None or wa != wb:
                continue                       # both arms must be the same enum
            li = info.get(lhs)
            if not li or li[0] >= wa:           # target must be strictly narrower
                continue
            ln = src.count('\n', 0, mlo + m.start(1)) + 1
            if ln in seen:
                continue
            seen.add(ln)
            f = Finding(
                path, ln, 'WARN', 'enum-ternary-width', lhs,
                f"`{a}`/`{b}` are members of an enum with a {wa}-bit base; the "
                f"ternary `… ? {a} : {b}` yields {wa} bits but is assigned to "
                f"`{lhs}` ({li[0]} bits) — the enum encoding is truncated. Widen "
                f"`{lhs}` to the enum base width or assign the enum type.")
            findings.append(_advisory(f, _prov.PROSE_HEURISTIC,
                                      _prov.NO_CORROBORATION))
    return findings


# ---------------------------------------------------------------------------
# Rule 22: Mixed blocking/non-blocking writes to the SAME reg in a clocked block
# ---------------------------------------------------------------------------
# A register written with BOTH a blocking `=` AND a non-blocking `<=` inside ONE
# edge-triggered always block is an unambiguous mistake (the verilator
# BLKSEQ/mixed class): the two scheduling regions race and the result is
# tool-dependent. Advisory WARN. Deliberately NARROW — the ubiquitous LEGITIMATE
# blocking-temp idiom (`tmp = expr; q <= f(tmp);`, where `tmp` and `q` are
# DIFFERENT names) does NOT fire, because it requires the SAME name on both a `=`
# and a `<=` write. No auto-fix: blanket `=`→`<=` is not value-preserving (it
# changes the in-block read semantics the design may rely on), so this only
# surfaces the conflict for a human/AI to resolve. chip-AGNOSTIC structural parse.
#
# §4.05 zero-FP — ONLY count STATEMENT-LEVEL writes (paren-depth 0). A `<=`/`=`
# inside a `for (i = 0; i <= N; i = i+1)` header or an `if (x <= LIMIT)` /
# `for (gl = 1; gl <= LOG; …)` condition is a COMPARISON / loop-control token, not
# a non-blocking assignment — those live at paren-depth >= 1. Without this filter
# a genvar loop bound (`gl <= LOG`) or an FSM `next_state` comparison was
# mis-counted as an NBA write and falsely "mixed" with its blocking temp write
# (observed on matrix_multiplier `gl` + Attenuator `next_state` in the corpus).
def _depth0_writes(body: str, op_re: str) -> Set[str]:
    """Names written by `op_re` (a `<=`/`=` matcher) at paren-depth 0 only —
    i.e. real statement-level assignments, never a `<=`/`=` buried inside a
    `for`/`if`/`while` parenthesised condition. String literals are blanked so a
    paren inside a `$display("(")` never skews the depth count."""
    scan = _blank_string_literals(body)
    names: Set[str] = set()
    for mm in re.finditer(op_re, scan):
        depth = scan.count('(', 0, mm.start()) - scan.count(')', 0, mm.start())
        if depth == 0:
            names.add(mm.group(1))
    return names


def rule_mixed_blocking_same_reg(src: str, path: str) -> List[Finding]:
    findings: List[Finding] = []
    for sens, body, pos in _iter_always_blocks(src):
        if not re.search(r'\b(?:pos|neg)edge\b', sens):
            continue                            # sequential blocks only
        nba = _depth0_writes(
            body, r'(?<![<>!=])\b([A-Za-z_]\w*)(?:\[[^\]]+\])?\s*<=(?!=)')
        blk = _depth0_writes(
            body, r'(?<![<>!=])\b([A-Za-z_]\w*)(?:\[[^\]]+\])?\s*=(?!=)')
        mixed = sorted((nba & blk) - VERILOG_KEYWORDS)
        for reg in mixed:
            # Line of the blocking write (the one to convert) for a precise anchor.
            bw = re.search(r'(?<![<>!=])\b' + re.escape(reg) +
                           r'(?:\[[^\]]+\])?\s*=(?!=)', body)
            off = pos + (bw.start() if bw else 0)
            f = Finding(
                path, src.count('\n', 0, off) + 1, 'WARN',
                'mixed-blocking-nonblocking', reg,
                f"register `{reg}` is written with BOTH a blocking `=` and a "
                f"non-blocking `<=` inside one edge-triggered block — the two "
                f"update regions race (verilator BLKSEQ; tool-dependent result). "
                f"Use `<=` consistently for sequential state.")
            findings.append(_advisory(f, _prov.PROSE_HEURISTIC,
                                      _prov.NO_CORROBORATION))
    return findings


# ---------------------------------------------------------------------------
# Rule 22: Narrow bitwise-NOT / binary-XNOR (/ shift) inverted in a WIDER lvalue
# context (rule name `narrow-bitwise-not-wider-context`, advisory WARN, NO --fix)
# ---------------------------------------------------------------------------
# A unary bitwise NOT `~OP`, a binary XNOR `A ~^ B` / `A ^~ B`, or a left /
# arith-right shift `A << s` / `A >>> s`, sitting in a position that INHERITS a
# WIDER assignment-context width M than the operand's self-determined width N,
# computes the inversion/shift AT WIDTH M: the operand zero-extends to M bits
# first and the operator then flips/moves the upper M-N pad bits. Canonical bug:
#
#     reg  [7:0] o_result;       // 8-bit lvalue (M = 8)
#     wire [3:0] i_operand_a;    // 4-bit operand (N = 4)
#     o_result <= ~i_operand_a;  // ~4'hC computed at 8 bits = 8'hF3, NOT 8'h03
#
# This is sibling to Rule 19 (`bitwise-not-width`, which covers `~narrow` in a
# COMPARISON and the bare `wideLHS <= ~narrow;`); Rule 22 generalises to binary
# XNOR, `<<`/`>>>` shifts, and the dangerous op nested in a `?:` arm.
#
# WHY WARN-only / NO auto-fix: a deterministic `--fix` cannot know whether the
# wide inversion is INTENDED (a legitimate full-width complement) or a sub-word
# bug — auto-wrapping `~op` as `{ {{M-N}{1'b0}}, ~op }` would silently corrupt the
# legitimate full-width case. So it emits an advisory (non-blocking) WARN proposing
# the fix; it is intentionally NOT block-eligible (never hard-vetoes an otherwise-
# correct draft) for the same intent-ambiguity reason.
#
# MUST-EXCLUDE (else it false-fires on legitimate code):
#   * REDUCTION operators (`&x |x ^x ~&x ~|x ~^x`) yield a 1-bit result that is
#     merely zero-extended — no pad-inversion bug. `~^`/`^~` are treated ONLY as
#     the *binary* XNOR (two operands); a leading `~^x`/`^~x` (unary reduction) is
#     never flagged.
#   * an operand already sized to M (concat-padded `{pad, ~op}` / a sized temp):
#     the dangerous op then sits at depth>0 inside `{...}` and is never reached.
#   * plain `& | ^ + -` over a zero-extended operand: the pad bits stay 0, so the
#     op is NOT flagged. Rule 22 fires ONLY when the dangerous op occupies the
#     WHOLE context-width position (the top-level RHS, or a `?:` arm); it
#     deliberately does NOT recurse into the operands of a further binary combiner
#     — a trailing `& z` can mask the inverted pad bits (`~a & b` is safe), so
#     flagging a nested invert is not soundly zero-FP. Conservative subset, still
#     catches the canonical direct-assignment bug.
# chip-AGNOSTIC: pure structural width arithmetic over the linter's width table.


def _sized_literal_width(tok: str) -> Optional[int]:
    """Declared bit-width of a sized literal (`4'hC` -> 4, `8'd5` -> 8), or None
    when `tok` is not a clean sized literal. chip-AGNOSTIC."""
    m = _SIZED_LITERAL_RE.fullmatch(tok.strip())
    if not m:
        return None
    try:
        w = int(m.group(1))
    except (TypeError, ValueError):
        return None
    return w if w > 0 else None


def _strip_outer_parens(e: str) -> str:
    """Remove fully-enclosing balanced parentheses (and surrounding whitespace)
    from `e`, repeatedly. `(a~^b)` -> `a~^b`; `(a)+(b)` is left intact (the outer
    parens do not enclose the whole expression). chip-AGNOSTIC."""
    e = e.strip()
    while len(e) >= 2 and e[0] == '(':
        depth = 0
        matched = -1
        for idx, ch in enumerate(e):
            if ch == '(':
                depth += 1
            elif ch == ')':
                depth -= 1
                if depth == 0:
                    matched = idx
                    break
        if matched == len(e) - 1:
            e = e[1:-1].strip()
        else:
            break
    return e


# Binary operators that can appear at the top level of an expression, paired with
# a precedence rank (LOWER rank binds LOOSER, so the loosest top-level operator is
# the expression's dominant/root operator). Longest tokens are matched first so
# `<<<` is never split as `<` + `<<`.
_BINOP_TABLE = [
    ('||', 1),
    ('&&', 2),
    ('|', 3),
    ('~^', 4), ('^~', 4), ('^', 4),
    ('&', 5),
    ('===', 6), ('!==', 6), ('==', 6), ('!=', 6),
    ('<=', 7), ('>=', 7), ('<', 7), ('>', 7),
    ('<<<', 8), ('>>>', 8), ('<<', 8), ('>>', 8),
    ('+', 9), ('-', 9),
    ('*', 10), ('/', 10), ('%', 10),
]
_BINOP_BY_LEN = sorted(_BINOP_TABLE, key=lambda t: -len(t[0]))


def _top_level_split(expr: str):
    """Split `expr` at its DOMINANT (loosest-precedence) top-level binary operator
    -> (op, left, right). Returns None when `expr` has no top-level binary operator
    (a pure atom / unary expression). Operators inside (), [], {} are ignored
    (depth > 0); a leading operator with no left operand is a UNARY reduction/sign
    and is never counted as binary. Ties pick the RIGHTMOST occurrence (the root of
    a left-associative chain). chip-AGNOSTIC."""
    s = expr
    n = len(s)
    depth = 0
    best = None  # (prec, pos, op)
    i = 0
    while i < n:
        c = s[i]
        if c in '([{':
            depth += 1
            i += 1
            continue
        if c in ')]}':
            depth -= 1
            i += 1
            continue
        if depth != 0:
            i += 1
            continue
        hit = None
        for op, prec in _BINOP_BY_LEN:
            if s.startswith(op, i):
                j = i - 1
                while j >= 0 and s[j].isspace():
                    j -= 1
                # a binary operator needs a LEFT operand: the previous non-space
                # char must end an operand (identifier/number/literal/`)`/`]`/`}`).
                if j >= 0 and (s[j].isalnum() or s[j] in "_)]}'"):
                    hit = (prec, i, op)
                break
        if hit is not None:
            prec, pos, op = hit
            if (best is None or prec < best[0]
                    or (prec == best[0] and pos > best[1])):
                best = hit
            i += len(op)
            continue
        i += 1
    if best is None:
        return None
    _, pos, op = best
    return (op, s[:pos].strip(), s[pos + len(op):].strip())


def _split_ternary(expr: str):
    """If `expr` has a top-level ternary, return (cond, true_arm, false_arm), else
    None. Matches the FIRST top-level `?` and its balancing `:` (nested ternaries
    balanced); `?`/`:` inside (), [], {} are ignored, so a `[a +: b]` part-select
    `:` never mis-splits. chip-AGNOSTIC."""
    s = expr
    depth = 0
    q = -1
    for i, c in enumerate(s):
        if c in '([{':
            depth += 1
        elif c in ')]}':
            depth -= 1
        elif depth == 0 and c == '?':
            q = i
            break
    if q < 0:
        return None
    depth = 0
    nested = 0
    for i in range(q + 1, len(s)):
        c = s[i]
        if c in '([{':
            depth += 1
        elif c in ')]}':
            depth -= 1
        elif depth == 0:
            if c == '?':
                nested += 1
            elif c == ':':
                if nested == 0:
                    return (s[:q].strip(), s[q + 1:i].strip(), s[i + 1:].strip())
                nested -= 1
    return None


def _self_width(expr: str, info: Dict[str, Tuple[int, bool, bool]]) -> Optional[int]:
    """Self-determined bit-width N of a SIMPLE expression over the width table
    `info` (name -> (width, is_literal, is_signed)), or None when it cannot be
    proven. Width-combining ops (`& | ^ ~^ ^~ + -`) and ternary arms resolve to
    the MAX of their operand widths (associative/commutative — no precedence
    needed); a leading reduction / `!` is 1 bit; shifts / mul / div / relational /
    equality return None (conservative — caller stays silent). chip-AGNOSTIC."""
    e = _strip_outer_parens(expr.strip())
    if not e:
        return None
    if re.fullmatch(r'[A-Za-z_]\w*', e):
        t = info.get(e)
        return t[0] if t else None
    w = _sized_literal_width(e)
    if w is not None:
        return w
    tern = _split_ternary(e)
    if tern:
        a = _self_width(tern[1], info)
        b = _self_width(tern[2], info)
        return max(a, b) if (a is not None and b is not None) else None
    sp = _top_level_split(e)
    if sp:
        op, left, right = sp
        if op in ('~^', '^~', '^', '&', '|', '+', '-'):
            a = _self_width(left, info)
            b = _self_width(right, info)
            return max(a, b) if (a is not None and b is not None) else None
        return None  # shift / mul / div / relational / equality -> unknown
    if e[0] == '~':
        nxt = e[1:].lstrip()
        if nxt[:1] in ('&', '|', '^'):
            return 1  # reduction NAND/NOR/XNOR -> 1 bit
        return _self_width(nxt, info)
    if e and e[0] in '&|^!':
        return 1  # leading reduction / logical-not -> 1 bit
    return None


def _narrow_invert_in_ctx(expr: str, M: int,
                          info: Dict[str, Tuple[int, bool, bool]]):
    """Return (kind, expr, N) when the WHOLE context-width position `expr`
    (assigned to an M-bit lvalue) is a sub-word inversion/shift flipping the upper
    pad bits — a unary bitwise NOT (`kind='not'`), a binary XNOR (`'xnor'`), or a
    `<<`/`<<<`/`>>>` shift (`'shift'`) whose operand self-width N < M. Recurses
    ONLY into ternary arms (which also inherit the M-bit context). Returns None
    otherwise. chip-AGNOSTIC."""
    e = _strip_outer_parens(expr.strip())
    if not e:
        return None
    tern = _split_ternary(e)
    if tern:
        for arm in (tern[1], tern[2]):
            r = _narrow_invert_in_ctx(arm, M, info)
            if r:
                return r
        return None
    sp = _top_level_split(e)
    if sp:
        op, left, right = sp
        if op in ('~^', '^~'):
            # BINARY XNOR (two operands). A unary reduction `~^x` has no left
            # operand and is never split here, so it can never reach this arm.
            if left:
                n = _self_width(e, info)
                if n is not None and n < M:
                    return ('xnor', e, n)
            return None
        if op in ('<<', '<<<', '>>>'):
            n = _self_width(left, info)
            if n is not None and n < M:
                return ('shift', e, n)
            return None
        # any other dominant binary op (| ^ & + - * / % == < > && || >> …): the
        # dangerous op, if any, is SUBORDINATE -> conservative skip (zero-FP).
        return None
    # no top-level binary op -> a pure unary / atom expression.
    if e[0] == '~':
        nxt = e[1:].lstrip()
        if nxt[:1] in ('&', '|', '^', '~'):
            return None  # reduction (~& ~| ~^) or double-NOT -> not a sub-word invert
        n = _self_width(nxt, info)
        if n is not None and n < M:
            return ('not', e, n)
    return None


def _ctx_assignments(text: str):
    """Yield (lhs_name, rhs_text, op_offset) for every STATEMENT-LEVEL (paren/
    bracket/brace depth 0) `=` / `<=` assignment whose LHS is a BARE identifier
    (a bit/part-select LHS has a slice-width context this rule does not resolve and
    is skipped). A `<=`/`==`/`!=`/`>=` used as a COMPARISON inside a parenthesised
    condition is depth>0 and never mis-read as an assignment. chip-AGNOSTIC."""
    s = text
    n = len(s)
    depth = 0
    i = 0
    while i < n:
        c = s[i]
        if c in '([{':
            depth += 1
            i += 1
            continue
        if c in ')]}':
            depth -= 1
            i += 1
            continue
        if depth == 0 and (c == '=' or (c == '<' and s[i:i + 2] == '<=')):
            if c == '<':
                op_end = i + 2
            else:
                if s[i:i + 2] == '==':           # equality compare, not assign
                    i += 2
                    continue
                if i > 0 and s[i - 1] in '<>=!':  # tail of <= >= == != ===
                    i += 1
                    continue
                op_end = i + 1
            j = i - 1
            while j >= 0 and s[j].isspace():
                j -= 1
            if j >= 0 and s[j] == ']':            # subscripted LHS -> skip
                i = op_end
                continue
            k = j
            while k >= 0 and (s[k].isalnum() or s[k] == '_'):
                k -= 1
            name = s[k + 1:j + 1]
            # statement end = next depth-0 ';'
            d2 = 0
            e = op_end
            while e < n:
                cc = s[e]
                if cc in '([{':
                    d2 += 1
                elif cc in ')]}':
                    d2 -= 1
                elif cc == ';' and d2 == 0:
                    break
                e += 1
            if name and not name[0].isdigit() and name not in VERILOG_KEYWORDS:
                yield (name, s[op_end:e], i)
            i = e + 1 if e < n else n
            continue
        i += 1


def rule_narrow_bitwise_not_wider_context(src: str, path: str) -> List[Finding]:
    """Rule 22 — advisory WARN on a sub-word bitwise NOT / binary XNOR / `<<`,
    `>>>` shift inverted (or shifted) in a WIDER assignment context. See the rule
    header for the precise catch + must-exclude set. Non-block-eligible (advisory):
    the wide-vs-sub-word INTENT is ambiguous, so it never hard-vetoes a draft."""
    findings: List[Finding] = []
    gconsts = _global_param_consts(src)
    seen: Set[Tuple[int, str]] = set()
    for _mn, mlo, mhi in _module_regions(src):
        region = src[mlo:mhi]
        info = _decl_width_info(region, gconsts)
        if not info:
            continue
        for name, rhs, off in _ctx_assignments(region):
            li = info.get(name)
            if not li:
                continue
            M, _lit, signed = li
            # Signed targets sign-extend before complement — the widening is far
            # more often INTENDED there (a signed full-width `~`); stay zero-FP and
            # only fire on unsigned lvalues (the canonical pad-zero-extend case).
            if signed:
                continue
            hit = _narrow_invert_in_ctx(rhs, M, info)
            if not hit:
                continue
            kind, _expr, N = hit
            line = src.count('\n', 0, mlo + off) + 1
            key = (line, name)
            if key in seen:
                continue
            seen.add(key)
            opname = {'not': 'bitwise ~', 'xnor': 'binary XNOR (~^/^~)',
                      'shift': 'shift (<<,>>>)'}[kind]
            pad = M - N
            sized_hint = "{ {%d{1'b0}}, <op> }" % pad
            f = Finding(
                path, line, 'WARN', 'narrow-bitwise-not-wider-context', name,
                f"{opname} on a {N}-bit operand assigned to the {M}-bit target "
                f"`{name}` ({M}>{N}): the operand zero-extends to {M} bits before "
                f"the inversion/shift, so the upper {pad} pad bit(s) get "
                f"inverted/shifted too (e.g. `~4'hC` in an 8-bit context = `8'hF3`, "
                f"not `8'h03`). If only the low {N} bits should be operated on, "
                f"size the operand (e.g. `{sized_hint}`) or use a sized temp. Advisory WARN "
                f"— no auto-fix (a blanket widening cast would corrupt a legitimate "
                f"full-width inversion).")
            # Advisory: visible at --severity WARN but NOT block-eligible — the
            # wide-vs-sub-word intent is ambiguous, so it never trips rc=1.
            f.block_eligible = False
            f.advisory_note = ("sub-word invert/shift in a wider lvalue context "
                               "(intent-ambiguous; no safe auto-fix)")
            findings.append(f)
    return findings


# ---------------------------------------------------------------------------
# Rule 24 (function-automatic variable bit-select write): DROPPED — not zero-FP.
# The hazard (a function-LOCAL variable-indexed write silently dropped by some
# simulators) does NOT reproduce on the tools in scope: Icarus Verilog 12.0
# evaluates `local[i] = …` inside `function automatic` correctly (verified), and
# verilator never flags it. So the only corpus match (cvdp_copilot_dbi_0008
# `temp_dat[i]`) is CORRECT code on the modern toolchain — flagging it would be a
# false-positive on a legitimate, ubiquitous reverse/accumulate idiom. Per the
# corpus-clean discipline (a rule that fires on legitimate state is a bug, narrow
# or drop), this rule is intentionally NOT enabled.
#
# Rule 23 (non-pow2 dynamic-index OOB): DROPPED — not soundly zero-FP. A dynamic
# part-select `vec[idx*K +: K]` whose static loop bound exceeds the declared width
# is only a bug when the select is UNGUARDED; a guarded `if (idx < LIMIT) vec[..]`
# is correct, and distinguishing the two (plus parsing the loop/counter bound that
# feeds idx) cannot be done soundly with a structural regex on the 47 corpus files
# that use part-selects. Left to verilator's own SELRANGE/width pass.
#
# Optional CDC dual-flop synchronizer rule: DROPPED — not zero-FP. Detecting a
# "missing" synchronizer on a real clock-domain crossing requires clock-domain
# inference that mislabels single-clock and already-synchronized designs; it would
# fire on legitimate state across the corpus, so it is not added.


# ---------------------------------------------------------------------------
# Rule 25: Use-before-declaration (iverilog-13 / the official cvdp-sim REJECTS;
# the host iverilog-12 elaboration gate TOLERATES — a FALSE-PASS gap).
#
# The host elaboration gate runs Icarus Verilog 12, which ACCEPTS a module-scope
# net/var REFERENCED in an expression BEFORE its declaration line (a forward
# reference, rc=0). The OFFICIAL CVDP scorer runs Icarus Verilog 13, which
# REJECTS use-before-declaration with "Could not find variable X". So the host
# gate FALSE-PASSES code that fails official scoring. Real case:
# interrupt_controller_0019 read `any_pending`/`best_idx` inside a clocked block
# and then declared them as `wire` several lines LATER.
#
# Zero-FP discipline (BLOCK-eligible — pure structural SV parse, no design
# literal). A name is flagged ONLY when ALL of these hold:
#   * it is a module-scope `wire`/`reg`/`logic` declaration — NOT a port,
#     parameter/localparam, genvar, or function/task arg-or-local (all of which
#     are subtracted, function/task + generate bodies are MASKED out first), and
#     NOT a name that is ALSO a port/param,
#   * it is REFERENCED inside a CLOCKED/COMBINATIONAL `always @(...)` body OR on
#     the RHS of a continuous `assign` (the two contexts iverilog-13 rejects),
#   * that reference's source line is STRICTLY ABOVE the declaration line,
#   * the reference is a real read — not the member of a hierarchical `a.b`, not
#     a call `name(...)`; string literals are blanked so a word inside a
#     `$display("…")` format string is never read as an identifier,
#   * the analysis is confined to a SINGLE module region, so a sibling module's
#     same-named net declared later never cross-fires.
# When unsure, do NOT flag (forward references in instance port connections,
# decl-initializer RHS, and sensitivity lists are intentionally NOT scanned).
# ---------------------------------------------------------------------------
def _mask_function_task_bodies(src: str) -> str:
    """Replace `function … endfunction` and `task … endtask` BODIES with
    equal-length whitespace (newlines kept) so function/task ARGUMENTS and
    LOCALS never enter the module-scope declaration table and a reference inside
    one is never scanned. Offsets are preserved so line numbers stay correct.
    chip-AGNOSTIC structural mask (mirrors `_mask_generate_blocks`)."""
    out = list(src)
    for opener, closer in (('function', 'endfunction'), ('task', 'endtask')):
        depth = 0
        block_start = -1
        for m in re.finditer(r'\b(' + opener + r'|' + closer + r')\b',
                             ''.join(out)):
            if m.group(1) == opener:
                if depth == 0:
                    block_start = m.end()
                depth += 1
            elif depth > 0:                       # a closer with a live opener
                depth -= 1
                if depth == 0 and block_start >= 0:
                    for i in range(block_start, m.start()):
                        if out[i] != '\n':
                            out[i] = ' '
                    block_start = -1
    return ''.join(out)


def _generate_assigned_names(src: str) -> Set[str]:
    """Names ASSIGNED (continuous or procedural) inside a `generate … endgenerate`
    block. A module-scope net driven by a generate block is EXCLUDED from the
    use-before-declaration scan: generate elaboration/reordering makes the simple
    source-line heuristic unreliable, so flagging such a net is not provably
    zero-FP. Collected from the UNMASKED source (the masker blanks generate
    bodies). chip-AGNOSTIC structural scan."""
    names: Set[str] = set()
    depth, block_start = 0, -1
    spans: List[Tuple[int, int]] = []
    for m in re.finditer(r'\b(generate|endgenerate)\b', src):
        if m.group(1) == 'generate':
            if depth == 0:
                block_start = m.end()
            depth += 1
        elif depth > 0:
            depth -= 1
            if depth == 0 and block_start >= 0:
                spans.append((block_start, m.start()))
                block_start = -1
    for lo, hi in spans:
        body = src[lo:hi]
        for am in re.finditer(r'\bassign\b\s+([A-Za-z_]\w*)', body):
            names.add(am.group(1))
        for am in re.finditer(
                r'([A-Za-z_]\w*)\s*(?:\[[^\]]*\])?\s*(?:<=|=)(?!=)', body):
            names.add(am.group(1))
    return names


def _collect_all_port_names(text: str) -> Set[str]:
    """Every port name (input/output/inout) of the module(s) in `text` —
    both non-ANSI body decls (`output reg [1:0] q;`) and ANSI header lists
    (`module m(input clk, rst_n, output q)`). chip-AGNOSTIC structural scan."""
    ports: Set[str] = set()
    # Non-ANSI body / ANSI single-keyword decls: `<dir> [wire|reg|logic] [..] NAME`
    for m in re.finditer(
            r'\b(?:input|output|inout)\b(?:\s+(?:wire|reg|logic))?(?:\s+signed)?'
            r'\s*(?:\[[^\]]+\]\s*)?([A-Za-z_]\w*)\s*(?=[,;)=])', text):
        if m.group(1) not in VERILOG_KEYWORDS:
            ports.add(m.group(1))
    # ANSI header: comma-separated names inherit the most recent direction.
    for hm in re.finditer(r'\bmodule\b\s+\w+\s*(#\s*\([^)]*\)\s*)?\(', text):
        depth, end = 0, hm.end() - 1
        while end < len(text):
            if text[end] == '(':
                depth += 1
            elif text[end] == ')':
                depth -= 1
                if depth == 0:
                    break
            end += 1
        cur_dir = None
        for tok in re.finditer(r'\b(input|output|inout)\b|([A-Za-z_]\w*)',
                               text[hm.end():end]):
            if tok.group(1):
                cur_dir = tok.group(1)
            elif tok.group(2) and cur_dir is not None:
                nm = tok.group(2)
                if nm not in VERILOG_KEYWORDS and nm not in (
                        'wire', 'reg', 'logic', 'signed', 'unsigned'):
                    ports.add(nm)
    return ports


def rule_use_before_declaration(src: str, path: str) -> List[Finding]:
    """Rule 25 — flag a module-scope net/var read in an `always`/`assign`
    expression at a line ABOVE its declaration (iverilog-13 rejects; the host
    iverilog-12 gate tolerates → false-pass). See the rule header above for the
    full zero-FP exclusion set. chip-AGNOSTIC, deterministic structural parse."""
    findings: List[Finding] = []
    # Mask the contexts a module-scope forward reference can never legally come
    # from (generate / function / task bodies) and blank string contents, so the
    # decl table and the reference scan both see only module-scope code.
    masked = _blank_string_literals(
        _mask_function_task_bodies(_mask_generate_blocks(src)))
    gen_assigned = _generate_assigned_names(src)

    # offset -> 1-based line, computed once against the (offset-preserving) src.
    line_starts = [0]
    for i, c in enumerate(src):
        if c == '\n':
            line_starts.append(i + 1)

    def _line_of(off: int) -> int:
        lo, hi = 0, len(line_starts)
        while lo < hi:                            # bisect_right, stdlib-free
            mid = (lo + hi) // 2
            if off < line_starts[mid]:
                hi = mid
            else:
                lo = mid + 1
        return lo

    # A module-scope wire/reg/logic declaration (ranges + optional 2nd array
    # range), capturing a comma-separated name list. Ports come through here too
    # (e.g. `output reg q`) but are subtracted below.
    decl_re = re.compile(
        r'\b(?:wire|reg|logic)\b\s+(?:(?:signed|unsigned)\s+)?'
        r'(?:\[[^\]]+\]\s*)?(?:\[[^\]]+\]\s*)?'
        r'([A-Za-z_]\w*(?:\s*,\s*[A-Za-z_]\w*)*)')
    always_re = re.compile(r'\balways(?:_ff|_comb|_latch)?\s*@\s*\(([^)]*)\)')
    assign_re = re.compile(r'\bassign\b\s+(.+?);', re.DOTALL)
    assign_op_re = re.compile(r'(?<![<>=!])=(?!=)')

    for _mname, mlo, mhi in _module_regions(masked):
        region = masked[mlo:mhi]

        # 1. Declaration table: name -> earliest declaration line (this region).
        decl_line: Dict[str, int] = {}
        for m in decl_re.finditer(region):
            ln = _line_of(mlo + m.start())
            for n in m.group(1).split(','):
                n = n.strip()
                if n and n not in VERILOG_KEYWORDS:
                    if n not in decl_line or ln < decl_line[n]:
                        decl_line[n] = ln
        if not decl_line:
            continue

        # 2. Subtract everything that is NOT a flaggable module-scope net/var.
        excluded: Set[str] = set(_collect_all_port_names(region))
        excluded |= gen_assigned
        for pm in re.finditer(
                r'\b(?:parameter|localparam)\b[^=;]*?\b([A-Za-z_]\w*)\s*=', region):
            excluded.add(pm.group(1))
        for gm in re.finditer(r'\bgenvar\b\s+([A-Za-z_]\w*)', region):
            excluded.add(gm.group(1))
        for gm in re.finditer(r'\bfor\b\s*\(\s*genvar\s+([A-Za-z_]\w*)', region):
            excluded.add(gm.group(1))
        candidates = {n: ln for n, ln in decl_line.items() if n not in excluded}
        if not candidates:
            continue

        # 3. Collect reads inside always bodies + continuous-assign RHS, and the
        #    EARLIEST line each candidate is read at.
        use_line: Dict[str, int] = {}

        def _scan_reads(text: str, base_off: int) -> None:
            for tm in re.finditer(r'[A-Za-z_]\w*', text):
                nm = tm.group(0)
                if nm not in candidates:
                    continue
                s, e = tm.start(), tm.end()
                prev = text[s - 1] if s > 0 else ''
                nxt = text[e] if e < len(text) else ''
                if prev == '.' or nxt == '.':     # hierarchical `a.b`
                    continue
                if nxt == '(':                     # function/task/macro call
                    continue
                # Assignment-pattern / struct member KEY (`'{ … name: value … }`)
                # — `name:` here is a FIELD LABEL of the LHS struct type, NOT a
                # read of a same-named net. Match only `{`/`,`-preceded
                # `ident :` (single colon, not `::` scope); that slot is never a
                # ternary middle-operand (preceded by `?`), so this is zero-FP.
                # Fixes a false use-before-declaration on OpenTitan reg structs
                # (e.g. `'{ … data_intg: held_intg.a_user_data_intg }`).
                j = e
                while j < len(text) and text[j] in ' \t':
                    j += 1
                nxt_ns = text[j] if j < len(text) else ''
                after_colon = text[j + 1] if j + 1 < len(text) else ''
                k = s - 1
                while k >= 0 and text[k] in ' \t\n':
                    k -= 1
                prev_ns = text[k] if k >= 0 else ''
                if nxt_ns == ':' and after_colon != ':' and prev_ns in '{,':
                    continue
                ln = _line_of(base_off + s)
                if nm not in use_line or ln < use_line[nm]:
                    use_line[nm] = ln

        for bm in always_re.finditer(region):
            body_start = bm.end()                  # scan the body, NOT the sens list
            body = _block_body_after(region, body_start)
            _scan_reads(body, mlo + body_start)
        for am in assign_re.finditer(region):
            stmt = am.group(1)
            op = assign_op_re.search(stmt)
            if not op:
                continue
            _scan_reads(stmt[op.end():], mlo + am.start(1) + op.end())

        # 4. Flag any candidate whose earliest read is strictly above its decl.
        for nm, dln in sorted(candidates.items(), key=lambda kv: kv[1]):
            uln = use_line.get(nm)
            if uln is not None and uln < dln:
                # ERROR severity (not WARN): an unresolved forward reference is a
                # hard ELABORATION FAILURE under the official iverilog-13 scorer
                # ("Could not find variable"), in the same class as undriven-wire
                # / multidriven-continuous-procedural — so it must survive the
                # canonical `--severity ERROR` lint gate and trip rc=1, closing
                # the false-pass. block_eligible stays True (zero-FP on corpus).
                findings.append(Finding(
                    path, uln, 'ERROR', 'use-before-declaration', nm,
                    f"use-before-declaration: '{nm}' is referenced at line "
                    f"{uln} but declared at line {dln} (>{uln}); iverilog-13 / "
                    f"the official cvdp-sim REJECTS this (host iverilog-12 "
                    f"tolerates it). Move the declaration above first use."))
    return findings


# ---------------------------------------------------------------------------
# Rule: an input / inout PORT declared `reg` (ORGANIC-20260703)
# ---------------------------------------------------------------------------
# Rules 26-31 (ORGANIC-20260704) — six arithmetic-datapath structural traps
# distilled from the 94 proven-correct CVDP solved_design_db designs. Every
# rule below is ADVISORY ONLY (severity INFO, block_eligible=False, no --fix,
# no emit-block): each is a NEW heuristic pattern-class that has only been
# corpus-swept against those 94 designs, not the full plugin reference corpus,
# so it never hard-blocks a gate — it is reported for human/AI review. Each
# rule fails SAFE (returns no finding) whenever it cannot symbolically relate
# the widths/structure involved, rather than guessing. chip-AGNOSTIC: every
# check is pure RTL-text structure, no design/vendor/SKU literal.
# ---------------------------------------------------------------------------
_ADVISORY_NOTE_20260704 = (
    "new structural heuristic (ORGANIC-20260704) — advisory pending broader "
    "corpus validation beyond the 94-design zero-FP sweep")


def _param_names(src: str) -> Set[str]:
    """Collect every `parameter`/`localparam` NAME declared in the source
    (single or comma-separated lists). Used so a symbolic width bound like
    `WIDTH-1` or `ADDR_WIDTH` is recognized as constant-like, never as a
    runtime signal."""
    names: Set[str] = set()
    for m in re.finditer(r'\b(?:parameter|localparam)\b([^;]*);', src, re.S):
        for nm in re.finditer(r'([A-Za-z_]\w*)\s*=', m.group(1)):
            names.add(nm.group(1))
    return names


def _width_info(bracket_expr: str):
    """Parse a declaration's bracket content into a comparable width triple:
      ('sym', k, NAME)  for `k*NAME-1:0` or `NAME-1:0` (k=1)   -- symbolic
      ('abs', bits, None) for a literal `HI:0` range            -- absolute
      None if the expression doesn't match either recognizable shape (fails
      safe -- callers must skip rather than guess).
    """
    expr = bracket_expr.strip()
    m = re.match(r'^(\d+)\s*\*\s*([A-Za-z_]\w*)\s*-\s*1\s*:\s*0$', expr)
    if m:
        return ('sym', int(m.group(1)), m.group(2))
    m = re.match(r'^([A-Za-z_]\w*)\s*-\s*1\s*:\s*0$', expr)
    if m:
        return ('sym', 1, m.group(1))
    m = re.match(r'^(\d+)\s*:\s*0$', expr)
    if m:
        return ('abs', int(m.group(1)) + 1, None)
    return None


def _same_base(a, b) -> bool:
    """True if two `_width_info` triples are on a directly comparable scale:
    both symbolic against the SAME named parameter, or both absolute (bit
    counts are always mutually comparable)."""
    if a is None or b is None:
        return False
    if a[0] != b[0]:
        return False
    if a[0] == 'sym':
        return a[2] == b[2]
    return True


def _decl_width_map(src: str) -> Dict[str, Tuple]:
    """name -> `_width_info` triple, for every wire/reg/logic declaration
    (ports included) whose FIRST packed dimension resolves to a recognizable
    `k*NAME-1:0` / `NAME-1:0` / `HI:0` shape. Unrecognizable shapes (a second
    packed/unpacked dimension, an expression using `$clog2`, etc.) are simply
    absent from the map, so every consuming rule below fails safe on them."""
    out: Dict[str, Tuple] = {}
    # A port's net-type keyword (`wire`/`reg`/`logic`) is OPTIONAL in Verilog
    # (`input [7:0] a` is implicitly `wire`), and each port typically repeats
    # its own `input`/`output`/`inout` keyword rather than sharing a comma
    # list (the `finditer` position must NOT swallow a sibling port's leading
    # keyword, so this is a single-name match, not a comma list).
    port_decl_re = re.compile(
        r'\b(?:input|output|inout)\s+(?:(?:wire|reg|logic)\s+)?'
        r'(?:signed\s+)?\[\s*([^\]]+?)\s*\]\s*([A-Za-z_]\w*)')
    # An internal signal decl always carries its net-type keyword and MAY
    # comma-list several names under one declaration.
    internal_decl_re = re.compile(
        r'\b(?:wire|reg|logic)\s+(?:signed\s+)?\[\s*([^\]]+?)\s*\]\s*'
        r'([A-Za-z_]\w*(?:\s*,\s*[A-Za-z_]\w*)*)')
    for m in port_decl_re.finditer(src):
        info = _width_info(m.group(1))
        if info:
            out.setdefault(m.group(2), info)
    for m in internal_decl_re.finditer(src):
        info = _width_info(m.group(1))
        if not info:
            continue
        for nm in m.group(2).split(','):
            nm = nm.strip()
            if nm and nm not in VERILOG_KEYWORDS:
                out.setdefault(nm, info)
    return out


def _func_return_width_map(src: str) -> Dict[str, Tuple]:
    """name -> `_width_info` triple for a `function [signed] [<range>] name(`
    declaration's OWN return type (e.g. a Booth partial-product recoder that
    already returns the full product width)."""
    out: Dict[str, Tuple] = {}
    for m in re.finditer(
            r'\bfunction\s+(?:signed\s+)?\[\s*([^\]]+?)\s*\]\s*'
            r'([A-Za-z_]\w*)\s*\(',
            src):
        info = _width_info(m.group(1))
        if info:
            out[m.group(2)] = info
    return out


def _mk_advisory(path: str, line: int, rule: str, symbol: str, message: str) -> Finding:
    return Finding(file=path, line=line, severity='INFO', rule=rule,
                    symbol=symbol, message=message, block_eligible=False,
                    advisory_note=_ADVISORY_NOTE_20260704)


def rule_divider_missing_final_correction(src: str, path: str) -> List[Finding]:
    """Rule 26 (ORGANIC-20260704) — non-restoring-divider final correction.

    In a non-restoring division algorithm, the running remainder can go
    negative mid-computation; after the LAST of exactly W iterations, a
    negative remainder MUST receive a mandatory `<rem> <= <rem> + <divisor>;`
    final correction before being read out, or the emitted remainder is off
    by one divisor on specific sign combinations.

    Conservative gate (zero-FP by construction against the reference
    restoring-division style): only fires on a register that is EXPLICITLY
    declared `reg signed [...]` with a name containing "rem"/"remainder" --
    the textbook non-restoring signature. A RESTORING divider's remainder is
    unsigned and corrected every cycle (not just at the end), so it is never
    matched by this gate. Fails safe (no finding) when the terminal-iteration
    branch or the emit statement isn't recognizable."""
    findings: List[Finding] = []
    signed_rem_re = re.compile(
        r'\breg\s+signed\s+\[[^\]]+\]\s*(\w*rem\w*)\b',
        re.IGNORECASE)
    term_re = re.compile(
        r'\b\w*(?:cnt|count|idx|iter)\w*\s*==\s*[\w$\'\s+-]*?-\s*1\b'
        r'\s*\)\s*(?:begin)?([\s\S]{0,400}?)(?:\bend\b|\bendcase\b|$)')
    for rm in signed_rem_re.finditer(src):
        reg_name = rm.group(1)
        for tm in term_re.finditer(src):
            block = tm.group(1)
            if not re.search(r'<=\s*' + re.escape(reg_name) + r'\b', block):
                continue
            has_correction = re.search(
                r'\bif\s*\(\s*' + re.escape(reg_name) + r'\s*<\s*0\s*\)'
                r'[\s\S]{0,160}?' + re.escape(reg_name) + r'\s*<=\s*'
                + re.escape(reg_name) + r'\s*\+', block)
            if has_correction:
                continue
            lineno = src[:tm.start()].count('\n') + 1
            findings.append(_mk_advisory(
                path, lineno, 'divider-missing-final-correction', reg_name,
                f"signed running-remainder '{reg_name}' is emitted at the "
                f"terminal iteration without a preceding "
                f"`if ({reg_name} < 0) {reg_name} <= {reg_name} + "
                f"<divisor>;` final correction — a non-restoring divider's "
                f"negative remainder must be corrected before readout."))
    return findings


def rule_multiop_arith_width_consistency(src: str, path: str) -> List[Finding]:
    """Rule 27 (ORGANIC-20260704) — multi-operand GCD/LCM width consistency.

    (a) A >=3-operand multiply chain (`X <= A*B*C[...];`) whose LHS is
        declared at the SAME width as a single operand rather than the
        algorithmic max width the product needs.
    (b) A wide dividend divided by a BARE narrower divisor identifier with no
        value-preserving zero-extend (the golden CVDP `gcd_0040` pattern
        `product / {{WIDTH{1'b0}}, gcd_result}` wraps the divisor in a
        zero-extend concat, so the bare-identifier regex never matches it).

    Fails safe whenever any operand's width can't be symbolically related to
    the others (unresolvable decl shape, or different named bases)."""
    findings: List[Finding] = []
    dwmap = _decl_width_map(src)

    mulchain_re = re.compile(
        r'\b([A-Za-z_]\w*)\s*(?:<=|=)\s*'
        r'((?:[A-Za-z_]\w*\s*\*\s*){2,}[A-Za-z_]\w*)\s*;')
    for m in mulchain_re.finditer(src):
        lhs = m.group(1)
        operands = [o.strip() for o in m.group(2).split('*')]
        lhs_info = dwmap.get(lhs)
        operand_infos = [dwmap.get(o) for o in operands]
        if lhs_info is None or any(oi is None for oi in operand_infos):
            continue
        if not all(_same_base(lhs_info, oi) for oi in operand_infos):
            continue
        operand_values = {oi[1] for oi in operand_infos}
        if len(operand_values) != 1:
            continue  # operands aren't all the same width -> not this idiom
        shared_val = next(iter(operand_values))
        if lhs_info[1] == shared_val:
            lineno = src[:m.start()].count('\n') + 1
            base_desc = lhs_info[2] if lhs_info[0] == 'sym' else f"{lhs_info[1]}-bit"
            findings.append(_mk_advisory(
                path, lineno, 'multiop-arith-width-consistency', lhs,
                f"'{lhs}' accumulates a {len(operands)}-operand product "
                f"({'*'.join(operands)}) but is declared at a single "
                f"operand's width ({base_desc}) rather than the algorithmic "
                f"max width the product chain requires — high-order bits "
                f"silently truncate."))

    div_re = re.compile(r'\b([A-Za-z_]\w*)\s*/\s*([A-Za-z_]\w*)\s*[;)]')
    for m in div_re.finditer(src):
        num, den = m.groups()
        num_info = dwmap.get(num)
        den_info = dwmap.get(den)
        if not _same_base(num_info, den_info):
            continue
        if num_info[1] > den_info[1]:
            lineno = src[:m.start()].count('\n') + 1
            findings.append(_mk_advisory(
                path, lineno, 'multiop-arith-width-consistency', den,
                f"'{num}' is divided by bare '{den}' without a "
                f"value-preserving zero-extend to match widths — the "
                f"divisor should be widened via an explicit zero-extend "
                f"concat (e.g. `{{{{N{{1'b0}}}}, {den}}}`) before the "
                f"divide."))
    return findings


def rule_cascaded_decrement_priority_order(src: str, path: str) -> List[Finding]:
    """Rule 28 (ORGANIC-20260704) — cascaded down-counter borrow chain order.

    A BCD/HH:MM:SS-style cascaded decrement must evaluate its if/else-if
    chain in strict priority order: each subsequent branch, on top of
    decrementing the NEXT unit, must reload EVERY previously-decremented unit
    to its wraparound constant. If a later branch's reload set is not a
    superset of the earlier branches' decrement targets, the chain is
    evaluated out of priority order and silently produces wrong wraparound.

    Structural (not keyword-based): a branch's "decrement" target is any
    `X <= X - <const>;` self-decrement; its "reload" targets are any other
    `Y <= <const>;` in the same branch body. Requires >=3 branches (an `if`
    plus >=2 cascading `else if`) to have an order to judge; fails safe
    otherwise. chip-AGNOSTIC: no domain-specific unit name is ever matched."""
    findings: List[Finding] = []
    lines = src.split('\n')
    n = len(lines)
    decr_re = re.compile(r'\b([A-Za-z_]\w*)\s*<=\s*\1\s*-\s*[\w\'$]+\s*;')
    reload_re = re.compile(r'\b([A-Za-z_]\w*)\s*<=\s*([\w\'$]+)\s*;')
    if_start_re = re.compile(r'^\s*if\s*\(')
    elseif_re = re.compile(r'^\s*(?:end\s+)?else\s+if\s*\(')
    plain_else_re = re.compile(r'^\s*(?:end\s+)?else\b(?!\s+if)')

    i = 0
    while i < n:
        if not if_start_re.match(lines[i]):
            i += 1
            continue
        # Walk the chain tracking `begin`/`end` nesting depth RELATIVE to
        # this `if`. Each line's `end` count is applied BEFORE checking for
        # a branch boundary (an `end else if (...) begin` line closes the
        # PRIOR branch and opens the NEXT one on the same line), and its
        # `begin` count is applied AFTER, so depth==0 means "back at the
        # chain's own nesting level" at the moment of the boundary check.
        chain_start = i
        branch_starts = [i]
        depth = 0
        j = i
        chain_end = None
        while j < n:
            depth -= lines[j].count('end')
            if j > i and depth <= 0:
                if elseif_re.match(lines[j]) or plain_else_re.match(lines[j]):
                    branch_starts.append(j)
                    depth = 0
                else:
                    # a genuine chain-terminal `end` (no trailing else) —
                    # the chain is over; this line is NOT part of any branch.
                    chain_end = j
                    break
            depth += lines[j].count('begin')
            j += 1
        if chain_end is None:
            chain_end = j
        if len(branch_starts) < 3:
            i = chain_start + 1
            continue
        branch_bodies = []
        for k in range(len(branch_starts)):
            b0 = branch_starts[k]
            b1 = branch_starts[k + 1] if k + 1 < len(branch_starts) else chain_end
            branch_bodies.append('\n'.join(lines[b0:b1]))
        decrements = []
        reload_sets = []
        for body in branch_bodies:
            dset = {dm.group(1) for dm in decr_re.finditer(body)}
            rset = {rm.group(1) for rm in reload_re.finditer(body)
                    if rm.group(1) not in dset and rm.group(2) != rm.group(1)}
            decrements.append(dset)
            reload_sets.append(rset)
        # Only judge chains where EVERY branch decrements some unit -- the
        # genuine cascaded-borrow idiom (each priority level owns exactly one
        # decrement). A branch with NO decrement at all (a distinct
        # catch-all/hold/idle condition unrelated to the counter, e.g. a
        # trailing `else` that just clears an unrelated `valid` flag) is not
        # part of a cascade and must not be judged against the reload-set
        # invariant -- ORGANIC-20260704 zero-FP fix: this excludes the CVDP
        # `sync_lifo_0010` up/down counter (`if(reset)... else if(!full)
        # counter<=counter+1; else if(!empty) counter<=counter-1;`), whose
        # last branch is a plain single-unit decrement with NO cascade
        # semantics at all, not a chain with a missing reload.
        if decrements and all(decrements):
            cumulative: Set[str] = set()
            bad = False
            for k in range(1, len(branch_bodies)):
                cumulative |= decrements[k - 1]
                if cumulative and not cumulative.issubset(reload_sets[k]):
                    bad = True
                    break
            if bad:
                findings.append(_mk_advisory(
                    path, chain_start + 1,
                    'cascaded-decrement-priority-order', '',
                    "cascaded down-counter borrow chain: a later else-if "
                    "branch decrements a new unit without reloading all "
                    "previously-decremented units to their wraparound "
                    "constant first — verify the if/else-if priority order "
                    "(lowest unit first, cascading the borrow upward)."))
        i = max(chain_end, chain_start + 1)
    return findings


def rule_seq_multiplier_width(src: str, path: str) -> List[Finding]:
    """Rule 29 (ORGANIC-20260704) — sequential shift-and-add multiplier width.

    `acc <= acc + (operand << <variable-shift>);` inside a counted
    shift-and-add loop: if `operand`'s OWN declared width is narrower than
    `acc`'s, the shift happens in the NARROW width before the add promotes
    it, so high-order partial products truncate silently for large operands.
    A constant shift amount is excluded (not the iterative idiom). Fails
    safe when either width can't be resolved or the two aren't on a
    comparable scale."""
    findings: List[Finding] = []
    dwmap = _decl_width_map(src)
    acc_re = re.compile(
        r'\b([A-Za-z_]\w*)\s*<=\s*\1\s*\+\s*\(?\s*'
        r'([A-Za-z_]\w*)\s*<<\s*([A-Za-z_]\w*)\s*\)?\s*;')
    for m in acc_re.finditer(src):
        acc, operand, shiftvar = m.groups()
        if shiftvar.isdigit():
            continue
        acc_info = dwmap.get(acc)
        op_info = dwmap.get(operand)
        if not _same_base(acc_info, op_info):
            continue
        if acc_info[1] > op_info[1]:
            lineno = src[:m.start()].count('\n') + 1
            findings.append(_mk_advisory(
                path, lineno, 'seq-multiplier-width', acc,
                f"'{operand}' is shifted by a variable amount before being "
                f"added into '{acc}', but '{operand}' is declared narrower "
                f"than '{acc}' — the shifted operand must be pre-sized to "
                f"the accumulator's width BEFORE the shift, or high-order "
                f"partial products truncate silently for large operands."))
    return findings


def rule_variable_partselect_illegal_range(src: str, path: str) -> List[Finding]:
    """Rule 30 (ORGANIC-20260704) — variable data-dependent bit-window
    extraction using an illegal `[hi:lo]` part-select.

    A `[hi:lo]` part-select where BOTH bounds resolve to a declared signal
    (not a parameter/localparam, not a literal) is almost certainly meant to
    be an indexed part-select (`<base> +: <CONST_WIDTH>` / `-: `) — a
    variable-bounded `[hi:lo]` is illegal Verilog. Fails safe whenever either
    bound is purely numeric/parameter-derived (the overwhelmingly common,
    legal case: `[WIDTH-1:0]`, `[ADDR_WIDTH:ADDR_WIDTH-1]`, etc.)."""
    findings: List[Finding] = []
    param_names = _param_names(src)
    signal_names = {nm for _, nm, _ in find_declarations(src)}
    signal_names |= set(re.findall(
        r'\b(?:input|output|inout)\s+(?:wire|reg|logic)?\s*(?:signed\s+)?'
        r'(?:\[[^\]]+\]\s*)?([A-Za-z_]\w*)', src))

    def _is_const_like(tok: str) -> bool:
        tok = tok.strip()
        if re.match(r"^\d+\s*'[sS]?[bBdDhHoO][0-9a-fA-Fx_XZ]*$", tok):
            return True
        if re.match(r'^\d+$', tok):
            return True
        return tok in param_names

    for m in re.finditer(r'\[([^\[\]:]+):([^\[\]:]+)\]', src):
        hi, lo = m.group(1), m.group(2)
        hi_toks = re.findall(r'[A-Za-z_]\w*', hi)
        lo_toks = re.findall(r'[A-Za-z_]\w*', lo)
        if not hi_toks or not lo_toks:
            continue
        hi_signal = any(t in signal_names and t not in param_names for t in hi_toks)
        lo_signal = any(t in signal_names and t not in param_names for t in lo_toks)
        hi_const = all(_is_const_like(t) for t in hi_toks)
        lo_const = all(_is_const_like(t) for t in lo_toks)
        if hi_signal and lo_signal and not hi_const and not lo_const:
            lineno = src[:m.start()].count('\n') + 1
            findings.append(_mk_advisory(
                path, lineno, 'variable-partselect-illegal-range', '',
                f"part-select [{hi.strip()}:{lo.strip()}] has non-constant "
                f"bounds that resolve to declared signals, not parameters "
                f"— a variable-bounded `[hi:lo]` slice is illegal Verilog; "
                f"use an indexed part-select `<base> +: <CONST_WIDTH>` / "
                f"`<base> -: <CONST_WIDTH>` (runtime base, CONSTANT width) "
                f"instead."))
    return findings


def rule_booth_shift_before_signext(src: str, path: str) -> List[Finding]:
    """Rule 31 (ORGANIC-20260704) — Booth-recoded term shifted before it is
    sign-extended to the full product width.

    `target <= term <<< <shift>;` (an arithmetic left-shift, the Booth
    radix-4 recode-and-shift idiom): if `term`'s own declared width (or, when
    `term` is a function call, the function's own RETURN width) is narrower
    than `target`'s, the sign/overflow bits are lost during the shift before
    the result is ever widened. The golden CVDP `modified_booth_mul` design's
    recoder function already returns the FULL product width, so this never
    fires on it. Fails safe when either width is unresolvable."""
    findings: List[Finding] = []
    dwmap = _decl_width_map(src)
    func_widths = _func_return_width_map(src)
    shift_re = re.compile(
        r'\b([A-Za-z_]\w*)\s*<=\s*'
        r'([A-Za-z_]\w*)\s*(\([^;]*?\))?\s*<<<\s*[\w\'$]+\s*;')
    for m in shift_re.finditer(src):
        target, term, call_args = m.groups()
        tgt_info = dwmap.get(target)
        term_info = func_widths.get(term) if call_args is not None else dwmap.get(term)
        if not _same_base(tgt_info, term_info):
            continue
        if term_info[1] < tgt_info[1]:
            lineno = src[:m.start()].count('\n') + 1
            findings.append(_mk_advisory(
                path, lineno, 'booth-shift-before-signext', target,
                f"'{term}' is arithmetically shifted (`<<<`) into "
                f"'{target}' without first being sign-extended to the full "
                f"product width — a Booth-recoded partial-product term "
                f"must be sign-extended to the FULL product width BEFORE "
                f"the shift, or the sign/overflow bits truncate."))
    return findings


# ---------------------------------------------------------------------------
# A Verilog `input` / `inout` port is a NET; it can never be a `reg` (a driven
# variable). `input reg <p>` / `inout reg <p>` is illegal in strict
# SystemVerilog and ELAB_ERRORs on the official CVDP icarus-13 scorer
#   error: Port <p> of module <m> is declared as input and as a reg type.
# even though some lax host simulators (iverilog-11) tolerate it. Only an
# `output` port may be `reg`. The `reg` keyword on an input/inout is ALWAYS
# removable without semantic change, so `--fix` rewrites `input reg`/`inout reg`
# -> `input`/`inout`. chip-AGNOSTIC: pure Verilog port-direction grammar.
_INPUT_REG_RE = re.compile(r"\b(input|inout)\b[ \t]+reg\b")


def rule_input_port_reg(src: str, path: str) -> List[Finding]:
    findings: List[Finding] = []
    for m in _INPUT_REG_RE.finditer(src):
        lineno = src[:m.start()].count("\n") + 1
        direction = m.group(1)
        findings.append(Finding(
            path, lineno, 'WARN', 'input-port-reg', direction,
            f"an `{direction}` port must never be declared `reg` — a net cannot "
            f"be a driven variable; `{direction} reg` ELAB_ERRORs on icarus-13 "
            f"(the official CVDP scorer). Only `output` ports may be `reg`. "
            f"Write `{direction} [W-1:0] x;` (implicit wire). "
            f"rtl_hygiene_lint --fix removes the redundant `reg`."))
    return findings


def autofix_input_reg_port(path: Path) -> Tuple[int, List[str]]:
    """ORGANIC-20260703 — rewrite `input reg`/`inout reg` -> `input`/`inout`
    in-place. The `reg` keyword on an input/inout port is illegal on icarus-13
    (the CVDP scorer) and ALWAYS removable without semantic change (the port is a
    net either way). Returns (count_fixed, [directions]); no-op (0, []) when
    nothing matches. Only the code before an inline `//` comment is rewritten."""
    raw = path.read_text(errors="replace")
    count = 0
    dirs: List[str] = []
    out_parts: List[str] = []
    for line in raw.splitlines(keepends=True):
        cpos = line.find("//")
        code = line if cpos < 0 else line[:cpos]
        rest = "" if cpos < 0 else line[cpos:]
        for m in _INPUT_REG_RE.finditer(code):
            dirs.append(m.group(1))
        new_code, n = _INPUT_REG_RE.subn(lambda m: m.group(1), code)
        count += n
        out_parts.append(new_code + rest)
    if count:
        path.write_text("".join(out_parts))
    return count, dirs


# ---------------------------------------------------------------------------
# ORGANIC-20260803 — ANSI `output` port re-declared as `reg` in the module body.
#
# In ANSI-2001 / SystemVerilog port style the direction (and any range) live
# INSIDE the port-list parentheses:
#       module m (input clk, output [15:0] p, output rdy);
# that header entry ALREADY declares `p` (implicitly a net). Re-declaring the
# same name in the body as a `reg` is a DUPLICATE declaration and hard-ERRORs on
# every conforming simulator (iverilog 12/14, verilator, the CVDP icarus-13
# scorer):
#       error: 'p' has already been declared in this scope.
#       ...    : It was declared here as a net.
# A registered output is a single object; the ONLY correct rewrite is to promote
# the HEADER entry to `output reg` and DELETE the body `reg` decl (preserving any
# power-up initializer as a standalone `initial NAME = <val>;`).
#
# This is DISTINCT from the legal NON-ANSI idiom, which this rule must NEVER
# touch — there the direction is declared in the BODY, and a separate `reg` is
# the intended storage decl:
#       module m (p, rdy);
#         output [15:0] p;   // direction decl in the BODY (non-ANSI)
#         reg    [15:0] p;   // separate storage decl — LEGAL, no conflict
# The discriminator is strictly POSITIONAL: fire ONLY when the `output` appears
# INSIDE the module port-list parentheses (ANSI) AND the same name is re-declared
# `reg` AFTER the header close-paren. That pair is always a compile error, so the
# repair has zero false positives (a legal design cannot contain it).
# chip-AGNOSTIC: pure Verilog port-direction grammar.
# ---------------------------------------------------------------------------
def _module_port_and_body_spans(text: str) -> List[Tuple[int, int, int]]:
    """Yield (hdr_open_idx, hdr_close_idx, body_end_idx) for each module that
    uses an ANSI/paren port list. body_end is the module's `endmodule` (or EOF).
    Depth-matched so nested parens (`#( ... )` params, nested concats) are safe."""
    ends = [m.end() for m in re.finditer(r'\bendmodule\b', text)]
    spans: List[Tuple[int, int, int]] = []
    for hm in re.finditer(r'\bmodule\b\s+\w+\s*(?:#\s*\([^)]*\)\s*)?\(', text):
        depth, i = 0, hm.end() - 1
        op = i
        while i < len(text):
            c = text[i]
            if c == '(':
                depth += 1
            elif c == ')':
                depth -= 1
                if depth == 0:
                    break
            i += 1
        cp = i
        body_end = next((e for e in ends if e > cp), len(text))
        spans.append((op, cp, body_end))
    return spans


def _find_output_reg_redecls(text: str) -> List[Dict[str, object]]:
    """Return one dict per ANSI `output` port illegally re-declared as `reg` in
    the body (the 'already declared' compile error). Empty list on legal code."""
    hits: List[Dict[str, object]] = []
    for (op, cp, body_end) in _module_port_and_body_spans(text):
        header = text[op + 1:cp]
        hbase = op + 1
        body = text[cp + 1:body_end]
        bbase = cp + 1
        # ANSI output port, one name per `output` keyword, NOT already reg/wire/
        # logic (those are correct or non-conflicting).
        for m in re.finditer(
                r'\boutput\b(?!\s+(?:reg|wire|logic))\s*(?:signed\s+)?'
                r'(?:\[[^\]]+\]\s*)?([A-Za-z_]\w*)', header):
            name = m.group(1)
            if name in VERILOG_KEYWORDS:
                continue
            reg_re = re.compile(
                r'\breg\b\s*(?:signed\s+)?(?:\[[^\]]+\]\s*)?'
                + re.escape(name) + r'\b\s*(=\s*[^;]*?)?\s*;')
            bm = reg_re.search(body)
            if not bm:
                continue
            hits.append({
                'name': name,
                'hdr_start': hbase + m.start(),
                'hdr_end': hbase + m.end(),
                'hdr_text': m.group(0),
                'body_start': bbase + bm.start(),
                'body_end': bbase + bm.end(),
                'init': (bm.group(1) or '').strip(),  # e.g. "= 8'b0" or ""
                'lineno': text[:hbase + m.start()].count('\n') + 1,
            })
    return hits


def rule_output_port_reg_redeclared(src: str, path: str) -> List[Finding]:
    findings: List[Finding] = []
    for h in _find_output_reg_redecls(src):
        name = h['name']
        findings.append(Finding(
            path, int(h['lineno']), 'ERROR', 'output-port-reg-redeclared', str(name),
            f"ANSI `output {name}` in the port list is ALSO re-declared `reg "
            f"{name};` in the body — a duplicate declaration that ELAB_ERRORs "
            f"('{name}' has already been declared in this scope). A registered "
            f"output is one object: write `output reg [W-1:0] {name}` in the "
            f"header and delete the body `reg`. rtl_hygiene_lint --fix repairs "
            f"this deterministically (init preserved as `initial {name}=…;`)."))
    return findings


def autofix_output_reg_redeclared(path: Path) -> Tuple[int, List[str]]:
    """ORGANIC-20260803 — repair an ANSI `output` port re-declared as `reg` in
    the body. Promotes the header entry to `output reg` and removes the body
    `reg` decl, preserving any power-up initializer as a standalone `initial`.
    Returns (count_fixed, [names]); no-op (0, []) when nothing matches.
    chip-AGNOSTIC; zero false positives (the pattern is always a compile error)."""
    text = path.read_text(errors='replace')
    hits = _find_output_reg_redecls(text)
    if not hits:
        return 0, []
    edits: List[Tuple[int, int, str]] = []
    names: List[str] = []
    for h in hits:
        names.append(str(h['name']))
        # promote the header entry: `output` -> `output reg`
        new_hdr = re.sub(r'\boutput\b', 'output reg', str(h['hdr_text']), count=1)
        edits.append((int(h['hdr_start']), int(h['hdr_end']), new_hdr))
        # body reg decl: delete, or keep power-up value as a standalone initial
        init = str(h['init'])
        repl = f"initial {h['name']} {init};" if init else ""
        edits.append((int(h['body_start']), int(h['body_end']), repl))
    for (s, e, r) in sorted(edits, key=lambda x: x[0], reverse=True):
        text = text[:s] + r + text[e:]
    path.write_text(text)
    return len(hits), names


# ---------------------------------------------------------------------------
# Rule 34 — simulation oscillator delayed blocking self-toggle
# ---------------------------------------------------------------------------
# A no-input clock/oscillator model commonly toggles an output on an exact delay:
#
#     initial begin clk = 0; forever #5 clk = ~clk; end
#
# A testbench sampling at the SAME timestamp races the blocking write in the
# active region.  ``clk <= ~clk`` schedules the transition in the NBA region,
# preserving the intended half-period waveform while making sampling order
# deterministic.  This is NOT a blanket blocking→NBA rewrite: the detector is
# confined to an unsynthesizable no-input module, an output that self-toggles
# after ``#delay`` inside ``initial/forever`` or a bare ``always``, and exactly
# one separate literal initialization.  Ordinary combinational and edge-clocked
# synthesizable assignments cannot match.
_DELAYED_BLOCKING_SELF_TOGGLE_RE = re.compile(
    r'#\s*(?:\([^;]*?\)|(?:\d+(?:\.\d+)?|[A-Za-z_]\w*))\s*'
    r'(?P<name>[A-Za-z_]\w*)\s*(?P<op>(?<![<>=!])=(?!=))\s*'
    r'~\s*(?P=name)\s*;', re.S)
_BARE_ALWAYS_RE = re.compile(r'(?<![\w$])always(?![\w$])')
_FOREVER_RE = re.compile(r'(?<![\w$])forever(?![\w$])')


def _blank_preprocessor_conditionals(src: str) -> str:
    """Blank every conditional-compilation branch without shifting offsets.

    This autofixer has no access to the simulator/synthesizer's ``-D`` macro
    environment.  Treating a branch as active would therefore be a guess, and
    procedural keywords in an inactive (even syntactically incomplete) branch
    can lend false scope to live code after `` `endif``.  Exclude the complete
    conditional region, including nested branches, and leave unconditional
    source available to the rule.  This is deliberately fail-closed: a real
    oscillator behind a macro is left untouched rather than rewritten under an
    unproved configuration.
    """
    out: List[str] = []
    depth = 0
    continuation = False
    conditional_open = re.compile(r'^\s*`(?:ifdef|ifndef)\b')
    conditional_close = re.compile(r'^\s*`endif\b')
    directive = re.compile(r'^\s*`[A-Za-z_]\w*')

    for line in src.splitlines(keepends=True):
        opens = bool(conditional_open.match(line))
        closes = bool(conditional_close.match(line))
        hidden = depth > 0 or opens or closes or continuation \
            or bool(directive.match(line))
        if hidden:
            out.append(''.join('\n' if ch == '\n' else '\r' if ch == '\r'
                               else ' ' for ch in line))
        else:
            out.append(line)

        if opens:
            depth += 1
        if closes and depth > 0:
            depth -= 1
        continuation = (bool(directive.match(line)) or continuation) \
            and line.rstrip('\r\n').rstrip().endswith('\\')

    return ''.join(out)


def _bare_always_spans(src: str) -> List[Tuple[int, int]]:
    """Return bounded spans for delay-driven ``always`` statements only."""
    spans: List[Tuple[int, int]] = []
    for m in _BARE_ALWAYS_RE.finditer(src):
        nxt = re.search(r'\S', src[m.end():])
        if not nxt:
            continue
        body_start = m.end() + nxt.start()
        if src[body_start] == '@':
            continue
        body, end = _statement_after(src, m.end())
        if body:
            spans.append((m.start(), end))
    return spans


def _forever_spans(src: str) -> List[Tuple[int, int]]:
    """Return bounded spans for each ``forever`` statement body."""
    spans: List[Tuple[int, int]] = []
    for m in _FOREVER_RE.finditer(src):
        body, end = _statement_after(src, m.end())
        if body:
            spans.append((m.start(), end))
    return spans


def _delayed_blocking_clock_toggle_sites(raw: str, path: str = "") -> List[Dict]:
    """Return conservative delayed self-toggle sites with raw-text offsets."""
    if _is_testbench(raw, path):
        return []
    scan = _blank_preprocessor_conditionals(strip_comments(raw))
    sites: List[Dict] = []
    for _module_name, lo, hi in _module_regions(scan):
        region = scan[lo:hi]
        structural = _blank_string_literals(region)
        # This rule models a source/oscillator, not a DUT clocked by an input.
        if re.search(r'\binput\b', structural):
            continue
        initial_spans = _initial_spans(structural)
        bare_always_spans = _bare_always_spans(structural)
        forever_spans = _forever_spans(structural)
        for m in _DELAYED_BLOCKING_SELF_TOGGLE_RE.finditer(structural):
            name = m.group('name')
            # The toggled signal must be a module output (ANSI or body style).
            if not re.search(r'\boutput\b[^;)]*\b' + re.escape(name) + r'\b',
                             structural, re.S):
                continue

            # The toggle must be structurally INSIDE the qualifying process.
            # Looking only for the last preceding `initial`/`always` leaked
            # across completed blocks and into task bodies, where `--fix`
            # changed unrelated delayed assignments.  Bound each process first.
            in_initial_forever = (
                any(start <= m.start() < end for start, end in initial_spans)
                and any(
                    start <= m.start() < end
                    # A forever loop that waits on an event before this toggle
                    # is event-driven, not the delay-only oscillator class.
                    # An unresolved macro in the same prefix may expand to the
                    # event control, so it is equally non-rewritable.
                    and '@' not in structural[start:m.start()]
                    and '`' not in structural[start:m.start()]
                    for start, end in forever_spans))
            in_bare_always = any(
                start <= m.start() < end
                and '@' not in structural[start:m.start()]
                # Without the caller's macro environment, a backtick token in
                # the owning `always` prefix may expand to an event control
                # (for example `EVENT -> @(posedge clk)`).  Rewriting in that
                # state would guess that an event-driven process is a free-
                # running oscillator, so leave it untouched.
                and '`' not in structural[start:m.start()]
                for start, end in bare_always_spans)
            if not (in_initial_forever or in_bare_always):
                continue

            writes = list(re.finditer(
                r'\b' + re.escape(name) +
                r'\b\s*(?:<=|(?<![<>=!])=(?!=))', structural))
            if len(writes) != 2:
                continue
            # The only other write must be a literal initialization before the
            # toggle.  Extra functional/reset writes make the rewrite ambiguous.
            literal_inits = list(re.finditer(
                r'\b' + re.escape(name) +
                r"\b\s*=\s*(?:\d+'[sS]?[bBoOdDhH][0-9a-fA-FxXzZ_]+|\d+)\s*;",
                structural))
            if len(literal_inits) != 1 or literal_inits[0].start() >= m.start():
                continue
            sites.append({
                'name': name,
                'op_start': lo + m.start('op'),
                'op_end': lo + m.end('op'),
                'line': scan.count('\n', 0, lo + m.start('op')) + 1,
            })
    return sites


def rule_delayed_blocking_clock_toggle(src: str, path: str) -> List[Finding]:
    return [Finding(
        path, int(site['line']), 'WARN',
        'delayed-blocking-clock-toggle', str(site['name']),
        "delay-driven no-input oscillator uses a blocking self-toggle; a "
        "testbench sampling at the same timestamp races the active-region "
        "write. Use `<=` for the delayed toggle (rtl_hygiene_lint --fix).")
        for site in _delayed_blocking_clock_toggle_sites(src, path)]


def autofix_delayed_blocking_clock_toggle(path: Path) -> Tuple[int, List[str]]:
    """Change only proven delay-oscillator self-toggle operators from = to <=."""
    raw = path.read_text(errors='replace')
    sites = _delayed_blocking_clock_toggle_sites(raw, str(path))
    if not sites:
        return 0, []
    for site in sorted(sites, key=lambda item: int(item['op_start']), reverse=True):
        start, end = int(site['op_start']), int(site['op_end'])
        raw = raw[:start] + '<=' + raw[end:]
    path.write_text(raw)
    return len(sites), [str(site['name']) for site in sites]


def lint_file(path: Path) -> List[Finding]:
    raw = path.read_text(errors='replace')
    src = strip_comments(raw)
    results = []
    results += rule_input_port_reg(src, str(path))
    results += rule_output_port_reg_redeclared(src, str(path))
    results += rule_delayed_blocking_clock_toggle(src, str(path))
    results += rule_undriven_and_unread(src, str(path))
    results += rule_case_coverage(src, str(path))
    results += rule_if_no_else_latch(src, str(path))
    results += rule_pulse_swallow(src, str(path))
    results += rule_uninit_registered_output(src, str(path))
    results += rule_undriven_output_port(src, str(path))
    results += rule_incomplete_sensitivity(src, str(path))
    results += rule_vector_self_shift_fold(src, str(path))
    results += rule_reserved_word_identifier(src, str(path))
    results += rule_unguarded_sim_only_assert(raw, str(path))
    results += rule_reset_boundary_residual_enable(src, str(path))
    results += rule_multidriven_register(src, str(path))
    results += rule_continuous_vs_procedural_driver(src, str(path))
    results += rule_divmod_by_zero_const(src, str(path))
    results += rule_assign_width_truncate(src, str(path))
    results += rule_array_reset_loop_idiom(src, str(path))
    results += rule_width_expand_trunc(src, str(path))
    results += rule_unused_clock_input(src, str(path))
    results += rule_bitwise_not_width(src, str(path))
    results += rule_enum_ternary_width(src, str(path))
    results += rule_mixed_blocking_same_reg(src, str(path))
    results += rule_narrow_bitwise_not_wider_context(src, str(path))
    results += rule_use_before_declaration(src, str(path))
    # Rules 26-31 (ORGANIC-20260704) — advisory-only arithmetic-datapath
    # structural rules; every finding is severity INFO / block_eligible=False
    # (see _mk_advisory), so enabling them cannot change any gate's rc.
    results += rule_divider_missing_final_correction(src, str(path))
    results += rule_multiop_arith_width_consistency(src, str(path))
    results += rule_cascaded_decrement_priority_order(src, str(path))
    results += rule_seq_multiplier_width(src, str(path))
    results += rule_variable_partselect_illegal_range(src, str(path))
    results += rule_booth_shift_before_signext(src, str(path))
    # rule_wire_input_read_in_clocked_block: NOT enabled.
    #
    # v0.1.39 honesty correction (audit Finding 2): the v0.1.38 disable
    # comment claimed "5 false-positives on 362-sample corpus" — that
    # count was from a transient corpus including IN-FLIGHT (still being
    # authored) RTLLM Shape-B samples that the agent later rewrote. A
    # clean re-sweep against the 362 PASSing reference corpus (156 v2 +
    # 156 Human refs + 50 RTLLM `verified_*.v`) shows ZERO false
    # positives — the rule never fires on the reference set at all.
    #
    # Honest reason to keep this disabled: zero FPs on the reference
    # corpus could mean the rule is correct AND no reference uses the
    # pattern, OR it could mean the rule pattern is too narrow to fire
    # on most real code. The synthetic test (test_rule9.v) demonstrates
    # the rule CAN fire on the genuine bug, but the corpus is silent. A
    # rule that's correct but never fires adds noise (false confidence
    # in lint cleanliness) without catching anything. Keep disabled
    # until either:
    #   (a) an extended corpus shows the rule fires on a real-world bug
    #       (rule is justified at WARN), OR
    #   (b) the bug class is provably absent from typical RTL (rule is
    #       removed as unnecessary).
    #
    # The pattern lives as an anonymized Bucket-B worked example in
    # agents/ic-expert-agent.md — AI judgment can still apply it, but the
    # deterministic rule isn't claiming general safety until verified.
    return results


def autofix_uninit_registered_output(path: Path) -> Tuple[int, List[str]]:
    """Deterministically REPAIR the `uninit-registered-output` finding in-place.

    For every reset-less registered output with no power-up value, insert a
    separate `initial <name> = 0;` block just before the module's `endmodule`
    (Verilator-PROCASSINIT-clean, unlike a decl initializer). This makes the
    power-up-determinism lesson ENFORCED by the tool rather than dependent on a
    caller / prompt remembering to apply it (the v0.1.24 lesson: a fix that lives
    only in a free-text instruction is a fix you can typo). chip-AGNOSTIC, safe:
    only fires on the conservative reset-less / no-init case, and a redundant
    `initial 0` on a never-reset DFF is harmless for sim/FPGA and ignored on ASIC.

    Returns (count_fixed, [names]). No-op (0, []) if nothing to fix.
    """
    raw = path.read_text(errors='replace')
    src = strip_comments(raw)
    # v0.1.40 (re-audit NEW-1 fix) — restrict analysis to the TOP MODULE only.
    # The autofix inserts the `initial` block before the file's LAST
    # `endmodule`, which is the top module's. For single-module files this is a
    # no-op refinement. For multi-module files (e.g. RTLLM asyn_fifo, which
    # contains a `dual_port_RAM` submodule above the top), scanning the whole
    # file flatly would:
    #   • pull a name that's a `reg` in the submodule but a `wire` in the top
    #     module → `initial wire_name = 0;` → iverilog "not a valid l-value"
    #   • pull a memory array `reg [W-1:0] MEM [0:D-1]` from the submodule and
    #     emit it as a scalar `MEM = 0;` → iverilog "Could not find variable"
    # Scope the search to the top module's body to eliminate both classes.
    top_body, top_start = _extract_top_module_body(src)
    src_scope = top_body if top_body is not None else src
    # v0.2.55 — mask generate-block bodies for ALL cases (a)/(b)/(c), not just
    # (c). A reg declared inside `generate ... endgenerate` (or a `for`-genvar
    # loop) has generate-block scope and CANNOT be referenced by a module-scope
    # `initial begin name = 0; end` block (iverilog: "Could not find variable").
    # Cases (a)/(b) used to scan the UNMASKED scope and so picked up SERV's
    # generate-scoped registered outputs (serv_state cnt_lsb/cnt_en,
    # serv_immdec imm19_12_20/...) — the autofix then emitted broken initial
    # refs that failed elaboration. chip-AGNOSTIC: structural masking only.
    src_scope_nogen = _mask_generate_blocks(src_scope)
    names: List[str] = []
    seen: Set[str] = set()
    # (a) registered OUTPUT ports with no power-up (the WARN-rule set).
    # ORGANIC #783 — skip ADVISORY (non-block-eligible) findings: a
    # valid-gated FSM-terminal output is intentionally power-up-X, and forcing
    # `initial 0` would DIVERGE it from a spec-faithful / golden reference
    # (X vs 0) on equivalence/area-opt tasks. Only AUTOFIX a genuine hard-block.
    for f in rule_uninit_registered_output(src_scope_nogen, str(path)):
        if (f.rule == 'uninit-registered-output' and f.block_eligible
                and f.symbol not in seen):
            names.append(f.symbol); seen.add(f.symbol)
    # ORGANIC #727 — signals structurally assigned under a reset condition
    # (single mixed reset+datapath block included). Never give a reset-covered
    # signal a redundant `initial 0`: it already has a deterministic power-up
    # value, and a module whose only reset port is spelled outside the
    # reset-name detector (e.g. APB `presetn`) would otherwise be treated as
    # reset-less by cases (b)/(c) and false-fixed.
    reset_covered_fix = _reset_covered_signals(src_scope_nogen)
    # (b) INTERNAL registered regs that drive a module output via a continuous
    #     assign (e.g. `reg q; ... q<=...; assign out=q;`). Same power-up-X bug,
    #     just one hop removed. Reset-less modules only.
    input_decls = ' '.join(re.findall(r'\binput\b[^;)\n]*', src_scope))
    is_resetless = not _RESET_NAME_RE.search(input_decls)
    # v0.1.40 — also collect TOP-SCOPE wire names so case (c) can skip names
    # that are wires in this module (even if the same name is a reg in a
    # sibling submodule that lives in the same file).
    top_wires = set(re.findall(
        r'\b(?:wire|output\s+wire|input\s+wire|inout\s+wire)\b(?:\s+signed)?\s*'
        r'(?:\[[^\]]+\]\s*)?([A-Za-z_]\w*)\s*(?=[,;)=])', src_scope))
    if is_resetless:
        out_ports = set(re.findall(
            r'\boutput\b\s+(?:(?:reg|logic|wire)\s+)?(?:signed\s+)?(?:\[[^\]]+\]\s*)?'
            r'([A-Za-z_]\w*)\s*(?=[,;)=])', src_scope))
        # v0.2.55 — `registered` from the GENERATE-MASKED scope so generate-
        # scoped regs (whose `<=` lives inside a generate body) are NOT eligible
        # for a module-scope `initial` (they would fail elaboration).
        registered = {mm.group(1) for mm in
                      re.finditer(r'(?<![<>!=])\b(\w+)(?:\[[^\]]+\])?\s*<=', src_scope_nogen)}
        has_initial = bool(re.search(r'\binitial\b', src_scope))
        for om in re.finditer(r'\bassign\s+([A-Za-z_]\w*)\s*=\s*([^;]+);', src_scope):
            if om.group(1) not in out_ports:
                continue
            for rhs_id in re.findall(r'\b([A-Za-z_]\w*)\b', om.group(2)):
                if rhs_id in registered and rhs_id not in seen \
                        and rhs_id not in VERILOG_KEYWORDS \
                        and rhs_id not in top_wires \
                        and rhs_id not in reset_covered_fix:
                    # #530 — memory-array guard (case (c) already has it):
                    # an unpacked array RHS (reg [W-1:0] mem [0:D-1]) must
                    # never receive the scalar `initial mem = 0;` autofix —
                    # icarus cannot elaborate a whole-array assignment, so
                    # the enforced --fix would BREAK a correct design.
                    is_mem_array = re.search(
                        r'\b(?:reg|logic)\b[^;\n]*\b' + re.escape(rhs_id)
                        + r'\s*\[[^\]]+\]\s*[;,]', src_scope)
                    if is_mem_array:
                        continue
                    decl_init = re.search(
                        r'\b(?:reg|logic)\b[^;\n]*\b' + re.escape(rhs_id) + r'\s*=', src_scope)
                    in_initial = has_initial and re.search(
                        r'\binitial\b[\s\S]{0,200}?\b' + re.escape(rhs_id) + r'\s*(<=|=)', src_scope)
                    if not decl_init and not in_initial:
                        names.append(rhs_id); seen.add(rhs_id)
    # (c) v0.1.38 — ALL internal `reg` declarations in reset-less modules.
    # v0.1.40 — top-module-scoped; skip memory arrays; skip names that are
    # wires in this module's scope.
    # v0.1.41 — also skip regs declared inside `generate ... endgenerate`
    # blocks; those have generate-block scope (e.g. g[i].local_reg) and
    # cannot be referenced by an `initial begin local_reg = 0; end` block
    # at module scope (iverilog: "Could not find variable").
    if is_resetless:
        # Mask out generate-block bodies so the reg/wire/registered scans
        # don't see them. Replacement preserves character offsets for any
        # caller that re-resolves line numbers.
        src_no_gen = _mask_generate_blocks(src_scope)
        all_regs: Dict[str, int] = {}
        # v0.1.40 — match `reg [...] name1, name2;` OR `reg name [0:D-1];`
        # (memory) — the memory form is REJECTED at the per-name walk by the
        # trailing-`[…]` test.
        for m in re.finditer(
                r'\breg\b(?:\s+signed)?\s*(?:\[[^\]]+\]\s*)?([^;]+);', src_no_gen):
            lineno_d = src_no_gen[:m.start()].count('\n') + 1
            decl_body = m.group(1)
            # Walk the comma-separated names; reject any name whose decl has
            # a trailing `[...]` (memory array) — those need element-wise init
            # via an integer loop, which the scalar `name = 0;` autofix would
            # mis-emit as `MEM = 0;` (iverilog: 'Could not find variable').
            for nm_match in re.finditer(
                    r'([A-Za-z_]\w*)\s*(\[[^\]]+\])?\s*(?:=[^,;]+)?', decl_body):
                nm = nm_match.group(1)
                trailing_bracket = nm_match.group(2)
                if not nm or nm in VERILOG_KEYWORDS or nm in all_regs:
                    continue
                if trailing_bracket:
                    # memory array — skip; element-wise init is out of scope
                    # for this autofix (would need an integer loop).
                    continue
                all_regs[nm] = lineno_d
        registered = {mm.group(1) for mm in
                      re.finditer(r'(?<![<>!=])\b(\w+)(?:\[[^\]]+\])?\s*<=', src_no_gen)}
        has_initial = bool(re.search(r'\binitial\b', src_no_gen))
        for nm in all_regs:
            if nm in seen or nm not in registered or nm in top_wires \
                    or nm in reset_covered_fix:
                continue
            decl_init = re.search(
                r'\breg\b[^;\n]*\b' + re.escape(nm) + r'\s*=', src_no_gen)
            in_initial = has_initial and re.search(
                r'\binitial\b[\s\S]{0,200}?\b' + re.escape(nm) + r'\s*(<=|=)', src_no_gen)
            if decl_init or in_initial:
                continue
            names.append(nm); seen.add(nm)
    if not names:
        return 0, []
    # v0.1.41 (re-re-audit Issue 2 fix) — `rfind('endmodule')` must run on
    # the COMMENT-STRIPPED source so a trailing `// endmodule in a note`
    # comment doesn't poison the lookup. Conveniently, `strip_comments`
    # preserves character offsets (it replaces comment characters with
    # spaces and keeps newlines), so the offset in stripped IS the offset
    # in raw — no translation needed. The rstrip() also dissolves the
    # trailing comment-as-spaces so rfind lands on the real endmodule.
    src_stripped = strip_comments(raw)
    idx = src_stripped.rstrip().rfind('endmodule')
    if idx < 0:
        return 0, []
    block = "\n  // power-up determinism (rtl_hygiene_lint --fix): reset-less registered\n"
    block += "  // outputs default to 0 so they are not X at t=0.\n  initial begin\n"
    block += "".join(f"    {n} = 0;\n" for n in names)
    block += "  end\n\n"
    patched = raw[:idx] + block + raw[idx:]
    path.write_text(patched)
    return len(names), names


def _mask_generate_blocks(src: str) -> str:
    """v0.1.41 (re-re-audit Issue 1 fix) — replace every `generate ... endgenerate`
    block body with whitespace of equal length, so the caller's regex scans
    don't pick up regs declared inside generate-scope. Character offsets are
    preserved so any caller computing line numbers still gets the right answer.

    A more sophisticated solution would track per-block reg scope, but for
    the autofix's purpose (emit a module-scope `initial begin … end`), regs
    inside `generate` are simply not addressable from module scope and must
    be excluded from the candidate set.
    """
    out = list(src)
    depth = 0
    block_start = -1
    for m in re.finditer(r'\b(generate|endgenerate)\b', src):
        if m.group(1) == 'generate':
            if depth == 0:
                block_start = m.end()
            depth += 1
        else:  # endgenerate
            depth -= 1
            if depth == 0 and block_start >= 0:
                # Replace block_start..m.start() with spaces (preserve newlines).
                for i in range(block_start, m.start()):
                    if out[i] != '\n':
                        out[i] = ' '
                block_start = -1
    return "".join(out)


def _extract_top_module_body(src: str):
    """v0.1.40 (re-audit NEW-1 fix) — return the (text, start_offset) for the
    TOP module (its `endmodule` is the file's LAST `endmodule`). Returns
    (None, None) on parse failure — caller falls back to the whole-file source.

    Includes the module HEADER (declaration + port list) so the reset detector
    sees ANSI-style `input rst_n` inside the port list. Verilog disallows
    nested modules, so 'last `module …` declaration before the last `endmodule`'
    is the correct top-module opener.
    """
    last_endmod = src.rstrip().rfind('endmodule')
    if last_endmod < 0:
        return None, None
    last_mod_decl = -1
    for m in re.finditer(r'\bmodule\b\s+[A-Za-z_]\w*', src[:last_endmod]):
        last_mod_decl = m.start()
    if last_mod_decl < 0:
        return None, None
    return src[last_mod_decl:last_endmod], last_mod_decl


def main():
    ap = argparse.ArgumentParser(description='General RTL hygiene lint.')
    ap.add_argument('files', nargs='+', help='Verilog/SystemVerilog files')
    ap.add_argument('--json', help='Write findings as JSON to this path')
    ap.add_argument('--severity', choices=['ERROR', 'WARN', 'INFO'], default='INFO',
                    help='Minimum severity to report (default: INFO)')
    ap.add_argument('--fix', action='store_true',
                    help='Deterministically repair in-place: (a) the '
                         'uninit-registered-output finding (insert `initial <reg>=0;`), '
                         'enforcing the power-up determinism lesson; and (b) the '
                         'unguarded-sim-only-assert finding (fence immediate `assert` '
                         'statements in `// synthesis translate_off … translate_on` so '
                         'they stop false-failing the synth gate); and (c) a narrowly '
                         'proven delay-driven no-input oscillator blocking self-toggle '
                         '(rewrite `=` to `<=` to remove active-region sampling races). '
                         'Regardless of caller/prompt.')
    ap.add_argument('--strict', action='store_true',
                    help='ORGANIC #770 — sole-emit hard-block mode. Identical '
                         'gating to the default (an ADVISORY prose-heuristic '
                         'finding never hard-blocks; only a BLOCK-eligible '
                         'finding trips rc=1); accepted for vocabulary parity '
                         'with the sibling --strict gates.')
    args = ap.parse_args()

    if args.fix:
        # ORGANIC #533 — compile-neutrality safety net (guard-the-guard).
        # #530 fixed two SPECIFIC fixer bugs that broke a compiling design;
        # this is the STRUCTURAL net for every FUTURE fixer bug: when the
        # file compiled BEFORE the fix, it must still compile AFTER —
        # otherwise revert everything and WARN. A pre-broken file is fixed
        # as usual (no revert — the fixer is not what broke it). Skipped
        # silently when iverilog is unavailable (the net needs a verifier).
        import shutil as _sh
        import subprocess as _sp
        _iv = _sh.which("iverilog")

        def _compiles(fp: Path) -> bool:
            # -i ignores missing submodules so the net also protects
            # hierarchical/multi-file RTL (review round-2: a file
            # instantiating an elsewhere-defined submodule failed the
            # standalone pre-compile and silently disarmed the net);
            # genuine fixer breakage (e.g. an `initial` referencing a
            # generate-scoped reg) is an elaboration error -i does NOT
            # suppress, so the net still catches real bugs.
            try:
                return _sp.run([_iv, "-g2012", "-i", "-t", "null", str(fp)],
                               capture_output=True, timeout=120
                               ).returncode == 0
            except Exception:
                return False

        total = 0
        guarded_total = 0
        cast_total = 0
        inreg_total = 0
        sens_total = 0
        outreg_total = 0
        clock_toggle_total = 0
        for f in args.files:
            p = Path(f)
            if not p.exists():
                print(f"WARNING: file not found: {f}", file=sys.stderr)
                continue
            pre_text = p.read_text(errors="replace")
            pre_ok = _compiles(p) if _iv else False
            # ORGANIC-20260703 — repair an input/inout port illegally declared
            # `reg` (uncompilable on the icarus-13 CVDP scorer) BEFORE the other
            # fixers; the `reg` on a net is always removable without semantics.
            ir, irdirs = autofix_input_reg_port(p)
            if ir:
                print(f"{f}: removed illegal `reg` from {ir} input/inout "
                      f"port(s): {irdirs}")
            # ORGANIC-20260803 — repair an ANSI `output` port re-declared as
            # `reg` in the body (the 'already declared' duplicate-decl compile
            # error). Runs alongside the input/inout repair; both are pure
            # port-grammar rewrites with zero semantic change.
            orr, orrnames = autofix_output_reg_redeclared(p)
            if orr:
                print(f"{f}: promoted {orr} ANSI output port(s) to `output reg` "
                      f"(removed duplicate body `reg`): {orrnames}")
            n, names = autofix_uninit_registered_output(p)
            if n:
                print(f"{f}: inserted `initial` power-up 0 for {names}")
            # Run the sim-only-assert fence AFTER the power-up fix (the latter
            # appends an `initial` block before endmodule; order is independent).
            g, glabels = autofix_guard_sim_only_assert(p)
            if g:
                print(f"{f}: fenced sim-only assertion(s) in translate_off guard: {glabels}")
            # Value-identical width casts (Rule 17): silence verilator
            # WIDTHEXPAND/WIDTHTRUNC without changing behaviour.
            w, wlabels = autofix_width_cast(p)
            if w:
                print(f"{f}: inserted value-identical width cast(s): {wlabels}")
            # Incomplete-sensitivity race: rewrite a combinational `always @(<list>)`
            # that reads an unlisted signal to `always @(*)` (value-preserving).
            s, slabels = autofix_incomplete_sensitivity(p)
            if s:
                print(f"{f}: rewrote incomplete sensitivity list(s) to @(*): {slabels}")
            # Delay-driven no-input oscillator: NBA preserves the half-period
            # waveform and removes same-timestamp active-region sampling races.
            ct, ctlabels = autofix_delayed_blocking_clock_toggle(p)
            if ct:
                print(f"{f}: rewrote delayed oscillator self-toggle(s) to NBA: "
                      f"{ctlabels}")
            if _iv and pre_ok and (ir or orr or n or g or w or s or ct) and not _compiles(p):
                p.write_text(pre_text)
                ir = orr = n = g = w = s = ct = 0
                print(f"WARN fix-reverted-noncompiling: {f} compiled before "
                      f"--fix but not after; ALL fixes reverted (#533 "
                      f"compile-neutrality net — file a backlog with this "
                      f"file as the repro)", file=sys.stderr)
            total += n
            guarded_total += g
            cast_total += w
            inreg_total += ir
            sens_total += s
            outreg_total += orr
            clock_toggle_total += ct
        print(f"rtl_hygiene_lint --fix: repaired {total} reset-less registered output(s), "
              f"fenced {guarded_total} sim-only assertion construct(s), "
              f"inserted {cast_total} value-identical width cast(s), "
              f"removed illegal `reg` from {inreg_total} input/inout port(s), "
              f"promoted {outreg_total} duplicate-declared output port(s) to `output reg`, "
              f"rewrote {sens_total} incomplete sensitivity list(s) to @(*), "
              f"rewrote {clock_toggle_total} delayed oscillator self-toggle(s) to NBA")
        return 0

    sev_order = {'ERROR': 2, 'WARN': 1, 'INFO': 0}
    min_sev = sev_order[args.severity]

    all_findings: List[Finding] = []
    for f in args.files:
        p = Path(f)
        if not p.exists():
            print(f"WARNING: file not found: {f}", file=sys.stderr)
            continue
        try:
            all_findings += lint_file(p)
        except Exception as e:
            print(f"ERROR parsing {f}: {e}", file=sys.stderr)
            return 2

    filtered = [f for f in all_findings if sev_order[f.severity] >= min_sev]

    # Text report
    err = sum(1 for f in filtered if f.severity == 'ERROR')
    warn = sum(1 for f in filtered if f.severity == 'WARN')
    info = sum(1 for f in filtered if f.severity == 'INFO')
    print(f"rtl_hygiene_lint: {err} errors, {warn} warnings, {info} info")
    print("-" * 70)
    for fd in sorted(filtered, key=lambda x: (x.file, x.line, x.severity)):
        # ORGANIC #770 round-2 — an ADVISORY (non-block-eligible) finding is
        # printed with an explicit [ADVISORY — …] suffix so it stays visible in
        # the report without contributing to the rc=1 / sole-emit BLOCK set.
        suffix = "" if fd.block_eligible else f"  [ADVISORY — {fd.advisory_note}]"
        print(f"{fd.file}:{fd.line}: [{fd.severity}] {fd.rule}: {fd.message}{suffix}")

    if args.json:
        atomic_write_text(Path(args.json), json.dumps([asdict(f) for f in filtered], indent=2))

    # ORGANIC #770 round-2 — only a BLOCK-eligible finding hard-blocks (trips
    # rc=1). A STRUCTURAL / corroborated finding (a genuine bug) stays
    # block-eligible and still blocks; a downgraded prose-heuristic finding is
    # advisory only.
    #
    # ORGANIC #777 — the block set is computed from `filtered` (the same
    # ≥ --severity set that stdout + the --json artifact use), NOT `all_findings`.
    # #770-r2 (166e6aa05) sourced this from `all_findings`, which is
    # severity-INDEPENDENT: at `--severity ERROR` (the canonical Step-2 lint
    # gate) a block-eligible WARN was filtered OUT of stdout+JSON yet STILL
    # tripped rc=1 — an INVISIBLE FAIL ('0 errors, 0 warnings, 0 info' + JSON
    # '[]' + rc=1) that cascade-blocked ~25 downstream steps with zero evidence.
    # Sourcing from `filtered` makes rc=1 ALWAYS correspond to a printed + JSON'd
    # finding. §4.05 (this relaxes a gate): a real ERROR at --severity ERROR is
    # in `filtered` → still rc=1 + visible; a block-eligible WARN at
    # --severity WARN is in `filtered` → still rc=1 + visible. Only the
    # below-threshold + invisible combination stops tripping a silent rc=1.
    blocking = [f for f in filtered
                if f.block_eligible and f.severity in ('ERROR', 'WARN')]
    return 1 if blocking else 0


if __name__ == '__main__':
    sys.exit(main())
